baseCss:
/* Shared base for every game. Layout: the app is pinned to the visible viewport (phone keyboards never hide it);
   HUD on top, the game's main area takes the rest and scrolls inside itself if it must, never the page. */
:root{
  --stage:#6A3DF0;      /* the stage colour; each game sets its own */
  --on:#FFFFFF;         /* text on the stage colour */
  --ink:#160B33;
  --gold:#F5B700;
  --green:#138A3D;      /* correct only */
  --err:#E5483C;        /* badge dot only */
  --glass:rgba(255,255,255,.17);
  --glass-2:rgba(255,255,255,.26);
  --shade:rgba(22,11,51,.24);
  --display:ui-rounded,"SF Pro Rounded","Nunito","Varela Round",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  --body:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,system-ui,sans-serif;
  color-scheme:dark;
}
html{height:100%;box-sizing:border-box}
*,*::before,*::after{box-sizing:inherit}
body{height:100%;margin:0;background:var(--stage);color:var(--on);font-family:var(--body);overflow:hidden;-webkit-tap-highlight-color:transparent;overscroll-behavior:none}
[hidden]{display:none!important}
.overlay{align-items:start!important}.overlay>.sheet{margin-block:auto}
button,input{font:inherit;color:inherit}
button{cursor:pointer}
button:focus-visible,input:focus-visible{outline:3px solid var(--on);outline-offset:2px}
.app{position:fixed;left:0;right:0;top:var(--vvt,0px);height:var(--vvh,100%);max-width:900px;margin:0 auto;display:flex;flex-direction:column;gap:9px;
  padding-left:max(14px,env(safe-area-inset-left,0px));padding-right:max(14px,env(safe-area-inset-right,0px));
  padding-top:max(10px,env(safe-area-inset-top,0px));padding-bottom:max(10px,env(safe-area-inset-bottom,0px))}
.main{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;gap:9px;overflow-y:auto;overscroll-behavior:contain}
.hud{display:flex;align-items:center;gap:7px;flex:none;min-height:36px}
.chip{display:inline-flex;align-items:center;gap:6px;height:34px;padding:0 12px;border-radius:99px;background:var(--glass);font:800 14px var(--display);font-variant-numeric:tabular-nums;white-space:nowrap}
.chip svg{width:17px;height:17px;flex:none}
.hearts{display:flex;gap:2px}
.hearts svg{width:20px;height:20px;transition:opacity .3s,transform .3s}
.hearts svg.lost{opacity:.25;transform:scale(.8)}
.spacer{flex:1}
.iconbtn{width:34px;height:34px;border:0;border-radius:50%;background:var(--glass);display:grid;place-items:center;flex:none}
.iconbtn svg{width:16px;height:16px}
.badge{position:absolute;right:10px;top:-13px;display:inline-flex;align-items:center;gap:6px;background:#fff;color:var(--ink);border-radius:99px;padding:5px 11px;font:800 13px var(--display);box-shadow:0 4px 14px rgba(0,0,0,.18);max-width:calc(100% - 20px);z-index:5}
.badge::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--err);flex:none}
.badge.good::before{background:var(--green)}
.prompt{position:relative;background:var(--glass);border-radius:20px;padding:12px 15px 14px;transition:background .18s;flex:none}
.prompt.ok{background:var(--green)}
.eyebrow{display:block;font:800 11.5px var(--display);text-transform:uppercase;letter-spacing:.09em;opacity:.8}
.def{margin:5px 0 0;font:800 clamp(18px,5vw,25px)/1.22 var(--display);text-wrap:balance}
.opts{display:grid;grid-template-columns:1fr 1fr;gap:8px;flex:none}
@media (min-width:700px){.opts.four{grid-template-columns:repeat(4,1fr)}}
.opt{position:relative;min-height:54px;border:0;border-radius:17px;background:var(--glass);font:800 17px/1.15 var(--display);padding:8px 10px;overflow-wrap:anywhere;transition:transform .1s,background .15s,opacity .2s,color .15s}
.opt:active{transform:scale(.97)}
@media (hover:hover){.opt:hover{background:var(--glass-2)}}
.opt.sel{background:#fff;color:var(--ink)}
.opt.right{background:var(--green);color:#fff}
.opt.reveal{background:#fff;color:var(--ink)}
.opt.dim{opacity:.38}
.locked .opt{pointer-events:none}
.solid{width:100%;min-height:54px;border:0;border-radius:17px;background:#fff;color:var(--ink);font:800 17px var(--display);transition:opacity .2s,transform .1s}
.solid:disabled{opacity:.45;cursor:default}
.solid:active:not(:disabled){transform:scale(.98)}
.ghost{min-height:48px;border:0;border-radius:16px;background:var(--glass);font:800 15px var(--display);padding:0 14px}
.ghost:disabled{opacity:.4}
.link{border:0;background:none;font:700 14px var(--display);opacity:.85;padding:6px 12px;border-radius:99px}
.doni{position:fixed;left:50%;top:calc(58px + env(safe-area-inset-top,0px));transform:translate(-50%,-16px);opacity:0;display:flex;align-items:center;gap:10px;background:#fff;color:var(--ink);border-radius:20px;padding:8px 14px 8px 8px;box-shadow:0 12px 30px rgba(0,0,0,.25);transition:transform .3s cubic-bezier(.2,1.4,.4,1),opacity .25s;pointer-events:none;z-index:15;width:max-content;max-width:calc(100% - 28px)}
.doni.show{transform:translate(-50%,0);opacity:1}
.doni svg{width:40px;height:40px;flex:none}
.doni p{margin:0;font:700 14.5px/1.3 var(--display)}
.banner{position:fixed;left:50%;top:38%;transform:translate(-50%,-50%);text-align:center;pointer-events:none;opacity:0;width:max-content;max-width:90%;z-index:14}
.banner h3{margin:0;font:900 clamp(26px,7vw,44px)/1.05 var(--display);text-shadow:0 3px 0 rgba(0,0,0,.25),0 10px 30px rgba(0,0,0,.35)}
.banner p{margin:6px 0 0;font:700 15px var(--display);text-shadow:0 2px 10px rgba(0,0,0,.4)}
.banner.show{animation:kbanner 2s ease forwards}
@keyframes kbanner{0%{opacity:0;transform:translate(-50%,-30%) scale(.9)}12%{opacity:1;transform:translate(-50%,-50%) scale(1.04)}20%{transform:translate(-50%,-50%) scale(1)}80%{opacity:1}100%{opacity:0;transform:translate(-50%,-62%)}}
.overlay{position:fixed;inset:0;z-index:20;display:grid;place-items:center;background:rgba(22,11,51,.62);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);overflow-y:auto;
  padding-left:max(14px,env(safe-area-inset-left,0px));padding-right:max(14px,env(safe-area-inset-right,0px));padding-block:max(18px,env(safe-area-inset-top,0px)) max(18px,env(safe-area-inset-bottom,0px))}
.sheet{width:100%;max-width:460px;background:var(--stage);color:var(--on);border-radius:28px;padding:22px 20px 20px;box-shadow:0 30px 80px rgba(0,0,0,.45);display:grid;gap:13px}
.kicker{margin:0;font:800 12px var(--display);text-transform:uppercase;letter-spacing:.12em;opacity:.8}
.sheet h1{margin:-6px 0 0;font:900 clamp(30px,8vw,42px)/1 var(--display);letter-spacing:-.02em;text-wrap:balance}
.lede{margin:0;font-size:15.5px;line-height:1.45}
.rules{margin:0;padding:0;list-style:none;display:grid;gap:7px;font-size:14.5px;line-height:1.4}
.rules li{background:var(--shade);border-radius:14px;padding:9px 12px}
.seg{display:grid;grid-template-columns:1fr 1fr;gap:6px;background:var(--shade);padding:5px;border-radius:18px}
.seg button{border:0;border-radius:14px;min-height:44px;background:none;font:800 15px var(--display)}
.seg button small{display:block;font:600 11px var(--body);opacity:.8}
.seg button[aria-pressed="true"]{background:#fff;color:var(--ink)}
.seglabel{margin:0 0 -6px;font:800 13px var(--display)}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}
.stat{background:var(--glass);border-radius:16px;padding:10px 11px}
.stat b{display:block;font:900 23px var(--display);font-variant-numeric:tabular-nums}
.stat span{font-size:12px;opacity:.85;line-height:1.25;display:block}
.mini{margin:2px 0 -4px;font:800 12.5px var(--display);text-transform:uppercase;letter-spacing:.09em;opacity:.8}
.wordlist{display:flex;flex-wrap:wrap;gap:6px}
.wchip{display:inline-flex;align-items:center;gap:6px;border-radius:99px;padding:6px 11px;font:800 14px var(--display);background:var(--glass)}
.wchip.up{background:var(--green);color:#fff}
.wchip small{font:600 11px var(--body);opacity:.85}
details{font-size:13px}
summary{cursor:pointer;font-weight:700}
pre{margin:8px 0 0;max-height:130px;overflow:auto;background:var(--shade);border-radius:12px;padding:10px;font:12px/1.4 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:pre-wrap}
@media (max-height:680px){.def{font-size:18px}.opt{min-height:46px;font-size:16px}.solid{min-height:48px}.prompt{padding:10px 13px 12px}}
@media (prefers-reduced-motion:reduce){.banner.show{animation:none;opacity:1}.doni{transition:opacity .2s}}
@media (max-width:380px){.row{flex-wrap:wrap;justify-content:center}.row .note{flex:1 1 100%!important;order:-1}.small{padding:0 11px;font-size:13px}}

