/* ═════════ Shared base for every game: content, engine stub, sound, Doni, HUD, start and end screens ═════════ */
const K = (() => {
'use strict';

/* ───────── Content: one list per level, helper text in the list's own language (Uzbek text is a draft for review).
   Card fields per the template contract: w word, d definition, s sentence with ___, f exact form, ant opposite, sp hand-written misspellings. ───────── */
const LEVELS = {
  a2:{text:'uz', words:[
    {id:'kitchen',w:'kitchen',p:'noun',d:'Ovqat tayyorlanadigan xona',s:'We cook dinner in the ___.',f:'kitchen',sp:['kichen','kitchin'],diff:1},
    {id:'library',w:'library',p:'noun',d:'Kitoblar saqlanadigan va o\'qiladigan joy',s:'We borrow books from the ___.',f:'library',sp:['libary','librery'],diff:2},
    {id:'tired',w:'tired',p:'adj',d:'Charchagan, dam olishni xohlaydigan',s:'I am very ___, so I want to sleep.',f:'tired',ant:'energetic',sp:['taired','tierd'],diff:1},
    {id:'borrow',w:'borrow',p:'verb',d:'Biror narsani vaqtincha olib turmoq',s:'Can I ___ your pen for a minute?',f:'borrow',ant:'lend',sp:['borow','borrov'],diff:2},
    {id:'journey',w:'journey',p:'noun',d:'Bir joydan boshqa joyga uzoq safar',s:'The bus ___ to the mountains took six hours.',f:'journey',sp:['jurney','journy'],diff:2},
    {id:'angry',w:'angry',p:'adj',d:'Jahli chiqqan',s:'He was ___ because his brother broke his bike.',f:'angry',ant:'calm',sp:['angri','angary'],diff:1},
    {id:'quiet',w:'quiet',p:'adj',d:'Shovqinsiz, tinch',s:'Please be ___ in the library.',f:'quiet',ant:'noisy',sp:['quiete','qiuet'],diff:1},
    {id:'expensive',w:'expensive',p:'adj',d:'Narxi juda baland',s:'This phone is too ___. I can\'t buy it.',f:'expensive',ant:'cheap',sp:['expensiv','expencive'],diff:2},
    {id:'remember',w:'remember',p:'verb',d:'Esda saqlamoq, unutmaslik',s:'Did you ___ to close the window?',f:'remember',ant:'forget',sp:['remeber','rememmber'],diff:2},
    {id:'dangerous',w:'dangerous',p:'adj',d:'Xavfli, zarar yetkazishi mumkin',s:'Don\'t swim here. The river is ___.',f:'dangerous',ant:'safe',sp:['dangerus','dangrous'],diff:3},
    {id:'neighbour',w:'neighbour',p:'noun',d:'Yoningizda yashaydigan odam',s:'My ___ lives next door with her two cats.',f:'neighbour',sp:['neighbur','nieghbour'],diff:3},
    {id:'umbrella',w:'umbrella',p:'noun',d:'Yomg\'irdan saqlaydigan buyum',s:'Take your ___. It is raining outside.',f:'umbrella',sp:['umbrela','umbralla'],diff:2},
    {id:'breakfast',w:'breakfast',p:'noun',d:'Ertalabki ovqat',s:'I always eat ___ at seven in the morning.',f:'breakfast',sp:['brekfast','breakfest'],diff:1},
    {id:'weather',w:'weather',p:'noun',d:'Tashqaridagi havo holati: yomg\'ir, quyosh, sovuq',s:'The ___ is sunny and warm today.',f:'weather',sp:['weathar','waether'],diff:3},
    {id:'cheap',w:'cheap',p:'adj',d:'Arzon, narxi past',s:'This T-shirt is ___. It was only two dollars.',f:'cheap',ant:'expensive',sp:['chaep','cheapp'],diff:1},
    {id:'busy',w:'busy',p:'adj',d:'Bandligi ko\'p, bo\'sh vaqti yo\'q',s:'I can\'t talk now. I am very ___.',f:'busy',ant:'free',sp:['bussy','buisy'],diff:1}]},
  c1:{text:'en', words:[
    {id:'erratic',w:'erratic',p:'adj',d:'Unpredictable, inconsistent, irregular',s:'His ___ dance moves changed every second, so even the DJ couldn\'t keep up.',f:'erratic',ant:'predictable',sp:['erratik','eratic'],diff:1},
    {id:'secluded',w:'secluded',p:'adj',d:'Hard to reach, hidden away',s:'The WiFi was so bad in the ___ cabin that they made friends with the squirrels.',f:'secluded',ant:'accessible',sp:['secludded','sekluded'],diff:1},
    {id:'fluctuate',w:'fluctuate',p:'verb',d:'To rise and fall irregularly',s:'His mood seems to ___ like the stock market: happy with pizza, gloomy without it.',f:'fluctuate',ant:'stabilize',sp:['flucuate','fluctuete'],diff:2},
    {id:'admonish',w:'admonish',p:'verb',d:'To warn or scold someone',s:'The teacher had to ___ the cat for knocking over the vase.',f:'admonish',ant:'praise',sp:['admonnish','admonesh'],diff:3},
    {id:'colloquial',w:'colloquial',p:'adj',d:'Used in casual conversation',s:'His speech was so full of ___ slang that even his grandma was confused.',f:'colloquial',ant:'formal',sp:['colloquel','coloquial'],diff:3},
    {id:'alienate',w:'alienate',p:'verb',d:'To make someone feel isolated or lonely',s:'Talking only about traffic lights can quickly ___ your friends.',f:'alienate',ant:'befriend',sp:['alianate','alienete'],diff:2},
    {id:'adept',w:'adept',p:'adj',d:'Very skilled at something',s:'She is so ___ at parking that she could fit a bus into a tiny space.',f:'adept',ant:'inept',sp:['adeptt','adpet'],diff:2},
    {id:'coerce',w:'coerce',p:'verb',d:'To pressure or force someone to do something',s:'He tried to ___ his little brother into trading chocolate for a carrot.',f:'coerce',ant:'persuade gently',sp:['coarce','coerse'],diff:3},
    {id:'eloquent',w:'eloquent',p:'adj',d:'Fluent and persuasive in speaking or writing',s:'His speech was so ___ that even his dog stopped barking to listen.',f:'eloquent',ant:'inarticulate',sp:['eloquant','elloquent'],diff:2},
    {id:'inevitable',w:'inevitable',p:'adj',d:'Unavoidable',s:'It was ___ that he would trip while texting; everyone saw it coming.',f:'inevitable',ant:'avoidable',sp:['inevitible','inevetable'],diff:1},
    {id:'detrimental',w:'detrimental',p:'adj',d:'Harmful, damaging',s:'Eating ten donuts for breakfast might be ___ to your health.',f:'detrimental',ant:'beneficial',sp:['detrimantal','detremental'],diff:2},
    {id:'ephemeral',w:'ephemeral',p:'adj',d:'Lasting a very short time',s:'His love of the gym was ___, lasting just long enough to post one photo.',f:'ephemeral',ant:'permanent',sp:['ephemeril','ephemerel'],diff:3},
    {id:'ubiquitous',w:'ubiquitous',p:'adj',d:'Found everywhere',s:'Phones are so ___ that you can\'t walk five steps without seeing one.',f:'ubiquitous',ant:'rare',sp:['ubiquitious','ubiqitous'],diff:3},
    {id:'tenacity',w:'tenacity',p:'noun',d:'Persistence, determination',s:'Building a treehouse with a single hammer took real ___.',f:'tenacity',ant:'weakness',sp:['tenasity','tennacity'],diff:2},
    {id:'skeptical',w:'skeptical',p:'adj',d:'Having doubts',s:'She was ___ about the cream that promised to make her twenty years younger.',f:'skeptical',ant:'trusting',sp:['skeptikal','skepticle'],diff:1},
    {id:'lavish',w:'lavish',p:'adj',d:'Luxurious, rich and expensive',s:'The party was so ___ that it had a chocolate fountain and a live band, just for the dog.',f:'lavish',ant:'frugal',sp:['lavvish','lavesh'],diff:1}]}
};
const CONFUSE=[['erratic','fluctuate'],['expensive','cheap'],['quiet','busy']];

/* ───────── Homework content from the hub: one homework code feeds every game. Without it, the demo lists above are used. ───────── */
const WG = (typeof window!=='undefined'&&window.__WG)||null;
if(WG){ LEVELS.hw={text:WG.text||'en',words:WG.cards}; CONFUSE.length=0; (WG.confuse||[]).forEach(g=>CONFUSE.push(g)) }
// games with extra content (groups, scales, stories...) read a homework block; demo tables otherwise
function block(name,table){ return WG ? ((WG.blocks&&WG.blocks[name])||[]) : table[level] }
// the game only reports; the vocab engine decides stages and schedules
function post(msg){ try{ if(window.parent&&window.parent!==window) window.parent.postMessage(Object.assign({wg:1,game:WG&&WG.game},msg),'*') }catch(e){} }

/* ───────── Shared game text; each game adds its own keys (Uzbek strings are drafts) ───────── */
const COMMON = {
  en:{kicker:'Vocabulary game',coins:'coins',words:'Words this round',stronger:'stronger',review:'review',idk:"I don't know",notQuite:w=>`Not quite · it's ${w}`,again:'Play again',json:'Result sent to the vocab engine',demo:'Demo · set by the homework',uzText:'Uzbek game text',enText:'English game text'},
  uz:{kicker:'Lug\'at o\'yini',coins:'tanga',words:'Bu raunddagi so\'zlar',stronger:'kuchaydi',review:'takrorlash',idk:'Bilmayman',notQuite:w=>`Hali emas · javob: ${w}`,again:'Yana o\'ynash',json:'Lug\'at tizimiga yuborilgan natija',demo:'Demo · uy vazifasi belgilaydi',uzText:'O\'zbekcha matn',enText:'Inglizcha matn'}
};

/* ───────── Utilities ───────── */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
let r=mulberry32((Date.now()*2654435761)>>>0);
const rng=()=>r();
const reseed=()=>{ r=mulberry32((Date.now()*2654435761)>>>0) };
const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const cap=s=>s?s[0].toUpperCase()+s.slice(1):s;
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const confused=id=>{const s=new Set([id]); CONFUSE.forEach(g=>{if(g.includes(id)) g.forEach(x=>s.add(x))}); return s};

/* ───────── One way to judge typed answers (shared by every typed game): case, spaces, curly quotes, Cyrillic look-alikes ───────── */
const CYR={'а':'a','е':'e','о':'o','р':'p','с':'c','х':'x','у':'y','к':'k','м':'m','т':'t','н':'h','в':'b','і':'i'};
const norm=s=>String(s).toLowerCase().replace(/[’‘`]/g,"'").replace(/[аеорсхукмтнві]/g,c=>CYR[c]||c).replace(/[^a-z' -]/g,'').replace(/\s+/g,' ').trim();
function lev(a,b){ if(Math.abs(a.length-b.length)>1) return 9; const d=[...Array(b.length+1).keys()]; for(let i=1;i<=a.length;i++){let p=d[0];d[0]=i;for(let j=1;j<=b.length;j++){const t=d[j];d[j]=Math.min(d[j]+1,d[j-1]+1,p+(a[i-1]===b[j-1]?0:1));p=t}} return d[b.length] }
// 'exact', 'close' (one slip on a word of 6+ letters: counts, with less evidence) or null
function judge(input,word){ const v=norm(input); if(!v) return null; const forms=[word.f||word.w,word.w,...(word.alt||[])].map(norm); if(forms.includes(v)) return 'exact'; const base=norm(word.f||word.w); return base.length>=6&&forms.some(f=>lev(v,f)===1)?'close':null }

/* ───────── Viewport (keeps the game above the phone keyboard and inside the screen) ───────── */
function fit(){ const app=$('app'); const vv=window.visualViewport; if(!app||!vv) return; app.style.setProperty('--vvh',vv.height+'px'); app.style.setProperty('--vvt',vv.offsetTop+'px') }
if(window.visualViewport){ visualViewport.addEventListener('resize',fit); visualViewport.addEventListener('scroll',fit) }

/* ───────── Sound (generated in code) ───────── */
let AC=null, soundOn=true, noiseBuf=null;
function ac(){ if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)()}catch(e){}} if(AC&&AC.state==='suspended') AC.resume(); return AC }
function tone(f,d,{type='sine',v=.12,to=null,at=0}={}){ if(!soundOn) return; const a=ac(); if(!a) return; const t=a.currentTime+at; const o=a.createOscillator(), g=a.createGain(); o.type=type; o.frequency.setValueAtTime(f,t); if(to) o.frequency.exponentialRampToValueAtTime(to,t+d); g.gain.setValueAtTime(.0001,t); g.gain.exponentialRampToValueAtTime(v,t+.01); g.gain.exponentialRampToValueAtTime(.0001,t+d); o.connect(g).connect(a.destination); o.start(t); o.stop(t+d+.03) }
function noise(d,{v=.2,f=1200,q=1,type='bandpass',at=0}={}){ if(!soundOn) return; const a=ac(); if(!a) return; if(!noiseBuf){noiseBuf=a.createBuffer(1,a.sampleRate,a.sampleRate);const ch=noiseBuf.getChannelData(0);for(let i=0;i<ch.length;i++)ch[i]=Math.random()*2-1} const t=a.currentTime+at; const s=a.createBufferSource(); s.buffer=noiseBuf; const fl=a.createBiquadFilter(); fl.type=type; fl.frequency.value=f; fl.Q.value=q; const g=a.createGain(); g.gain.setValueAtTime(v,t); g.gain.exponentialRampToValueAtTime(.0001,t+d); s.connect(fl).connect(g).connect(a.destination); s.start(t); s.stop(t+d+.03) }
const SFX={
  tap(){tone(620,.05,{type:'triangle',v:.05})},
  right(c){const b=523*Math.pow(1.06,Math.min(c||0,8)); tone(b,.09,{type:'triangle',v:.1}); tone(b*1.5,.15,{type:'triangle',v:.09,at:.08})},
  wrong(){tone(330,.15,{v:.07}); tone(262,.22,{v:.07,at:.12})},
  coin(){tone(1320,.06,{type:'square',v:.026}); tone(1760,.1,{type:'square',v:.026,at:.05})},
  lose(){noise(.2,{v:.25,f:300,type:'lowpass'}); tone(160,.25,{v:.1,to:80})},
  win(){[523,659,784,1047,784,1047].forEach((f,i)=>tone(f,.2,{type:'triangle',v:.09,at:i*.11}))},
  end(){[392,330,262].forEach((f,i)=>tone(f,.26,{v:.07,at:i*.18}))}
};

/* ───────── Engine stub: same contract as the real engine (pick due words, record the first answer per word) ───────── */
function engine(words){
  const byId=Object.fromEntries(words.map(w=>[w.id,w]));
  const queue=shuffle(words.map(w=>w.id)), stats={}, recent=[];
  return {
    byId,
    next(pref=2,exclude=[]){
      let cand=queue.filter(id=>!recent.includes(id)&&!exclude.includes(id)).slice(0,7);
      if(!cand.length) cand=queue.filter(id=>!exclude.includes(id)).slice(0,1);
      if(!cand.length) cand=queue.slice(0,1);
      cand.sort((a,b)=>Math.abs(byId[a].diff-pref)-Math.abs(byId[b].diff-pref));
      const id=cand[0]; queue.splice(queue.indexOf(id),1); return byId[id];
    },
    submit(id,ok,evidence){
      const s=stats[id]||(stats[id]={seen:0,right:0,first:null,ev:'none'});
      s.seen++; if(ok) s.right++;
      if(s.first===null){ s.first=ok; s.ev=ok?(evidence||'weak'):'none' }
      post({type:'answer',wid:id,ok:!!ok,evidence:ok?(evidence||'weak'):'none',first:s.seen===1});
      if(ok) queue.push(id); else queue.splice(Math.min(3,queue.length),0,id);
      recent.push(id); if(recent.length>3) recent.shift();
    },
    results(){ return Object.entries(stats).map(([wid,s])=>({wid,ok:s.first,evidence:s.ev})) }
  };
}
/* ───────── Room: the players of a multiplayer game. Here the others are simulated; on the site the same calls go
   through a Supabase Realtime channel (presence = who is in, broadcast = answers). Every client derives the same
   question order from the room seed, so no server code is needed. ───────── */
const BOT_NAMES=['Kamola','Sardor','Malika','Jasur','Nilufar','Bekzod','Dilnoza','Otabek','Madina','Aziz','Shahzoda','Timur','Gulnora','Rustam','Zarina','Islom','Laylo','Doniyor','Sevara'];
function room({size=2,you='You'}={}){
  const names=shuffle([...BOT_NAMES]);
  const players=[{id:'me',name:you,me:true,skill:null}];
  for(let i=1;i<size;i++) players.push({id:'b'+i,name:names[(i-1)%names.length],me:false,skill:.55+r()*.35,speed:.7+r()*.6});
  return {players,
    // a simulated answer: accuracy falls with word difficulty and tier; time is human-like and never instant
    bot(p,word,tier=1){ const acc=Math.max(.2,Math.min(.95,p.skill-.07*((word&&word.diff)||2)-.06*(tier-1)+.08)); const ok=r()<acc;
      const t=(1.6+tier*1.3+r()*2.6)*p.speed*1000; return {ok,t} },
    mode:'simulated'};
}
function options(w,pool,n=4,field='w'){
  const bad=confused(w.id);
  const same=shuffle(pool.filter(x=>!bad.has(x.id)&&x.p===w.p)), other=shuffle(pool.filter(x=>!bad.has(x.id)&&x.p!==w.p));
  const picks=[...same,...other].slice(0,n-1);
  return shuffle([w,...picks]);
}

/* ───────── UI helpers ───────── */
const heartSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-7.5-4.6-9.6-9.3C.9 8.3 3 4.5 6.6 4.5c2.1 0 3.6 1.2 5.4 3.2 1.8-2 3.3-3.2 5.4-3.2 3.6 0 5.7 3.8 4.2 7.2C19.5 16.4 12 21 12 21z" fill="currentColor"/></svg>';
function hearts(el,n,max){ if(el.children.length!==max) el.innerHTML=heartSvg.repeat(max); [...el.children].forEach((h,i)=>h.classList.toggle('lost',i>=n)); el.setAttribute('aria-label',`${n} of ${max}`) }
let badgeT=0;
function badge(el,text,good,ms=2000){ el.textContent=text; el.classList.toggle('good',!!good); el.hidden=false; clearTimeout(el._t); el._t=setTimeout(()=>el.hidden=true,ms) }
let doniT=0;
function doni(text){ const d=$('doni'); if(!d||!text) return; $('doniTxt').textContent=text; d.classList.add('show'); clearTimeout(doniT); doniT=setTimeout(()=>d.classList.remove('show'),2600) }
function banner(title,sub){ const b=$('banner'); if(!b) return; b.querySelector('h3').textContent=title; b.querySelector('p').textContent=sub||''; b.classList.remove('show'); void b.offsetWidth; b.classList.add('show') }

/* ───────── Level, text, start and end screens ───────── */
let level=WG?'hw':'c1', GAME=null, T=null;
function texts(){ const lang=LEVELS[level].text; return Object.assign({},COMMON[lang],GAME.text[lang]) }
function setup(game){
  GAME=game;
  const seg=$('levelSeg');
  seg.addEventListener('click',e=>{ const b=e.target.closest('button'); if(!b) return; level=b.dataset.l; [...seg.children].forEach(x=>x.setAttribute('aria-pressed',x===b)); applyText(); GAME.preview&&GAME.preview() });
  $('startBtn').addEventListener('click',()=>{ ac(); $('startOv').hidden=true; reseed(); GAME.start() });
  $('againBtn').addEventListener('click',()=>{ $('endOv').hidden=true; $('startOv').hidden=false; GAME.preview&&GAME.preview() });
  $('soundBtn').addEventListener('click',()=>{ soundOn=!soundOn; $('soundBtn').style.opacity=soundOn?1:.5; $('soundBtn').setAttribute('aria-label',soundOn?'Sound on':'Sound off') });
  if(WG){ seg.hidden=true; $('segLabel').hidden=true }
  fit(); applyText(); GAME.preview&&GAME.preview();
}
function applyText(){
  T=texts(); document.documentElement.lang=LEVELS[level].text;
  $('sKicker').textContent=T.kicker; $('sTitle').textContent=T.title; $('sLede').textContent=T.lede;
  $('sRules').innerHTML=T.rules.map(x=>`<li>${x}</li>`).join(''); $('startBtn').textContent=T.start;
  $('segLabel').textContent=T.demo; const b=$('levelSeg').children; b[0].querySelector('small').textContent=COMMON.uz.uzText; b[1].querySelector('small').textContent=COMMON.en.enText;
  $('againBtn').textContent=T.again; $('jsonSum').textContent=T.json;
  document.querySelectorAll('[data-t]').forEach(el=>{ const v=T[el.dataset.t]; if(typeof v==='string') el.textContent=v });
  GAME.onText&&GAME.onText(T);
}
function end({kicker,title,stats,results,payload,extra}){
  $('eKicker').textContent=kicker||T.title; $('eTitle').textContent=title;
  $('eStats').innerHTML=stats.map(s=>`<div class="stat"><b>${esc(s.v)}</b><span>${esc(s.l)}</span></div>`).join('');
  $('eExtra').innerHTML=extra||''; $('eExtra').hidden=!extra;
  const byId=Object.fromEntries(LEVELS[level].words.map(w=>[w.id,w]));
  $('eWordsLbl').textContent=T.words;
  $('eWords').innerHTML=results.map(x=>`<span class="wchip ${x.ok?'up':''}">${esc(byId[x.wid]?byId[x.wid].w:x.wid)}<small>${x.ok?T.stronger:T.review}</small></span>`).join('')||'<span class="wchip">—</span>';
  $('eJson').textContent=JSON.stringify(Object.assign({level},payload,{results}),null,1);
  post({type:'result',data:Object.assign({},payload,{results})});
  $('endOv').hidden=false; $('againBtn').focus();
}

return {LEVELS,get level(){return level},get T(){return T},get words(){return LEVELS[level].words},
  rng,reseed,shuffle,$,esc,cap,reduceMotion,confused,norm,lev,judge,tone,noise,SFX,ac,engine,options,hearts,badge,doni,banner,setup,end,block,post,room,get hwId(){return WG&&WG.id||''}};
})();

