/* Shared look for typed (Recall) games: orange stage with dark text, a typing bar pinned above the keyboard */
:root{--stage:#FF8A1E;--on:#2B1700;--ink:#2B1700;--glass:rgba(43,23,0,.11);--glass-2:rgba(43,23,0,.18);--shade:rgba(43,23,0,.12);color-scheme:light}
.prompt{background:#FFF4E6;color:var(--ink)}
.prompt.ok{background:var(--green);color:#fff}
.typer{flex:none;display:flex;gap:8px;position:relative}
.typer input{flex:1;min-width:0;height:54px;border:0;border-radius:17px;background:#fff;color:var(--ink);font:800 21px var(--display);padding:0 16px;letter-spacing:.02em}
.typer input::placeholder{color:rgba(43,23,0,.38);font-weight:700}
.typer input:disabled{opacity:.55}
.typer.shake input{animation:tshake .32s}
@keyframes tshake{0%,100%{transform:none}25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}
.typer .go{height:54px;border:0;border-radius:17px;background:var(--ink);color:#fff;font:800 17px var(--display);padding:0 18px}
.typer .go:disabled{opacity:.45}
.row{flex:none;display:flex;gap:8px;align-items:center}
.small{border:0;background:var(--glass);border-radius:99px;height:36px;padding:0 14px;font:800 14px var(--display)}
.small:disabled{opacity:.4}
.row .note{flex:1;text-align:center;font:700 13px var(--display);opacity:.75}
.hintline{display:block;margin-top:6px;font:800 16px var(--display);letter-spacing:.2em;color:#B85A00}
.sheet .solid{background:var(--ink);color:#fff}
.overlay{background:rgba(43,23,0,.5)}
.seg button[aria-pressed="true"]{background:#fff;color:var(--ink)}
