gameshow.css:
/* The Big Word Show: studio lights over the prize ladder; Recognize violet stage */
:root{--stage:#6A3DF0}
.studio{position:relative;flex:none;border-radius:22px;overflow:hidden;background:radial-gradient(120% 120% at 50% 0%,#3A1FA8,#170A45 70%);padding:12px 12px 12px;min-height:96px}
.spot{position:absolute;top:-30px;width:120px;height:170px;background:linear-gradient(rgba(255,240,200,.35),rgba(255,240,200,0));clip-path:polygon(40% 0,60% 0,100% 100%,0 100%);transform-origin:50% 0;pointer-events:none;mix-blend-mode:screen}
.spot.s1{left:6%;animation:sweep 6s ease-in-out infinite}
.spot.s2{left:42%;animation:sweep 7s ease-in-out infinite reverse}
.spot.s3{right:6%;animation:sweep 5s ease-in-out infinite}
@keyframes sweep{0%,100%{transform:rotate(-14deg)}50%{transform:rotate(14deg)}}
.studio.suspense .spot{animation-duration:.6s}
.studio.flash{box-shadow:inset 0 0 0 3px var(--green),0 0 30px rgba(19,138,61,.6)}
.stagehead{position:relative;display:flex;align-items:baseline;gap:8px;font:800 13px var(--display);text-transform:uppercase;letter-spacing:.09em}
.stagehead b{margin-left:auto;font:900 18px var(--display);color:var(--gold);letter-spacing:0;text-transform:none}
.ladder{position:relative;display:grid;grid-template-columns:repeat(12,1fr);gap:4px;margin-top:10px}
.ladder i{height:22px;border-radius:7px;background:rgba(255,255,255,.12);display:grid;place-items:center;font:800 10.5px var(--display);font-style:normal;color:rgba(255,255,255,.65);transition:background .25s,transform .25s}
.ladder i.safe{box-shadow:inset 0 0 0 2px rgba(245,183,0,.7)}
.ladder i.done{background:rgba(245,183,0,.85);color:#2B1700}
.ladder i.now{background:#fff;color:var(--ink);transform:scale(1.12)}
.clue{margin:8px 0 0;font:600 14.5px/1.4 var(--body);background:var(--shade);border-radius:12px;padding:8px 10px}
.opt .l{display:inline-grid;place-items:center;width:24px;height:24px;border-radius:50%;background:rgba(255,255,255,.2);font:900 12px var(--display);margin-right:8px;vertical-align:middle}
.opt.sel .l{background:var(--ink);color:#fff}
.opt{text-align:left;padding-left:12px}
.opt.gone{visibility:hidden}
.opt.pulse{animation:pulse .5s ease infinite alternate}
@keyframes pulse{from{box-shadow:0 0 0 0 rgba(255,255,255,.7)}to{box-shadow:0 0 0 6px rgba(255,255,255,0)}}
.actions{flex:none;display:grid;grid-template-columns:auto auto 1fr;gap:8px}
.life{display:grid;place-items:center;line-height:1.05;padding:4px 12px;min-width:74px}
.life b{font:900 15px var(--display)}
.life small{font:600 10.5px var(--body);opacity:.8}
.life.used{opacity:.3;text-decoration:line-through}
@media (max-width:380px){.ladder i{font-size:0}.life{min-width:62px;padding:4px 8px}}
@media (prefers-reduced-motion:reduce){.spot{animation:none}.opt.pulse{animation:none}}

gameshow.js:
/* ═════════ The Big Word Show ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 1;                                   // hidden tier: Recognize
const LADDER = [1,1,2,2,2,3,3,3,4,4,5,6];         // coins per step, times TIER
const SAFE = [3,7];                               // checkpoints after steps 4 and 8 (index)
const LIVES = 3;

const text = {
  en:{title:'The Big Word Show',lede:'Climb the prize ladder: 12 questions, three chances. Pick an answer, then lock it in.',
      rules:['<b>Tap an answer</b>, then press <b>Final answer</b>. You can change your mind before you lock in.','<b>A wrong answer</b> costs a chance and drops you back to the last gold checkpoint.','<b>Lifelines</b> help once each, but that question pays half and counts less toward learning.'],
      start:'Start the show',which:'Which word means',q:n=>`Question ${n}`,pick:'Pick an answer',final:'Final answer',fiftyL:'once',clueB:'Clue',clueL:'once',
      clueTxt:s=>`In a sentence: ${s}`,right:c=>`Correct · +${c}`,back:'Back to the checkpoint',won:'Top of the ladder!',out:'Out of chances',
      winT:'You won the show',outT:'The show is over',stCoins:'coins',stTop:'highest step',stClean:'answered with no lifeline',
      praiseTop:'All twelve steps. Champion.',praiseHard:w=>`${w} is a hard one. Locked in and right.`},
  uz:{title:'Katta so\'z shousi',lede:'Sovrin narvoniga chiqing: 12 savol, uchta imkoniyat. Javobni tanlang, keyin tasdiqlang.',
      rules:['<b>Javobni bosing</b>, so\'ng <b>Yakuniy javob</b> tugmasini bosing. Tasdiqlashdan oldin fikringizni o\'zgartirishingiz mumkin.','<b>Noto\'g\'ri javob</b> bitta imkoniyatni oladi va sizni oxirgi oltin bosqichga qaytaradi.','<b>Yordamlar</b> bir martadan ishlaydi, lekin o\'sha savol yarim tanga beradi.'],
      start:'Shouni boshlash',which:'Qaysi so\'z shuni anglatadi',q:n=>`${n}-savol`,pick:'Javobni tanlang',final:'Yakuniy javob',fiftyL:'bir marta',clueB:'Maslahat',clueL:'bir marta',
      clueTxt:s=>`Gapda: ${s}`,right:c=>`To'g'ri · +${c}`,back:'Oltin bosqichga qaytish',won:'Narvon cho\'qqisi!',out:'Imkoniyat qolmadi',
      winT:'Siz shouda g\'olib bo\'ldingiz',outT:'Shou tugadi',stCoins:'tanga',stTop:'eng yuqori bosqich',stClean:'yordamsiz javoblar',
      praiseTop:'O\'n ikki bosqichning hammasi. Chempion!',praiseHard:w=>`${w} qiyin so\'z. To\'g'ri tanladingiz.`}
};

let G=null, T=null;
function pref(step){ return step<4?1:step<8?2:3 }       // harder words higher up the ladder
function newRound(preview){
  const eng=K.engine(K.words);
  G={eng,step:0,top:0,lives:LIVES,coins:0,clean:0,fifty:false,clue:false,q:null,sel:null,busy:false,preview:!!preview};
  renderLadder(); K.hearts($('lives'),LIVES,LIVES); $('coinTxt').textContent=0;
  $('fifty').classList.remove('used'); $('clueBtn').classList.remove('used');
  nextQ();
}
function nextQ(){
  const w=G.eng.next(pref(G.step));
  G.q={w,opts:K.options(w,K.words),lifeline:false,gone:[]}; G.sel=null; G.busy=false;
  $('def').textContent=w.d; $('clue').hidden=true; $('badge').hidden=true; $('prompt').classList.remove('ok');
  $('opts').innerHTML=G.q.opts.map((o,i)=>`<button class="opt" data-i="${i}"><span class="l">${'ABCD'[i]}</span>${esc(o.w)}</button>`).join('');
  $('opts').classList.remove('locked');
  $('fifty').disabled=G.fifty; $('clueBtn').disabled=G.clue;
  $('lockBtn').disabled=true; $('lockBtn').textContent=T.pick;
  renderLadder();
}
function renderLadder(){
  $('ladder').innerHTML=LADDER.map((v,i)=>`<i class="${SAFE.includes(i)?'safe':''} ${i<G.step?'done':''} ${i===G.step?'now':''}">${v*TIER}</i>`).join('');
  $('qLabel').textContent=T.q(G.step+1); $('qValue').textContent=`+${LADDER[Math.min(G.step,LADDER.length-1)]*TIER}`;
  $('stepChip').textContent=`${Math.min(G.step+1,LADDER.length)}/${LADDER.length}`;
}
$('opts').addEventListener('click',e=>{
  const b=e.target.closest('.opt'); if(!b||!G||G.busy||G.preview) return;
  G.sel=+b.dataset.i; [...$('opts').children].forEach(x=>x.classList.toggle('sel',x===b)); K.SFX.tap();
  $('lockBtn').disabled=false; $('lockBtn').textContent=T.final;
});
$('lockBtn').addEventListener('click',()=>{ if(!G||G.busy||G.sel===null) return; lockIn() });
$('fifty').addEventListener('click',()=>{
  if(!G||G.busy||G.fifty||G.preview) return; G.fifty=true; G.q.lifeline=true; $('fifty').classList.add('used'); $('fifty').disabled=true;
  const wrong=G.q.opts.map((o,i)=>i).filter(i=>G.q.opts[i].id!==G.q.w.id); K.shuffle(wrong).slice(0,2).forEach(i=>{ $('opts').children[i].classList.add('gone'); if(G.sel===i){G.sel=null;$('lockBtn').disabled=true;$('lockBtn').textContent=T.pick} });
  tone(440,.1,{type:'triangle',v:.06}); tone(330,.12,{type:'triangle',v:.06,at:.08});
});
$('clueBtn').addEventListener('click',()=>{
  if(!G||G.busy||G.clue||G.preview) return; G.clue=true; G.q.lifeline=true; $('clueBtn').classList.add('used'); $('clueBtn').disabled=true;
  const c=$('clue'); c.textContent=T.clueTxt(G.q.w.s.replace('___','_____')); c.hidden=false; tone(880,.08,{type:'triangle',v:.06});
});
addEventListener('keydown',e=>{ if(!G||!$('startOv').hidden||!$('endOv').hidden) return; const k='abcd'.indexOf(e.key.toLowerCase()); if(k>=0||(e.key>='1'&&e.key<='4')){ const i=k>=0?k:+e.key-1; const b=$('opts').children[i]; b&&!b.classList.contains('gone')&&b.click() } else if(e.key==='Enter') $('lockBtn').click() });

function lockIn(){
  G.busy=true; $('opts').classList.add('locked'); $('lockBtn').disabled=true;
  const btns=[...$('opts').children], pick=btns[G.sel]; pick.classList.add('pulse');
  $('studio').classList.add('suspense');
  // suspense: a short drum roll before the reveal
  if(!K.reduceMotion) for(let i=0;i<8;i++) noise(.05,{v:.12+i*.02,f:180,type:'lowpass',at:i*.09});
  setTimeout(reveal, K.reduceMotion?150:900);
}
function reveal(){
  const q=G.q, btns=[...$('opts').children], ok=q.opts[G.sel].id===q.w.id;
  $('studio').classList.remove('suspense'); btns.forEach(b=>b.classList.remove('pulse'));
  // 50:50 leaves a coin-flip, so it gives no evidence; the sentence clue still counts, but weakly
  G.eng.submit(q.w.id, ok, q.lifeline ? 'none' : 'weak');
  if(ok){
    const c=Math.max(1,Math.round(LADDER[G.step]*TIER*(q.lifeline?.5:1))); G.coins+=c; if(!q.lifeline) G.clean++;
    btns[G.sel].classList.remove('sel'); btns[G.sel].classList.add('right'); $('prompt').classList.add('ok');
    $('studio').classList.add('flash'); setTimeout(()=>$('studio').classList.remove('flash'),600);
    SFX.right(G.step); setTimeout(()=>SFX.coin(),160); K.badge($('badge'),T.right(c),true);
    if(q.w.diff>=3&&!q.lifeline) K.doni(T.praiseHard(K.cap(q.w.w)));
    G.step++; G.top=Math.max(G.top,G.step); $('coinTxt').textContent=G.coins;
    if(G.step>=LADDER.length){ renderLadder(); K.banner(T.won,''); return setTimeout(()=>finish(true),1400) }
    setTimeout(nextQ,1100);
  } else {
    btns[G.sel].classList.add('dim'); btns.forEach((b,i)=>{ if(q.opts[i].id===q.w.id) b.classList.add('reveal') });
    G.lives--; K.hearts($('lives'),G.lives,LIVES); SFX.wrong();
    const safe=[...SAFE].reverse().find(s=>s<G.step); G.step = safe===undefined ? 0 : safe+1;
    K.badge($('badge'),T.notQuite(q.w.w),false,2400);
    if(G.lives<=0){ K.banner(T.out,''); return setTimeout(()=>finish(false),1800) }
    setTimeout(()=>{ K.banner(T.back,''); nextQ() },2000);
  }
}
function finish(won){
  won?SFX.win():SFX.end();
  if(won) K.doni(T.praiseTop);
  K.end({title:won?T.winT:T.outT,stats:[{v:G.coins,l:T.stCoins},{v:`${G.top}/${LADDER.length}`,l:T.stTop},{v:G.clean,l:T.stClean}],
    results:G.eng.results(),payload:{game:'big-word-show',tier:TIER,coins:G.coins,top:G.top}});
}

K.setup({text,
  onText:t=>{ T=t; if(G) renderLadder() },
  preview:()=>{ T=K.T; newRound(true) },
  start:()=>{ T=K.T; newRound(false) }
});
})();

whack.css:
/* Whack-a-Word: a garden of six holes; Recognize violet stage */
:root{--stage:#6A3DF0}
.garden{position:relative;flex:1 1 auto;min-height:230px;border-radius:24px;overflow:hidden;background:linear-gradient(#7FCB6A,#4FA34A 60%,#3E8A3A);display:grid;place-items:center;padding:14px}
.garden::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 20% 15%,rgba(255,255,255,.25) 0 2px,transparent 3px) 0 0/34px 30px,radial-gradient(circle at 70% 60%,rgba(0,60,0,.18) 0 2px,transparent 3px) 0 0/28px 26px;pointer-events:none}
.holes{position:relative;width:100%;max-width:560px;height:100%;max-height:420px;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(2,1fr);gap:10px 12px}
.hole{position:relative;border:0;background:none;padding:0;overflow:hidden;display:flex;align-items:flex-end;justify-content:center;border-radius:0 0 50% 50% / 0 0 30% 30%;touch-action:manipulation}
.hole::after{content:"";position:absolute;left:4%;right:4%;bottom:0;height:30%;border-radius:50%;background:radial-gradient(ellipse at 50% 35%,#2A1A0C,#4A2E14 70%);box-shadow:0 3px 0 #6B4220;z-index:0}
.mole{position:relative;z-index:1;width:86%;max-width:150px;transform:translateY(105%);transition:transform .22s cubic-bezier(.3,1.4,.5,1);display:grid;justify-items:center;pointer-events:none;margin-bottom:8%}
.hole.up .mole{transform:translateY(0)}
.hole.hit .mole{transform:translateY(25%) scale(.92);transition-duration:.12s}
.sign{position:relative;z-index:2;max-width:100%;background:#FFF6E0;color:#2B1700;border-radius:10px;padding:5px 9px;font:900 clamp(13px,3.6vw,17px)/1.1 var(--display);box-shadow:0 2px 0 #C8A46A;overflow-wrap:anywhere;text-align:center;margin-bottom:-6px}
.hole.right .sign{background:var(--green);color:#fff;box-shadow:0 2px 0 #0B5E29}
