  background:radial-gradient(circle,#fff 0 18%,transparent 19%),conic-gradient(from 0deg,#FFE27A 0 10%,transparent 10% 20%,#FFE27A 20% 30%,transparent 30% 40%,#FFE27A 40% 50%,transparent 50% 60%,#FFE27A 60% 70%,transparent 70% 80%,#FFE27A 80% 90%,transparent 90%);border-radius:50%}
.pow.go{animation:pow .35s ease-out}
@keyframes pow{0%{opacity:1;transform:translate(-50%,-50%) scale(.3)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.4)}}
.foot{flex:none;display:flex;align-items:center;gap:8px;min-height:36px}
