whack.js:
/* ═════════ Whack-a-Word ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 1;              // hidden tier: Recognize
const COIN = 2;              // per right whack, times TIER (+1 on a combo of 3 or more)
const ROUND = 12;            // meanings per round
const LIVES = 3;
const MISS_AFTER = 3;        // the right mole hides this many times unhit, then the word counts as missed

const text = {
  en:{title:'Whack-a-Word',lede:'Moles pop up holding words. Whack the one that matches the meaning, and only that one.',
      rules:['<b>Read the meaning</b> at the top, then whack the mole holding that word.','<b>Whacking a wrong mole</b> costs a heart. Hitting everything loses fast.','The right mole hides again if you wait too long. After three escapes it counts as missed.'],
      start:'Start whacking',which:'Whack the word that means',combo:n=>`Combo ×${n}`,right:c=>`Got it · +${c}`,escaped:w=>`It got away · it was ${w}`,
      done:'Garden cleared',over:'Out of hearts',stCoins:'coins',stHit:'right whacks',stBest:'best combo',praise:n=>`${n} in a row without a single wrong whack.`},
  uz:{title:'So\'zni ur',lede:'Inlardan so\'z ushlagan jonivorlar chiqadi. Ma\'noga mos so\'zni ushlaganini, faqat o\'shani uring.',
      rules:['<b>Tepadagi ma\'noni o\'qing</b>, so\'ng o\'sha so\'zni ushlagan jonivorni uring.','<b>Noto\'g\'ri jonivorni ursangiz</b>, bitta yurak yo\'qoladi. Hammasini urish tez yutqazadi.','Uzoq kutsangiz, to\'g\'ri jonivor yana yashirinadi. Uch marta qochsa, so\'z o\'tkazib yuborilgan hisoblanadi.'],
      start:'Boshlash',which:'Shu ma\'nodagi so\'zni uring',combo:n=>`Ketma-ket ×${n}`,right:c=>`Topdingiz · +${c}`,escaped:w=>`Qochib ketdi · javob: ${w}`,
      done:'Bog\' tozalandi',over:'Yuraklar tugadi',stCoins:'tanga',stHit:'to\'g\'ri zarba',stBest:'eng uzun ketma-ketlik',praise:n=>`${n} ta ketma-ket, birorta ham xato zarbasiz.`}
};

const MOLE=c=>`<svg viewBox="0 0 96 80" aria-hidden="true"><ellipse cx="48" cy="58" rx="38" ry="30" fill="${c}"/><ellipse cx="48" cy="64" rx="22" ry="16" fill="#E8C9A8"/><circle cx="35" cy="44" r="5" fill="#1C1C1E"/><circle cx="61" cy="44" r="5" fill="#1C1C1E"/><circle cx="36.5" cy="42.5" r="1.6" fill="#fff"/><circle cx="62.5" cy="42.5" r="1.6" fill="#fff"/><ellipse cx="48" cy="54" rx="7" ry="5" fill="#FF8FB0"/><path d="M42 61q6 4 12 0" stroke="#5A3A2A" stroke-width="2.4" fill="none" stroke-linecap="round"/><ellipse cx="26" cy="56" rx="5" ry="3" fill="#FF9EC0" opacity=".7"/><ellipse cx="70" cy="56" rx="5" ry="3" fill="#FF9EC0" opacity=".7"/></svg>`;
const MOLE_COLS=['#8A5A3C','#7A4E34','#9A6A48','#6E4630','#A0704C','#845238'];

let G=null, T=null, holes=[];
function buildHoles(){
  $('holes').innerHTML=[...Array(6)].map((_,i)=>`<button class="hole" data-h="${i}" aria-label="Hole ${i+1}"><div class="mole"><span class="sign"></span>${MOLE(MOLE_COLS[i])}</div><i class="pow"></i></button>`).join('');
  holes=[...$('holes').children].map(el=>({el,up:false,word:null,until:0}));
}
function newRound(preview){
  clearTimers();
  const eng=K.engine(K.words);
  G={eng,n:0,lives:LIVES,coins:0,hits:0,combo:0,best:0,stay:1.9,gap:.85,set:null,preview:!!preview,over:false,t:0,nextPop:0};
  buildHoles(); K.hearts($('lives'),LIVES,LIVES); $('coinTxt').textContent=0; $('combo').textContent='';
  nextMeaning();
}
function nextMeaning(){
  if(G.n>=ROUND) return finish(true);
  G.n++; $('progChip').textContent=`${G.n}/${ROUND}`;
  const w=G.eng.next(1+Math.min(2,Math.floor(G.n/5)));
  const opts=K.options(w,K.words,5);
  G.set={w,opts,appear:0,sinceRight:0,resolved:false};
  holes.forEach(h=>{ h.up=false; h.word=null; h.el.className='hole' });
  $('def').textContent=w.d; $('prompt').classList.remove('ok'); $('badge').hidden=true;
  G.nextPop=.5;
}
function pop(){
  const free=holes.filter(h=>!h.up); if(!free.length) return;
  const h=free[Math.floor(K.rng()*free.length)];
  const s=G.set, upWords=holes.filter(x=>x.up).map(x=>x.word.id);
  // the right word comes up regularly; other words fill the rest, never two of the same at once
  let word;
  if(!upWords.includes(s.w.id) && (s.sinceRight>=2 || K.rng()<.38)) word=s.w;
  else { const pool=s.opts.filter(o=>o.id!==s.w.id&&!upWords.includes(o.id)); word=pool.length?pool[Math.floor(K.rng()*pool.length)]:s.w }
  if(word===s.w){ s.appear++; s.sinceRight=0 } else s.sinceRight++;
  h.word=word; h.up=true; h.until=G.t+G.stay*(word===s.w?1:.9+K.rng()*.3);
  h.el.querySelector('.sign').textContent=word.w; h.el.classList.add('up'); h.el.classList.remove('hit','right','wrongpick','missed');
  tone(500+K.rng()*200,.05,{type:'triangle',v:.03});
}
function hide(h){ h.up=false; h.el.classList.remove('up') }

let raf=0, last=0, timers=[];
function clearTimers(){ timers.forEach(clearTimeout); timers=[] }
function loop(now){
  const dt=Math.min(.05,(now-last)/1000); last=now;
  if(G&&!G.preview&&!G.over&&G.set&&!G.set.resolved&&$('startOv').hidden&&!document.hidden){
    G.t+=dt;
    for(const h of holes){ if(h.up&&G.t>=h.until){ const wasRight=h.word.id===G.set.w.id; hide(h); if(wasRight&&G.set.appear>=MISS_AFTER) { escaped(); break } } }
    G.nextPop-=dt; if(G.nextPop<=0&&!G.set.resolved){ pop(); G.nextPop=G.gap*(.7+K.rng()*.6) }
  }
  raf=requestAnimationFrame(loop);
}
raf=requestAnimationFrame(t=>{last=t;loop(t)});

$('holes').addEventListener('pointerdown',e=>{
  const el=e.target.closest('.hole'); if(!el||!G||G.preview||G.over||!G.set||G.set.resolved) return;
  const h=holes[+el.dataset.h]; if(!h.up) return;
  e.preventDefault();
  const p=el.querySelector('.pow'); p.classList.remove('go'); void p.offsetWidth; p.classList.add('go');
  el.classList.add('hit'); noise(.08,{v:.4,f:600,type:'lowpass'});
  const ok=h.word.id===G.set.w.id;
  if(ok) return whackRight(h);
  // wrong whack: costs a heart; the word itself is not scheduled as wrong (the student didn't pick it as the meaning of the target)
  G.lives--; G.combo=0; K.hearts($('lives'),G.lives,LIVES); $('combo').textContent='';
  el.classList.add('wrongpick'); SFX.wrong(); K.badge($('badge'),T.notQuite(G.set.w.w),false,1600);
  G.eng.submit(G.set.w.id,false);   // only the first answer counts, so a later right whack still shows the word, with no strong evidence
  timers.push(setTimeout(()=>hide(h),350));
  if(G.lives<=0){ G.over=true; timers.push(setTimeout(()=>finish(false),900)) }
});
function whackRight(h){
  const s=G.set; s.resolved=true;
  G.eng.submit(s.w.id,true,'weak');
  G.hits++; G.combo++; G.best=Math.max(G.best,G.combo);
  const c=COIN*TIER+(G.combo>=3?TIER:0); G.coins+=c; $('coinTxt').textContent=G.coins;
  h.el.classList.add('right'); $('prompt').classList.add('ok');
  SFX.right(G.combo); timers.push(setTimeout(()=>SFX.coin(),140)); K.badge($('badge'),T.right(c),true,1200);
  $('combo').textContent=G.combo>=2?T.combo(G.combo):'';
  if(G.combo===6) K.doni(T.praise(G.combo));
  // adapt: a little faster while it goes well
  G.stay=Math.max(1.15,G.stay*.95); G.gap=Math.max(.5,G.gap*.96);
  timers.push(setTimeout(()=>{ holes.forEach(hide); timers.push(setTimeout(nextMeaning,300)) },700));
}
function escaped(){
  const s=G.set; s.resolved=true; G.combo=0; $('combo').textContent='';
  G.eng.submit(s.w.id,false); SFX.wrong();
  K.badge($('badge'),T.escaped(s.w.w),false,1800);
  // show the word that escaped, then move on; slower after a miss
  const h=holes.find(x=>!x.up)||holes[0]; h.word=s.w; h.el.querySelector('.sign').textContent=s.w.w; h.el.classList.add('up','missed'); h.up=true;
  G.stay=Math.min(2.4,G.stay*1.08); G.gap=Math.min(1,G.gap*1.05);
  timers.push(setTimeout(()=>{ holes.forEach(hide); timers.push(setTimeout(nextMeaning,300)) },1500));
}
$('idk').addEventListener('click',()=>{ if(!G||G.preview||G.over||!G.set||G.set.resolved) return; escaped() });

function finish(cleared){
  G.over=true; clearTimers(); holes.forEach(hide);
  cleared?SFX.win():SFX.end();
  K.end({title:cleared?T.done:T.over,stats:[{v:G.coins,l:T.stCoins},{v:`${G.hits}/${G.n}`,l:T.stHit},{v:G.best,l:T.stBest}],
    results:G.eng.results(),payload:{game:'whack-a-word',tier:TIER,coins:G.coins}});
}

K.setup({text,
  onText:t=>{ T=t },
  preview:()=>{ T=K.T; newRound(true); /* show a still garden behind the start screen */ holes.slice(0,3).forEach((h,i)=>{ const w=G.set.opts[i]; h.word=w; h.el.querySelector('.sign').textContent=w.w; h.el.classList.add('up') }) },
  start:()=>{ T=K.T; newRound(false) }
});
})();

