/* Star Pairs: words and meanings as stars joined by lines; Recognize violet stage */
:root{--stage:#6A3DF0}
.prompt.slim{padding:10px 14px}
.sky{position:relative;flex:1 1 auto;min-height:300px;border-radius:24px;background:radial-gradient(120% 90% at 30% 0%,#3A1FA8,#120836 75%);padding:12px;display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:14px 26px;align-content:center;overflow:hidden}
