/* ═════════ Star Pairs (match pairs) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone} = K;
const TIER = 1;              // hidden tier: Recognize
const COIN = 2;              // per pair matched on the first try, times TIER; 1 after a miss
const BOARDS = 3, PAIRS = 5; // 5 words with 6 meanings, so the last pair is never free
const LIVES = 4;

const text = {
  en:{title:'Star Pairs',lede:'Join each word to its meaning to draw a constellation. One meaning in every sky belongs to no word.',
      rules:['<b>Tap a word</b>, then tap its meaning. Or start from a meaning.','<b>A wrong pair</b> costs a heart.','There is always one extra meaning, so the last pair still needs thinking.'],
      start:'Light up the sky',instr:(n,m)=>`Sky ${n} of ${m} · join each word to its meaning`,
      paired:c=>`Joined · +${c}`,notPair:'Not a pair',done:'Constellation complete',over:'Out of hearts',allDone:'Every sky is lit',
      stCoins:'coins',stPairs:'pairs joined',stFirst:'first try',praise:'Five pairs, no misses. A perfect sky.'},
  uz:{title:'Yulduz juftliklari',lede:'Har bir so\'zni ma\'nosiga ulab, yulduz turkumini chizing. Har bir osmonda bitta ma\'no hech qaysi so\'zga tegishli emas.',
      rules:['<b>So\'zni bosing</b>, so\'ng uning ma\'nosini bosing. Ma\'nodan ham boshlashingiz mumkin.','<b>Noto\'g\'ri juftlik</b> bitta yurakni oladi.','Har doim bitta ortiqcha ma\'no bor, shuning uchun oxirgi juftlik ham o\'ylashni talab qiladi.'],
      start:'Osmonni yoritish',instr:(n,m)=>`${m} tadan ${n}-osmon · har bir so\'zni ma\'nosiga ulang`,
      paired:c=>`Ulandi · +${c}`,notPair:'Juftlik emas',done:'Yulduz turkumi tayyor',over:'Yuraklar tugadi',allDone:'Hamma osmonlar yoritildi',
      stCoins:'tanga',stPairs:'ulangan juftliklar',stFirst:'birinchi urinish',praise:'Besh juftlik, bironta xatosiz. Mukammal osmon.'}
};

let G=null, T=null;
function newRound(preview){
  const eng=K.engine(K.words);
  G={eng,b:0,lives:LIVES,coins:0,pairs:0,first:0,preview:!!preview,over:false,B:null};
  K.hearts($('lives'),LIVES,LIVES); $('coinTxt').textContent=0; nextBoard();
}
function nextBoard(){
  if(G.b>=BOARDS) return finish(true);
  G.b++; $('progChip').textContent=`${G.b}/${BOARDS}`;
  const words=[]; for(let i=0;i<PAIRS;i++) words.push(G.eng.next(1+Math.min(2,G.b-1),words.map(w=>w.id)));
  // the decoy meaning comes from a word not on this board
  const decoy=K.shuffle(K.words.filter(w=>!words.some(x=>x.id===w.id)&&!words.some(x=>K.confused(x.id).has(w.id))))[0];
  G.B={words,defs:K.shuffle([...words,decoy]),decoy:decoy.id,sel:null,done:new Set(),missed:new Set(),lines:[]};
  $('instr').textContent=T.instr(G.b,BOARDS);
  $('colW').innerHTML=K.shuffle([...words]).map(w=>`<button class="card" data-side="w" data-id="${w.id}">${esc(w.w)}</button>`).join('');
  $('colD').innerHTML=G.B.defs.map(w=>`<button class="card" data-side="d" data-id="${w.id}">${esc(w.d)}</button>`).join('');
  $('lines').innerHTML='';
}
function cardEl(side,id){ return document.querySelector(`#col${side==='w'?'W':'D'} .card[data-id="${id}"]`) }
function select(el){ document.querySelectorAll('.sky .card.sel').forEach(x=>x.classList.remove('sel')); if(el) el.classList.add('sel') }
$('sky').addEventListener('click',e=>{
  const el=e.target.closest('.card'); if(!el||!G||G.preview||G.over||el.classList.contains('done')) return;
  const side=el.dataset.side, id=el.dataset.id, B=G.B;
  if(!B.sel||B.sel.side===side){ B.sel={side,id}; select(el); SFX.tap(); return }
  const wId = side==='w'?id:B.sel.id, dId = side==='d'?id:B.sel.id;
  const wEl=cardEl('w',wId), dEl=cardEl('d',dId);
  B.sel=null; select(null);
  if(wId===dId) return match(wEl,dEl,wId);
  // a wrong pair: the word's first answer is wrong, a heart is lost
  G.lives--; K.hearts($('lives'),G.lives,LIVES);
  if(!B.missed.has(wId)){ B.missed.add(wId); G.eng.submit(wId,false) }
  [wEl,dEl].forEach(x=>{ x.classList.remove('nope'); void x.offsetWidth; x.classList.add('nope') });
  SFX.wrong(); K.badge($('badge'),T.notPair,false,1200);
  if(G.lives<=0){ G.over=true; setTimeout(()=>finish(false),900) }
});
function match(wEl,dEl,id){
  const B=G.B, clean=!B.missed.has(id);
  if(clean){ G.eng.submit(id,true,'weak'); G.first++ }
  B.done.add(id); G.pairs++;
  const c=(clean?COIN:1)*TIER; G.coins+=c; $('coinTxt').textContent=G.coins;
  wEl.classList.add('done'); dEl.classList.add('done'); drawLine(wEl,dEl);
  SFX.right(B.done.size); setTimeout(()=>SFX.coin(),140); K.badge($('badge'),T.paired(c),true,1000);
  if(B.done.size===PAIRS){
    cardEl('d',B.decoy).classList.add('decoy');
    setTimeout(()=>{ [523,659,784,1047].forEach((f,i)=>tone(f,.18,{type:'triangle',v:.07,at:i*.08})); K.banner(T.done,''); if(B.missed.size===0) K.doni(T.praise) },450);
    setTimeout(nextBoard,2000);
  }
}
function drawLine(a,b){
  const sky=$('sky').getBoundingClientRect(), ra=a.getBoundingClientRect(), rb=b.getBoundingClientRect();
  const x1=ra.right-sky.left-4, y1=ra.top+ra.height/2-sky.top, x2=rb.left-sky.left+16, y2=rb.top+rb.height/2-sky.top;
  const len=Math.hypot(x2-x1,y2-y1);
  const l=document.createElementNS('http://www.w3.org/2000/svg','line');
  l.setAttribute('x1',x1); l.setAttribute('y1',y1); l.setAttribute('x2',x2); l.setAttribute('y2',y2); l.style.setProperty('--len',len);
  $('lines').appendChild(l); G.B.lines.push([a,b,l]);
}
// keep the lines attached when the screen size changes
new ResizeObserver(()=>{ if(!G||!G.B) return; G.B.lines.forEach(([a,b,l])=>{ const sky=$('sky').getBoundingClientRect(), ra=a.getBoundingClientRect(), rb=b.getBoundingClientRect();
  l.setAttribute('x1',ra.right-sky.left-4); l.setAttribute('y1',ra.top+ra.height/2-sky.top); l.setAttribute('x2',rb.left-sky.left+16); l.setAttribute('y2',rb.top+rb.height/2-sky.top); l.style.animation='none'; l.style.strokeDasharray='none' }) }).observe($('sky'));

function finish(done){
  G.over=true; done?SFX.win():SFX.end();
  K.end({title:done?T.allDone:T.over,stats:[{v:G.coins,l:T.stCoins},{v:`${G.pairs}/${BOARDS*PAIRS}`,l:T.stPairs},{v:G.first,l:T.stFirst}],
    results:G.eng.results(),payload:{game:'star-pairs',tier:TIER,coins:G.coins}});
}
K.setup({text,onText:t=>{ T=t; if(G&&G.B) $('instr').textContent=T.instr(G.b,BOARDS) },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

spelling.css:
/* Spell Check Sprint: a runner on a track, one word at a time; Recognize violet stage */
:root{--stage:#6A3DF0}
.track{flex:none;border-radius:20px;background:linear-gradient(#2F1A86,#24126A);padding:12px 14px 10px}
.lane{position:relative;height:34px;border-radius:99px;background:repeating-linear-gradient(90deg,rgba(255,255,255,.14) 0 22px,transparent 22px 44px),#3D25A0}
.runner{position:absolute;left:0;top:50%;width:30px;height:30px;margin-top:-15px;border-radius:50%;background:#fff;box-shadow:0 2px 0 rgba(0,0,0,.2);transition:left .35s cubic-bezier(.3,1.3,.5,1)}
