/* ═════════ Spell Check Sprint (real or fake spelling) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone} = K;
const TIER = 1;              // hidden tier: Recognize (spelling of known words)
const COIN = 1;              // per right call, times TIER; +1 on a streak of 5
const SECONDS = 40;
const LIVES = 3;             // a wrong call costs a heart: with a 1-in-2 guess, tapping at random runs out fast
const GOAL = 20;             // right calls to reach the finish line

const text = {
  en:{title:'Spell Check Sprint',lede:'A word flashes up. Is it spelled correctly, or is it a fake? Call it right to sprint to the finish.',
      rules:['<b>Real</b> if the spelling is correct, <b>Fake</b> if it is not. Arrow keys work too.','<b>A wrong call</b> costs a heart. Guessing at random runs out of hearts fast.','Reach the flag in 40 seconds for a bonus.'],
      start:'On your marks',isIt:'Real or fake?',real:'Real',fake:'Fake',spelled:w=>`It's spelled ${w}`,wasReal:'That one was spelled correctly',
      streak:n=>`Streak ×${n}`,finish:'Finish line!',time:'Time',over:'Out of hearts',stCoins:'coins',stRight:'right calls',stBest:'best streak',
      dist:(n,g)=>`${n}/${g} to the flag`,praise:'Ten right calls in a row.'},
  uz:{title:'Imlo yugurishi',lede:'Ekranda so\'z chiqadi. U to\'g\'ri yozilganmi yoki soxtami? To\'g\'ri topib, marraga yuguring.',
      rules:['Imlo to\'g\'ri bo\'lsa <b>To\'g\'ri</b>, noto\'g\'ri bo\'lsa <b>Soxta</b> ni bosing. Strelka tugmalari ham ishlaydi.','<b>Noto\'g\'ri javob</b> bitta yurakni oladi. Tasodifiy bosish tez yutqazadi.','40 soniyada bayroqqa yetsangiz, bonus olasiz.'],
      start:'Boshladik',isIt:'To\'g\'rimi yoki soxtami?',real:'To\'g\'ri',fake:'Soxta',spelled:w=>`To'g'ri yozilishi: ${w}`,wasReal:'Bu so\'z to\'g\'ri yozilgan edi',
      streak:n=>`Ketma-ket ×${n}`,finish:'Marra!',time:'Vaqt tugadi',over:'Yuraklar tugadi',stCoins:'tanga',stRight:'to\'g\'ri javob',stBest:'eng uzun ketma-ketlik',
      dist:(n,g)=>`bayroqqacha ${n}/${g}`,praise:'Ketma-ket o\'nta to\'g\'ri javob.'}
};

let G=null, T=null, timer=0;
function newRound(preview){
  clearInterval(timer);
  const eng=K.engine(K.words.filter(w=>w.sp&&w.sp.length));
  G={eng,lives:LIVES,coins:0,right:0,streak:0,best:0,left:SECONDS,preview:!!preview,over:false,item:null,busy:false,won:false};
  K.hearts($('lives'),LIVES,LIVES); $('coinTxt').textContent=0; $('timeChip').textContent=SECONDS+'s'; $('streak').textContent='';
  moveRunner(); nextWord();
  if(!preview) timer=setInterval(tick,1000);
}
function tick(){ if(G.over||document.hidden) return; G.left--; $('timeChip').textContent=G.left+'s'; if(G.left<=5) tone(1000,.05,{type:'square',v:.02}); if(G.left<=0) finish('time') }
function nextWord(){
  const w=G.eng.next(2);
  const real=K.rng()<.5;
  const shown=real?w.w:w.sp[Math.floor(K.rng()*w.sp.length)];
  G.item={w,real,shown}; G.busy=false;
  const c=$('card'); c.className='card'; $('word').textContent=shown; $('fixnote').textContent=''; $('badge').hidden=true;
  document.querySelector('.choice').classList.remove('locked');
}
function call(saysReal){
  if(!G||G.preview||G.over||G.busy) return;
  G.busy=true; document.querySelector('.choice').classList.add('locked');
  const it=G.item, ok=saysReal===it.real;
  G.eng.submit(it.w.id,ok,'weak');
  const c=$('card');
  if(ok){
    G.right++; G.streak++; G.best=Math.max(G.best,G.streak);
    const coins=COIN*TIER+(G.streak>=5?TIER:0); G.coins+=coins; $('coinTxt').textContent=G.coins;
    c.classList.add('ok'); SFX.right(Math.min(G.streak,8));
    if(!it.real) $('fixnote').textContent=T.spelled(it.w.w);
    $('streak').textContent=G.streak>=3?T.streak(G.streak):'';
    if(G.streak===10) K.doni(T.praise);
    moveRunner();
    if(G.right>=GOAL&&!G.won){ G.won=true; K.banner(T.finish,''); setTimeout(()=>finish('goal'),900); return }
    setTimeout(()=>{ c.classList.add('out'); setTimeout(nextWord,140) }, it.real?380:900);
  } else {
    G.lives--; G.streak=0; K.hearts($('lives'),G.lives,LIVES); $('streak').textContent='';
    c.classList.add('miss'); SFX.wrong();
    $('fixnote').textContent = it.real ? T.wasReal : T.spelled(it.w.w);
    if(G.lives<=0) return setTimeout(()=>finish('hearts'),1200);
    setTimeout(()=>{ c.classList.add('out'); setTimeout(nextWord,140) },1300);
  }
}
function moveRunner(){ const p=Math.min(1,G.right/GOAL); $('runner').style.left=`calc(${p*100}% - ${p*36}px)`; $('dist').innerHTML=`<span>${esc(T.dist(G.right,GOAL))}</span><span></span>` }
$('btnReal').addEventListener('click',()=>call(true));
$('btnFake').addEventListener('click',()=>call(false));
addEventListener('keydown',e=>{ if(!$('startOv').hidden||!$('endOv').hidden) return; if(e.key==='ArrowRight') call(true); else if(e.key==='ArrowLeft') call(false) });
function finish(why){
  if(G.over) return; G.over=true; clearInterval(timer);
  if(why==='goal'){ const b=5*TIER; G.coins+=b; SFX.win() } else SFX.end();
  K.end({title:why==='goal'?T.finish:why==='time'?T.time:T.over,stats:[{v:G.coins,l:T.stCoins},{v:G.right,l:T.stRight},{v:G.best,l:T.stBest}],
    results:G.eng.results(),payload:{game:'spell-check-sprint',tier:TIER,coins:G.coins}});
}
K.setup({text,onText:t=>{ T=t; if(G) moveRunner() },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

