mark.js:
/* ═════════ Secret Letters (mark the words) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 1;              // hidden tier: Recognize, but chosen in context, so evidence is medium
const COIN = 3;              // per word found on the first tap, times TIER; 1 after a wrong tap
const LETTERS = 4, PER = 3;  // 4 letters of 3 hidden words = 12 words
const LIVES = 3;
const SENDERS = ['Agent Fox','Agent Owl','Agent Lynx','Agent Moth'], SENDERS_UZ = ['Agent Tulki','Agent Boyo\'g\'li','Agent Silovsin','Agent Kapalak'];

const text = {
  en:{title:'Secret Letters',lede:'Your agents send coded letters. Each one hides three of your words. Read carefully and tap the word that matches each meaning.',
      rules:['<b>Read the meaning</b>, then tap that word in the letter.','<b>A wrong tap</b> costs a heart, so read before you tap.','Each letter is decoded when all three words are found.'],
      start:'Open the first letter',find:(n,m)=>`Find word ${n} of ${m} · it means`,to:n=>`TO: HEADQUARTERS · LETTER ${n}`,
      got:c=>`Found · +${c}`,notHere:'Not that word',shown:w=>`It was: ${w}`,decoded:'Letter decoded',over:'Out of hearts',done:'All letters decoded',
      note:n=>`${n} words hidden`,stCoins:'coins',stFound:'words found',stFirst:'first tap',praise:'Three words, three taps. Clean decode.'},
  uz:{title:'Maxfiy xatlar',lede:'Agentlaringiz shifrlangan xatlar yuboradi. Har birida uchta so\'zingiz yashiringan. Diqqat bilan o\'qing va har bir ma\'noga mos so\'zni bosing.',
      rules:['<b>Ma\'noni o\'qing</b>, so\'ng xatdagi o\'sha so\'zni bosing.','<b>Noto\'g\'ri bosish</b> bitta yurakni oladi, shuning uchun avval o\'qing.','Uchala so\'z topilganda xat ochiladi.'],
      start:'Birinchi xatni ochish',find:(n,m)=>`${m} tadan ${n}-so\'zni toping · ma\'nosi`,to:n=>`KIMGA: SHTAB · ${n}-XAT`,
      got:c=>`Topildi · +${c}`,notHere:'Bu so\'z emas',shown:w=>`Javob: ${w}`,decoded:'Xat ochildi',over:'Yuraklar tugadi',done:'Hamma xatlar ochildi',
      note:n=>`${n} ta so\'z yashiringan`,stCoins:'tanga',stFound:'topilgan so\'zlar',stFirst:'birinchi bosishda',praise:'Uch so\'z, uch bosish. Toza ochildi.'}
};

let G=null, T=null;
function newRound(preview){
  const eng=K.engine(K.words);
  G={eng,li:0,lives:LIVES,coins:0,found:0,first:0,total:0,preview:!!preview,over:false,L:null};
  K.hearts($('lives'),LIVES,LIVES); $('coinTxt').textContent=0;
  nextLetter();
}
function nextLetter(){
  if(G.li>=LETTERS) return finish(true);
  G.li++; $('progChip').textContent=`${G.li}/${LETTERS}`;
  const picked=[]; for(let i=0;i<PER;i++) picked.push(G.eng.next(1+Math.min(2,G.li-1),picked.map(w=>w.id)));
  const order=K.shuffle([...picked]);             // the order words are asked in differs from the order they appear
  G.L={words:picked,ask:order,k:0,miss:0,missed:new Set(),slips:0};
  $('letter').classList.remove('decoded','locked');
  $('lTo').textContent=T.to(G.li);
  $('lFrom').textContent='— '+(K.LEVELS[K.level].text==='uz'?SENDERS_UZ:SENDERS)[(G.li-1)%4];
  renderText(); ask();
}
function renderText(){
  const p=$('ltext'); p.innerHTML='';
  G.L.words.forEach((w,wi)=>{
    const sent=w.s.replace('___','\u0000');
    sent.split(/(\s+)/).forEach(part=>{
      if(/^\s+$/.test(part)){ p.appendChild(document.createTextNode(part)); return }
      let pre='',word=part,post='',isT=false;
      if(part.includes('\u0000')){ const [a,b]=part.split('\u0000'); pre=a; word=w.f; post=b; isT=true }
      else { const m=part.match(/^([^A-Za-z']*)([A-Za-z'-]+)([^A-Za-z']*)$/); if(!m){ p.appendChild(document.createTextNode(part)); return } pre=m[1]; word=m[2]; post=m[3] }
      if(pre) p.appendChild(document.createTextNode(pre));
      const b=document.createElement('button'); b.className='w'; b.type='button'; b.textContent=word; if(isT) b.dataset.wid=w.id;
      p.appendChild(b); if(post) p.appendChild(document.createTextNode(post));
    });
    p.appendChild(document.createTextNode(' '));
  });
}
function ask(){
  const L=G.L, w=L.ask[L.k]; L.miss=0;
  $('findLbl').textContent=T.find(L.k+1,PER); $('def').textContent=w.d; $('prompt').classList.remove('ok'); $('badge').hidden=true;
  $('found').innerHTML=L.ask.map((x,i)=>`<i class="${i<L.k?(L.missed.has(x.id)?'miss':'on'):''}"></i>`).join('');
  $('note').textContent=T.note(PER);
}
$('ltext').addEventListener('click',e=>{
  const b=e.target.closest('.w'); if(!b||!G||G.preview||G.over||b.classList.contains('got')||b.classList.contains('shown')) return;
  const L=G.L; if(L.wait||L.k>=PER) return; const w=L.ask[L.k];
  if(b.dataset.wid===w.id) return got(b,w);
  // a wrong tap: costs a heart; the word being asked counts as not known on this first answer
  L.miss++; L.slips++; G.lives--; K.hearts($('lives'),G.lives,LIVES);
  if(L.miss===1) G.eng.submit(w.id,false);
  b.classList.remove('nope'); void b.offsetWidth; b.classList.add('nope'); SFX.wrong(); K.badge($('badge'),T.notHere,false,1300);
  if(G.lives<=0){ G.over=true; showAnswer(w); setTimeout(()=>finish(false),1500) }
});
function got(b,w){
  const L=G.L;
  if(L.miss===0){ G.eng.submit(w.id,true,'medium'); G.first++ }
  const c=(L.miss===0?COIN:1)*TIER; G.coins+=c; G.found++; $('coinTxt').textContent=G.coins;
  b.classList.add('got'); $('prompt').classList.add('ok'); SFX.right(L.k); setTimeout(()=>SFX.coin(),140); K.badge($('badge'),T.got(c),true,1100);
  advance();
}
function showAnswer(w){ const b=$('ltext').querySelector(`[data-wid="${w.id}"]`); if(b) b.classList.add('shown'); K.badge($('badge'),T.shown(w.f),false,1800) }
$('idk').addEventListener('click',()=>{
  if(!G||G.preview||G.over) return; const L=G.L; if(L.wait||L.k>=PER) return; const w=L.ask[L.k];
  L.wait=true;   // one "I don't know" per word: a double tap must not skip the next word
  if(L.miss===0) G.eng.submit(w.id,false); L.missed.add(w.id); showAnswer(w); SFX.wrong(); setTimeout(()=>{ L.wait=false; advance() },900);
});
function advance(){
  const L=G.L; L.k++;
  if(L.k>=PER){
    const clean=L.missed.size===0&&L.slips===0;
    $('letter').classList.add('decoded','locked'); $('found').innerHTML=L.ask.map(x=>`<i class="${L.missed.has(x.id)?'miss':'on'}"></i>`).join('');
    noise(.12,{v:.4,f:500,type:'lowpass'}); tone(392,.12,{type:'triangle',v:.08,at:.05}); tone(587,.18,{type:'triangle',v:.08,at:.15});
    K.banner(T.decoded,''); if(clean) K.doni(T.praise);
    return setTimeout(nextLetter,1600);
  }
  setTimeout(ask,700);
}
function finish(done){
  G.over=true; done?SFX.win():SFX.end();
  K.end({title:done?T.done:T.over,stats:[{v:G.coins,l:T.stCoins},{v:`${G.found}/${LETTERS*PER}`,l:T.stFound},{v:G.first,l:T.stFirst}],
    results:G.eng.results(),payload:{game:'secret-letters',tier:TIER,coins:G.coins}});
}

K.setup({text,onText:t=>{ T=t },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

