/* ═════════ Word Connections ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone} = K;
const TIER = 2;              // hidden tier: Connect (tell similar words apart)
const COIN = 3;              // per group found, times TIER; minus 1 for each mistake in this puzzle (at least 1)
const MISTAKES = 4;

/* Content: puzzles of three groups of four. Category names are helper text in the list's own language.
   Each group must be unambiguous: no tile may fit a second group (content rule). */
const PUZZLES = {
  a2:[
    [{c:'Uydagi joylar',w:['kitchen','bathroom','bedroom','garden']},{c:'Ob-havo',w:['rainy','sunny','windy','cloudy']},{c:'His-tuyg\'ular',w:['angry','tired','happy','bored']}],
    [{c:'Kiyimlar',w:['jacket','scarf','gloves','boots']},{c:'Kasblar',w:['doctor','driver','farmer','teacher']},{c:'Ertalabki ovqat',w:['bread','eggs','cereal','milk']}],
    [{c:'Pul bilan bog\'liq',w:['cheap','expensive','price','change']},{c:'Sayohat',w:['journey','ticket','luggage','passport']},{c:'Maktab',w:['homework','library','lesson','exam']}]],
  c1:[
    [{c:'Short-lived',w:['ephemeral','transient','fleeting','momentary']},{c:'Found everywhere',w:['ubiquitous','pervasive','omnipresent','universal']},{c:'Unpredictable',w:['erratic','capricious','mercurial','volatile']}],
    [{c:'Criticise someone',w:['admonish','reproach','chide','berate']},{c:'Praise someone',w:['exalt','extol','laud','commend']},{c:'Make someone do something',w:['coerce','compel','cajole','induce']}],
    [{c:'Not enough',w:['paucity','dearth','scarcity','shortage']},{c:'Too much',w:['glut','surfeit','plethora','profusion']},{c:'Plain, without decoration',w:['austere','spartan','unadorned','stark']}]]
};

const text = {
  en:{title:'Word Connections',lede:'Twelve words hide three groups of four. Find what connects them.',
      rules:['<b>Pick four words</b> you think belong together, then submit.','<b>Four mistakes</b> per puzzle. "One away" means three of your four are right.','No timer. Shuffle the tiles if you get stuck.'],
      start:'Start the puzzle',instr:(n,m)=>`Puzzle ${n} of ${m} · find groups of four`,shuffle:'Shuffle',deselect:'Clear',submit:'Submit',pick:n=>`Pick ${n} more`,
      oneAway:'One away…',nope:'Not a group',already:'You tried that one',found:c=>`Group found · +${c}`,solvedAll:'Puzzle solved',out:'Out of mistakes',
      next:'Next puzzle',doneT:'All puzzles solved',overT:'Puzzles complete',stCoins:'coins',stGroups:'groups found',stPerfect:'perfect puzzles',praise:'No mistakes at all. Sharp.'},
  uz:{title:'So\'z guruhlari',lede:'O\'n ikki so\'zda to\'rttadan uchta guruh yashiringan. Ularni nima bog\'lashini toping.',
      rules:['<b>Bir guruhga tegishli</b> deb o\'ylagan to\'rtta so\'zni tanlang va yuboring.','Har bir boshqotirmada <b>to\'rtta xato</b> imkoniyati bor. "Bittasi qoldi" degani to\'rttadan uchtasi to\'g\'ri.','Vaqt chegarasi yo\'q. Qiyin bo\'lsa, aralashtiring.'],
      start:'Boshlash',instr:(n,m)=>`${m} tadan ${n}-boshqotirma · to\'rttalik guruhlarni toping`,shuffle:'Aralashtirish',deselect:'Tozalash',submit:'Yuborish',pick:n=>`Yana ${n} ta tanlang`,
      oneAway:'Bittasi qoldi…',nope:'Bu guruh emas',already:'Buni sinab ko\'rgansiz',found:c=>`Guruh topildi · +${c}`,solvedAll:'Boshqotirma yechildi',out:'Xatolar tugadi',
      next:'Keyingi boshqotirma',doneT:'Hamma boshqotirmalar yechildi',overT:'Boshqotirmalar tugadi',stCoins:'tanga',stGroups:'topilgan guruhlar',stPerfect:'xatosiz boshqotirmalar',praise:'Umuman xatosiz. Ajoyib.'}
};

let G=null, T=null;
function newRound(preview){
  const set=K.shuffle([...K.block('groups',PUZZLES)]);
  G={set,pi:-1,coins:0,groups:0,perfect:0,res:{},preview:!!preview,P:null};
  $('coinTxt').textContent=0; nextPuzzle();
}
function nextPuzzle(){
  G.pi++;
  if(G.pi>=G.set.length) return finish();
  const groups=G.set[G.pi].map((g,i)=>({...g,i,found:false}));
  const tiles=K.shuffle(groups.flatMap(g=>g.w.map(w=>({w,g:g.i}))));
  G.P={groups,tiles,sel:new Set(),mistakes:0,tried:new Set(),inWrong:new Set(),busy:false};
  $('progChip').textContent=`${G.pi+1}/${G.set.length}`; $('instr').textContent=T.instr(G.pi+1,G.set.length);
  $('solved').innerHTML=''; renderMist(); renderGrid(); updateSubmit();
}
function renderMist(){ $('mist').innerHTML=[...Array(MISTAKES)].map((_,i)=>`<i class="${i<G.P.mistakes?'used':''}"></i>`).join('') }
function renderGrid(){
  const P=G.P; $('grid').innerHTML=P.tiles.map((t,k)=>`<button class="tile${P.sel.has(k)?' sel':''}" data-k="${k}">${esc(t.w)}</button>`).join('');
  $('grid').classList.toggle('locked',P.busy);
}
function updateSubmit(){ const n=G.P.sel.size; const b=$('submitBtn'); b.disabled=n!==4||G.P.busy; b.textContent = n===4 ? T.submit : T.pick(4-n) }
$('grid').addEventListener('click',e=>{
  const b=e.target.closest('.tile'); if(!b||!G||G.preview||G.P.busy) return;
  const k=+b.dataset.k, P=G.P;
  if(P.sel.has(k)) P.sel.delete(k); else if(P.sel.size<4) P.sel.add(k); else return;
  b.classList.toggle('sel',P.sel.has(k)); SFX.tap(); updateSubmit();
});
$('shuffleBtn').addEventListener('click',()=>{ if(!G||G.P.busy) return; const P=G.P; const sel=[...P.sel].map(k=>P.tiles[k]); K.shuffle(P.tiles); P.sel=new Set(sel.map(t=>P.tiles.indexOf(t))); renderGrid(); tone(500,.06,{type:'triangle',v:.04}) });
$('clearBtn').addEventListener('click',()=>{ if(!G||G.P.busy) return; G.P.sel.clear(); renderGrid(); updateSubmit() });
$('submitBtn').addEventListener('click',submit);

function submit(){
  const P=G.P; if(P.sel.size!==4||P.busy) return;
  const picks=[...P.sel].map(k=>P.tiles[k]);
  const key=picks.map(t=>t.w).sort().join('|');
  if(P.tried.has(key)) return K.badge($('badge'),T.already,false,1300);
  P.tried.add(key);
  const counts={}; picks.forEach(t=>counts[t.g]=(counts[t.g]||0)+1);
  const best=Math.max(...Object.values(counts)), gi=+Object.keys(counts).find(g=>counts[g]===best);
  P.busy=true; renderGrid();
  // a little hop before the answer, like flipping cards over
  const els=[...P.sel].map(k=>$('grid').children[k]); els.forEach((el,i)=>setTimeout(()=>el.classList.add('jump'),i*80));
  setTimeout(()=>{
    if(best===4) return found(gi,picks);
    P.mistakes++; renderMist(); picks.forEach(t=>P.inWrong.add(t.w));
    els.forEach(el=>{ el.classList.remove('jump'); el.classList.add('shake') }); SFX.wrong();
    K.badge($('badge'),best===3?T.oneAway:T.nope,false,1500);
    P.busy=false;
    if(P.mistakes>=MISTAKES) return setTimeout(revealRest,700);
    setTimeout(()=>{ els.forEach(el=>el.classList.remove('shake')); renderGrid(); updateSubmit() },450);
  },420);
}
function found(gi,picks){
  const P=G.P, g=P.groups[gi]; g.found=true; G.groups++;
  // evidence per word: right if it was never part of a wrong guess; null if it was but its group was found later
  g.w.forEach(w=>{ if(G.res[w]===undefined) G.res[w]= P.inWrong.has(w)?null:true });
  const c=Math.max(1,COIN-P.mistakes)*TIER; G.coins+=c; $('coinTxt').textContent=G.coins;
  P.tiles=P.tiles.filter(t=>t.g!==gi); P.sel.clear(); P.busy=false;
  addSolved(g,false); renderGrid(); updateSubmit();
  SFX.right(P.groups.filter(x=>x.found).length); setTimeout(()=>SFX.coin(),140); K.badge($('badge'),T.found(c),true,1200);
  if(P.groups.every(x=>x.found)) puzzleDone(true);
}
function addSolved(g,missed){ const d=document.createElement('div'); d.className=`group g${g.i}${missed?' missed':''}`; d.innerHTML=`<b>${esc(g.c)}</b><span>${g.w.map(esc).join(' · ')}</span>`; $('solved').appendChild(d) }
function revealRest(){
  const P=G.P; P.busy=true;
  P.groups.filter(g=>!g.found).forEach(g=>{ g.w.forEach(w=>{ if(G.res[w]===undefined) G.res[w]=false }); addSolved(g,true) });
  P.tiles=[]; renderGrid(); K.banner(T.out,''); SFX.end(); puzzleDone(false);
}
function puzzleDone(ok){
  if(ok){ if(G.P.mistakes===0){ G.perfect++; K.doni(T.praise) } setTimeout(()=>{ K.banner(T.solvedAll,''); [523,659,784,1047].forEach((f,i)=>tone(f,.18,{type:'triangle',v:.07,at:i*.08})) },300) }
  const b=$('submitBtn'); b.disabled=false; b.textContent=G.pi>=G.set.length-1?T.doneT:T.next;
  b.onclick=()=>{ b.onclick=null; G.pi>=G.set.length-1?finish():nextPuzzle() };
  G.P.busy=true;
}
function finish(){
  $('submitBtn').onclick=null;
  const results=Object.entries(G.res).map(([w,ok])=>({wid:w,ok,evidence:ok===true?'medium':'none'}));
  SFX.win();
  K.end({title:G.groups===G.set.length*3?T.doneT:T.overT,stats:[{v:G.coins,l:T.stCoins},{v:`${G.groups}/${G.set.length*3}`,l:T.stGroups},{v:G.perfect,l:T.stPerfect}],
    results:results.map(r=>({...r,ok:r.ok===true})),payload:{game:'word-connections',tier:TIER,coins:G.coins,raw:results}});
}
K.setup({text,onText:t=>{ T=t; if(G&&G.P) $('instr').textContent=T.instr(G.pi+1,G.set.length) },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

