sort.js:
/* ═════════ Sorting Office (group sort) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 2;              // hidden tier: Connect (meaning and connotation)
const COIN = 2;              // per envelope sorted right first time, times TIER; +1 on a streak of 4
const LIVES = 3;

/* Content: sorting sets. Bins and notes are helper text in the list's own language; only unambiguous words (content rule). */
const SETS = {
  a2:[
    {q:'Qayerga tegishli?',bins:['Oshxona','Hammom','Yotoqxona'],items:[
      ['fridge',0,'Ovqatni sovuq saqlaydi'],['oven',0,'Unda pishiriladi'],['plate',0,'Ovqat qo\'yiladi'],['cooker',0,'Ovqat tayyorlash uchun'],
      ['shower',1,'Yuvinish uchun'],['towel',1,'Badanni artish uchun'],['toothbrush',1,'Tish tozalash uchun'],['soap',1,'Qo\'l yuvish uchun'],
      ['bed',2,'Unda uxlanadi'],['pillow',2,'Bosh qo\'yiladi'],['wardrobe',2,'Kiyimlar saqlanadi'],['blanket',2,'Usti yopiladi']]},
    {q:'Yaxshi hismi yoki yomon hismi?',bins:['Yaxshi his','Yomon his'],items:[
      ['happy',0,'Xursand'],['excited',0,'Hayajonlangan'],['relaxed',0,'Xotirjam'],['proud',0,'Faxrlangan'],['calm',0,'Tinch, sokin'],['glad',0,'Mamnun'],
      ['angry',1,'Jahli chiqqan'],['worried',1,'Xavotirlangan'],['bored',1,'Zerikkan'],['sad',1,'Xafa'],['scared',1,'Qo\'rqqan'],['upset',1,'Ko\'ngli buzilgan']]}],
  c1:[
    {q:'Positive or negative?',bins:['Positive','Negative'],items:[
      ['frugal',0,'careful with money, sensibly'],['stingy',1,'unwilling to spend or share'],['thrifty',0,'good at saving money'],['miserly',1,'hates spending, even when it is needed'],
      ['confident',0,'sure of yourself'],['arrogant',1,'thinks they are better than others'],['assertive',0,'states views firmly and respectfully'],['aggressive',1,'ready to attack or argue'],
      ['curious',0,'eager to learn'],['nosy',1,'too interested in other people\'s business'],['determined',0,'keeps going toward a goal'],['stubborn',1,'refuses to change, even when wrong']]},
    {q:'Too much, too little, or enough?',bins:['Too much','Too little','Enough'],items:[
      ['glut',0,'far more supply than is needed'],['surfeit',0,'an excessive amount'],['plethora',0,'a very large, often too large, amount'],['excess',0,'more than is allowed or needed'],
      ['paucity',1,'a scarcity of something'],['dearth',1,'a lack of something'],['scarcity',1,'not enough to meet demand'],['shortage',1,'less than is needed'],
      ['adequate',2,'good enough for the need'],['sufficient',2,'as much as is needed'],['satisfactory',2,'acceptable, meets the standard'],['enough',2,'as much as needed']]}]
};

const text = {
  en:{title:'Sorting Office',lede:'Envelopes keep arriving, each with one word. Read it and drop it into the right mailbag.',
      rules:['<b>Tap a mailbag</b> to post the envelope into it.','<b>A wrong bag</b> costs a heart, and the envelope shows why before it goes to the right one.','No timer: read each word before you post it.'],
      start:'Open the sorting office',instr:(n,m)=>`Envelope ${n} of ${m}`,right:c=>`Posted · +${c}`,wrong:'Wrong bag',
      done:'All sorted',over:'Out of hearts',stCoins:'coins',stRight:'sorted first time',stStreak:'best streak',praise:'Every envelope in the right bag.'},
  uz:{title:'Saralash bo\'limi',lede:'Konvertlar kelib turibdi, har birida bitta so\'z. Uni o\'qing va to\'g\'ri qopga tashlang.',
      rules:['Konvertni tashlash uchun <b>qopni bosing</b>.','<b>Noto\'g\'ri qop</b> bitta yurakni oladi, konvert esa to\'g\'ri qopga o\'tishdan oldin sababini ko\'rsatadi.','Vaqt chegarasi yo\'q: tashlashdan oldin so\'zni o\'qing.'],
      start:'Bo\'limni ochish',instr:(n,m)=>`${m} tadan ${n}-konvert`,right:c=>`Tashlandi · +${c}`,wrong:'Noto\'g\'ri qop',
      done:'Hammasi saralandi',over:'Yuraklar tugadi',stCoins:'tanga',stRight:'birinchi urinishda',stStreak:'eng uzun ketma-ketlik',praise:'Hamma konvert to\'g\'ri qopda.'}
};

let G=null, T=null;
function newRound(preview){
  const set=K.shuffle([...K.block('sorts',SETS)])[0];
  const items=K.shuffle(set.items.map(([w,b,d])=>({w,b,d})));
  G={set,items,i:-1,lives:LIVES,coins:0,right:0,streak:0,best:0,res:{},counts:set.bins.map(()=>0),busy:false,preview:!!preview,over:false};
  K.hearts($('lives'),LIVES,LIVES); $('coinTxt').textContent=0;
  $('question').textContent=set.q;
  const bags=$('bags'); bags.style.setProperty('--n',set.bins.length);
  bags.innerHTML=set.bins.map((b,i)=>`<button class="bag" data-b="${i}">${esc(b)}<small id="cnt${i}">0</small></button>`).join('');
  nextEnv();
}
function nextEnv(){
  G.i++; G.busy=false; $('bags').classList.remove('locked');
  if(G.i>=G.items.length) return finish(true);
  const it=G.items[G.i];
  $('instr').textContent=T.instr(G.i+1,G.items.length); $('progChip').textContent=`${G.i}/${G.items.length}`;
  const e=$('env'); e.style.transform=''; e.style.opacity=''; e.classList.remove('in'); void e.offsetWidth; e.classList.add('in');
  $('envWord').textContent=it.w; $('why').textContent='';
  $('queue').innerHTML='<i></i>'.repeat(Math.min(6,G.items.length-G.i-1));
  [...$('bags').children].forEach(b=>b.classList.remove('ok','right'));
  noise(.15,{v:.1,f:3500,q:.6});
}
$('bags').addEventListener('click',e=>{
  const bag=e.target.closest('.bag'); if(!bag||!G||G.preview||G.busy||G.over) return;
  G.busy=true; $('bags').classList.add('locked');
  const it=G.items[G.i], b=+bag.dataset.b, ok=b===it.b;
  if(G.res[it.w]===undefined) G.res[it.w]=ok;
  if(ok){
    G.right++; G.streak++; G.best=Math.max(G.best,G.streak);
    const c=COIN*TIER+(G.streak>=4?TIER:0); G.coins+=c; $('coinTxt').textContent=G.coins;
    post(bag,b,true); SFX.right(Math.min(G.streak,8)); setTimeout(()=>SFX.coin(),160); K.badge($('badge'),T.right(c),true,900);
    setTimeout(nextEnv,620);
  } else {
    G.lives--; G.streak=0; K.hearts($('lives'),G.lives,LIVES);
    const env=$('env'); env.classList.remove('bounce'); void env.offsetWidth; env.classList.add('bounce');
    $('why').textContent=it.d; SFX.wrong(); K.badge($('badge'),T.wrong,false,1400);
    const rightBag=$('bags').children[it.b]; rightBag.classList.add('right');
    if(G.lives<=0){ G.over=true; return setTimeout(()=>finish(false),1600) }
    setTimeout(()=>{ post(rightBag,it.b,false); setTimeout(nextEnv,620) },1600);
  }
});
function post(bag,b,ok){
  const env=$('env'), r1=env.getBoundingClientRect(), r2=bag.getBoundingClientRect();
  env.style.transform=`translate(${r2.left+r2.width/2-(r1.left+r1.width/2)}px,${r2.top-(r1.top+r1.height/2)}px) scale(.25)`; env.style.opacity='0';
  setTimeout(()=>{ G.counts[b]++; $('cnt'+b).textContent=G.counts[b]; bag.classList.remove('gulp'); void bag.offsetWidth; bag.classList.add('gulp'); if(ok) bag.classList.add('ok'); tone(300,.06,{type:'triangle',v:.05}) },380);
}
function finish(done){
  G.over=true; $('progChip').textContent=`${G.i}/${G.items.length}`;
  if(done&&G.right===G.items.length) K.doni(T.praise);
  done?SFX.win():SFX.end();
  const results=Object.entries(G.res).map(([w,ok])=>({wid:w,ok,evidence:ok?'medium':'none'}));
  K.end({title:done?T.done:T.over,stats:[{v:G.coins,l:T.stCoins},{v:`${G.right}/${G.items.length}`,l:T.stRight},{v:G.best,l:T.stStreak}],
    results,payload:{game:'sorting-office',tier:TIER,coins:G.coins,set:G.set.q}});
}
addEventListener('keydown',e=>{ if(!$('startOv').hidden||!$('endOv').hidden) return; const n=+e.key; if(n>=1&&n<=3){ const b=$('bags').children[n-1]; b&&b.click() } });
K.setup({text,onText:t=>{ T=t },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

