rank.js:
/* ═════════ Power Meter (rank order) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone} = K;
const TIER = 2;              // hidden tier: Connect (nuance between close words)
const PAY = [3,1];           // coins per set by check (1st, 2nd), times TIER
const ROUND = 5, CHECKS = 2;

/* Content: hand-written scales, mildest first. Labels and notes are helper text in the list's own language. */
const SETS = {
  a2:[
    {q:'Qanchalik issiq?',lo:'sovuq',hi:'issiq',w:[['cold','sovuq'],['cool','salqin'],['warm','iliq'],['hot','issiq']]},
    {q:'Qanchalik katta?',lo:'kichik',hi:'katta',w:[['tiny','juda kichik'],['small','kichik'],['big','katta'],['huge','ulkan']]},
    {q:'Qanchalik tez-tez?',lo:'kam',hi:'ko\'p',w:[['never','hech qachon'],['sometimes','ba\'zan'],['often','tez-tez'],['always','doimo']]},
    {q:'Qanchalik yaxshi?',lo:'yomon',hi:'a\'lo',w:[['bad','yomon'],['okay','o\'rtacha'],['good','yaxshi'],['excellent','a\'lo']]},
    {q:'Qanchalik baland ovozda?',lo:'past',hi:'baland',w:[['whisper','pichirlamoq'],['talk','gapirmoq'],['shout','baqirmoq']]},
    {q:'Qanchalik tez?',lo:'sekin',hi:'tez',w:[['walk','yurmoq'],['jog','yengil yugurmoq'],['run','yugurmoq'],['sprint','bor kuch bilan yugurmoq']]}],
  c1:[
    {q:'How angry?',lo:'mild',hi:'strong',w:[['irritated','a little annoyed'],['angry','clearly upset'],['furious','extremely angry']]},
    {q:'How happy?',lo:'mild',hi:'strong',w:[['content','quietly satisfied'],['happy','pleased'],['elated','very happy and excited'],['ecstatic','overwhelmed with joy']]},
    {q:'How afraid?',lo:'mild',hi:'strong',w:[['uneasy','slightly worried'],['anxious','nervous about what may happen'],['frightened','afraid'],['terrified','extremely afraid']]},
    {q:'How important?',lo:'least',hi:'most',w:[['trivial','hardly matters'],['minor','small in importance'],['significant','important'],['momentous','hugely important, historic']]},
    {q:'How big?',lo:'smaller',hi:'bigger',w:[['small','not big'],['large','big'],['huge','very big'],['gargantuan','enormous, giant']]},
    {q:'How often?',lo:'rarely',hi:'always',w:[['rarely','hardly ever'],['occasionally','now and then'],['frequently','often'],['constantly','all the time']]}]
};

const text = {
  en:{title:'Power Meter',lede:'Some words are close in meaning but differ in strength. Put each set in order, from mildest at the bottom to strongest at the top.',
      rules:['<b>Tap the words</b> from mildest to strongest; they fill the meter from the bottom.','<b>2 checks per set.</b> After a wrong check, the words in the right place lock in.','Fewer checks earn more coins. A set you can\'t order costs a star.'],
      start:'Power up',instr:(n,m)=>`Set ${n} of ${m}`,clear:'Clear',fill:n=>`${n} to place`,check:'Check the order',next:'Next set',finish:'See results',
      right:c=>`Perfect order · +${c}`,wrong:n=>`Not quite · ${n} in the right place`,answer:'Here is the right order',
      done:'Meter maxed out',stCoins:'coins',stSets:'sets in order',stFirst:'first check',praise:'Every set right on the first check.'},
  uz:{title:'Kuch o\'lchagich',lede:'Ba\'zi so\'zlar ma\'nosi yaqin, lekin kuchi har xil. Har bir to\'plamni pastda eng kuchsizdan tepada eng kuchligacha tartiblang.',
      rules:['So\'zlarni <b>eng kuchsizdan eng kuchligacha</b> bosing; ular o\'lchagichni pastdan to\'ldiradi.','<b>Har bir to\'plamga 2 tekshiruv.</b> Noto\'g\'ri tekshiruvdan keyin to\'g\'ri joydagi so\'zlar qotadi.','Kamroq tekshiruv ko\'proq tanga beradi. Tartiblay olmagan to\'plam bitta yulduzni oladi.'],
      start:'Boshlash',instr:(n,m)=>`${m} tadan ${n}-to\'plam`,clear:'Tozalash',fill:n=>`Yana ${n} ta`,check:'Tartibni tekshirish',next:'Keyingi to\'plam',finish:'Natijalar',
      right:c=>`To'g'ri tartib · +${c}`,wrong:n=>`Hali emas · ${n} tasi to'g'ri joyda`,answer:'To\'g\'ri tartib',
      done:'O\'lchagich to\'ldi',stCoins:'tanga',stSets:'tartiblangan to\'plamlar',stFirst:'birinchi tekshiruv',praise:'Hamma to\'plam birinchi tekshiruvda to\'g\'ri.'}
};
const starSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2l2.6 5.3 5.9.9-4.3 4.1 1 5.8L12 15.4 6.8 18.1l1-5.8L3.5 8.2l5.9-.9z" fill="#fff"/></svg>';
$('stars').innerHTML=starSvg.repeat(3);

let G=null, T=null;
function newRound(preview){
  const sets=K.shuffle([...K.block('scales',SETS)]).slice(0,ROUND);
  G={sets,si:-1,stars:3,coins:0,ordered:0,first:0,res:{},preview:!!preview,S:null};
  $('coinTxt').textContent=0; renderStars(); nextSet();
}
function renderStars(){ [...$('stars').children].forEach((s,i)=>s.classList.toggle('lost',i>=G.stars)) }
function nextSet(){
  G.si++;
  if(G.si>=G.sets.length) return finish();
  const set=G.sets[G.si], n=set.w.length;
  let pool=K.shuffle(set.w.map((x,i)=>({w:x[0],note:x[1],rank:i})));
  if(pool.every((p,i)=>p.rank===i)) pool.reverse();              // never start already in order
  G.S={set,n,pool,slots:Array(n).fill(null),locked:new Set(),checks:0,state:'build'};
  $('progChip').textContent=`${G.si+1}/${G.sets.length}`; $('instr').textContent=T.instr(G.si+1,G.sets.length);
  $('label').textContent=set.q; $('loLbl').textContent=set.lo; $('hiLbl').textContent=set.hi; $('badge').hidden=true;
  render();
}
function render(){
  const S=G.S;
  $('meter').innerHTML=S.slots.map((x,i)=>{
    const cls=x?(S.state==='solved'?'ok':S.state==='failed'?'answer':S.locked.has(i)?'locked':'filled'):'';
    return `<div class="slot ${cls}" data-i="${i}"><span class="lv">${i+1}</span>${x?esc(x.w):''}${x&&S.state!=='build'?`<span class="note">${esc(x.note)}</span>`:''}</div>`;
  }).join('');
  $('pool').innerHTML=S.pool.map((p,k)=>`<button class="chipw" data-k="${k}">${esc(p.w)}</button>`).join('');
  const b=$('checkBtn');
  if(S.state==='build'){ const left=S.pool.length; b.disabled=left>0; b.textContent=left?T.fill(left):T.check }
  else { b.disabled=false; b.textContent=G.si>=G.sets.length-1?T.finish:T.next }
  $('clearBtn').disabled=S.state!=='build';
}
$('pool').addEventListener('click',e=>{
  const c=e.target.closest('.chipw'); if(!c||!G||G.preview||G.S.state!=='build') return;
  const S=G.S, p=S.pool.splice(+c.dataset.k,1)[0];
  const i=S.slots.findIndex(x=>x===null); S.slots[i]=p; SFX.tap(); render();
  const el=$('meter').children[i]; el&&el.classList.add('in');
  tone(330+i*90,.08,{type:'triangle',v:.05});
});
$('meter').addEventListener('click',e=>{
  const s=e.target.closest('.slot'); if(!s||!G||G.S.state!=='build') return;
  const S=G.S, i=+s.dataset.i; if(!S.slots[i]||S.locked.has(i)) return;
  S.pool.push(S.slots[i]); S.slots[i]=null;
  // unlocked words above slide down, locked ones stay
  const free=S.slots.filter((x,j)=>x&&!S.locked.has(j)); S.slots=S.slots.map((x,j)=>S.locked.has(j)?x:null);
  let fi=0; for(let j=0;j<S.n&&fi<free.length;j++) if(!S.locked.has(j)) S.slots[j]=free[fi++];
  render();
});
$('clearBtn').addEventListener('click',()=>{ const S=G.S; if(!S||S.state!=='build') return; S.slots.forEach((x,i)=>{ if(x&&!S.locked.has(i)){ S.pool.push(x); S.slots[i]=null } }); render() });
$('checkBtn').addEventListener('click',()=>{
  const S=G.S; if(!S) return;
  if(S.state!=='build') return nextSet();
  if(S.pool.length) return;
  S.checks++;
  const ok=S.slots.every((x,i)=>x.rank===i);
  if(S.checks===1) S.set.w.forEach((x,i)=>{ const at=S.slots.findIndex(s=>s.w===x[0]); if(G.res[x[0]]===undefined) G.res[x[0]]=at===i });
  if(ok){
    S.state='solved'; const c=PAY[S.checks-1]*TIER; G.coins+=c; G.ordered++; if(S.checks===1) G.first++; $('coinTxt').textContent=G.coins;
    render(); [...$('meter').children].forEach((el,i)=>setTimeout(()=>{ el.classList.add('in'); tone(392*Math.pow(1.12,i),.12,{type:'triangle',v:.08}) },i*110));
    setTimeout(()=>SFX.coin(),S.n*110+80); K.badge($('badge'),T.right(c),true,1500);
    return;
  }
  let n=0; S.slots.forEach((x,i)=>{ if(x.rank===i){ S.locked.add(i); n++ } });
  S.slots.forEach((x,i)=>{ if(!S.locked.has(i)){ S.pool.push(x); S.slots[i]=null } }); K.shuffle(S.pool);
  SFX.wrong(); K.badge($('badge'),T.wrong(n),false,1600);
  if(S.checks>=CHECKS){
    S.state='failed'; G.stars=Math.max(0,G.stars-1); renderStars();
    S.slots=[...S.set.w].map((x,i)=>({w:x[0],note:x[1],rank:i})); S.pool=[];
    K.badge($('badge'),T.answer,false,1800);
  }
  render();
});
function finish(){
  G.coins+=G.stars*TIER; $('coinTxt').textContent=G.coins;
  if(G.first===G.sets.length) K.doni(T.praise);
  SFX.win();
  const results=Object.entries(G.res).map(([w,ok])=>({wid:w,ok,evidence:ok?'medium':'none'}));
  K.end({title:T.done,stats:[{v:G.coins,l:T.stCoins},{v:`${G.ordered}/${G.sets.length}`,l:T.stSets},{v:G.first,l:T.stFirst}],
    results,payload:{game:'power-meter',tier:TIER,coins:G.coins,stars:G.stars}});
}
K.setup({text,onText:t=>{ T=t },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

parts.css:
/* Word Lab: combine prefixes, roots and suffixes in flasks; Connect stage pink */
:root{--stage:#D92F7A}
.bench{position:relative;flex:1 1 auto;min-height:190px;border-radius:24px;background:linear-gradient(#3E1040,#2A0A2C);padding:16px 12px 14px;display:grid;align-content:center;gap:12px;overflow:hidden}
.bench::after{content:"";position:absolute;left:0;right:0;bottom:0;height:18px;background:#5A2A46}
.flasks{position:relative;z-index:1;display:flex;justify-content:center;align-items:flex-end;gap:6px;flex-wrap:wrap}
.flask{position:relative;border:0;width:clamp(86px,26vw,120px);height:96px;background:none;padding:0;color:var(--ink);cursor:pointer}
.flask .glass{position:absolute;inset:0;border-radius:14px 14px 30px 30px;background:rgba(255,255,255,.12);box-shadow:inset 0 0 0 2px rgba(255,255,255,.35)}
.flask .glass::before{content:"";position:absolute;top:-10px;left:32%;right:32%;height:14px;border-radius:4px 4px 0 0;background:rgba(255,255,255,.12);box-shadow:inset 0 0 0 2px rgba(255,255,255,.35)}
.flask .liq{position:absolute;left:3px;right:3px;bottom:3px;height:0;border-radius:6px 6px 27px 27px;transition:height .35s cubic-bezier(.3,1.3,.5,1)}
.flask.full .liq{height:62%}
.flask .tag{position:absolute;left:0;right:0;bottom:18px;text-align:center;font:900 clamp(15px,4.4vw,19px) var(--display);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.4)}
.flask .type{position:absolute;left:0;right:0;top:-28px;text-align:center;font:800 10.5px var(--display);text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.7)}
.plus{color:rgba(255,255,255,.6);font:900 22px var(--display);align-self:center;padding-top:20px}
.t-pre .liq{background:linear-gradient(#FFE27A,#F5B700)}
.t-root .liq{background:linear-gradient(#9FE3D4,#3CB8A0)}
.t-suf .liq{background:linear-gradient(#C9B8FF,#8A6AF0)}
.flask.bubble .liq{animation:bub .6s ease}
@keyframes bub{0%,100%{filter:none}50%{filter:brightness(1.4)}}
.result{position:relative;z-index:1;min-height:44px;text-align:center;font:900 clamp(26px,8vw,38px)/1.1 var(--display);letter-spacing:.01em}
.result.ok{color:#9BF0B0;text-shadow:0 0 18px rgba(60,196,106,.6)}
.result.no{color:#fff;opacity:.6;text-decoration:line-through}
.break{position:relative;z-index:1;display:flex;flex-wrap:wrap;justify-content:center;gap:6px}
.break span{background:rgba(255,255,255,.14);border-radius:99px;padding:5px 11px;font:700 13.5px var(--display)}
.break b{font-weight:900}
.shelf{flex:none;display:flex;flex-wrap:wrap;gap:8px;justify-content:center}
.part{border:0;border-radius:14px;min-height:46px;padding:8px 14px;font:900 17px var(--display);color:var(--ink);transition:transform .12s,opacity .2s}
.part small{display:block;font:700 10px var(--display);text-transform:uppercase;letter-spacing:.06em;opacity:.65}
.part.t-pre{background:#FFE27A}.part.t-root{background:#9FE3D4}.part.t-suf{background:#C9B8FF}
.part:active{transform:scale(.95)}
.part.used{opacity:.3;pointer-events:none}
.actions{flex:none;display:grid;grid-template-columns:auto 1fr;gap:8px}
@media (prefers-reduced-motion:reduce){.flask .liq{transition:none}.flask.bubble .liq{animation:none}}

