/* ═════════ Word Lab (word-part builder) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 2;              // hidden tier: Connect (word families and parts)
const PAY = [3,1];           // coins by try (1st, 2nd), times TIER
const ROUND = 10, LIVES = 4, TRIES = 2;

/* Content: parts with their meaning (helper text in the list's own language) and words built from them.
   The C1 parts come from the Prefix & Suffix list in claude/sat-words.md. */
const LAB = {
  a2:{parts:{
      un:['pre','emas'],re:['pre','qayta'],dis:['pre','teskari, emas'],im:['pre','emas'],pre:['pre','oldin'],
      happy:['root','xursand'],write:['root','yozmoq'],care:['root','ehtiyot'],help:['root','yordam'],teach:['root','o\'rgatmoq'],quick:['root','tez'],
      like:['root','yoqtirmoq'],play:['root','o\'ynamoq'],possible:['root','mumkin'],view:['root','ko\'rish'],kind:['root','mehribon'],read:['root','o\'qimoq'],
      ful:['suf','to\'la'],less:['suf','-siz'],er:['suf','qiluvchi odam'],ly:['suf','tarzda'],ness:['suf','holat, xususiyat']},
    words:[
      {w:'unhappy',p:['un','happy'],d:'Xursand emas'},{w:'rewrite',p:['re','write'],d:'Qayta yozmoq'},{w:'careful',p:['care','ful'],d:'Ehtiyotkor'},
      {w:'helpless',p:['help','less'],d:'Yordamsiz, ojiz'},{w:'teacher',p:['teach','er'],d:'Dars beradigan odam'},{w:'quickly',p:['quick','ly'],d:'Tez tarzda'},
      {w:'dislike',p:['dis','like'],d:'Yoqtirmaslik'},{w:'playful',p:['play','ful'],d:'O\'ynoqi, sho\'x'},{w:'impossible',p:['im','possible'],d:'Imkonsiz'},
      {w:'preview',p:['pre','view'],d:'Oldindan ko\'rish'},{w:'kindness',p:['kind','ness'],d:'Mehribonlik'},{w:'reader',p:['read','er'],d:'Kitob o\'qiydigan odam'}]},
  c1:{parts:{
      bio:['pre','life'],tele:['pre','far'],auto:['pre','self'],trans:['pre','across'],inter:['pre','between'],pre:['pre','before'],
      in:['pre','not'],dis:['pre','away'],sub:['pre','under'],circum:['pre','around'],mal:['pre','bad'],re:['pre','back, again'],
      logy:['suf','study of'],scope:['root','look, see'],graph:['root','write'],port:['root','carry'],rupt:['root','break'],dict:['root','say'],
      vis:['root','see'],cred:['root','believe'],miss:['root','send'],way:['root','path'],vent:['root','come'],function:['root','work'],ject:['root','throw'],
      ible:['suf','able to be']},
    words:[
      {w:'biology',p:['bio','logy'],d:'The study of living things'},{w:'telescope',p:['tele','scope'],d:'An instrument for seeing things far away'},
      {w:'autograph',p:['auto','graph'],d:'A signature you write yourself'},{w:'transport',p:['trans','port'],d:'To carry from one place across to another'},
      {w:'interrupt',p:['inter','rupt'],d:'To break in while someone is speaking'},{w:'predict',p:['pre','dict'],d:'To say what will happen before it does'},
      {w:'visible',p:['vis','ible'],d:'Able to be seen'},{w:'incredible',p:['in','cred','ible'],d:'So surprising it is hard to believe'},
      {w:'dismiss',p:['dis','miss'],d:'To send someone away'},{w:'subway',p:['sub','way'],d:'A railway that runs under the ground'},
      {w:'circumvent',p:['circum','vent'],d:'To find a way around a problem or rule'},{w:'malfunction',p:['mal','function'],d:'To work badly or fail to work'},
      {w:'reject',p:['re','ject'],d:'To refuse, to throw back'}]}
};

const text = {
  en:{title:'Word Lab',lede:'Words are built from parts that carry meaning. Mix the right prefix, root and suffix to make the word that matches each meaning.',
      rules:['<b>Tap parts</b> to pour them into the flasks, in order. Tap a flask to empty it.','<b>Mix</b> to test your word. A wrong mix costs a heart; you get two tries per word.','After each word, the lab shows what every part means.'],
      start:'Open the lab',build:'Build the word that means',empty:'Empty',mix:'Mix',fill:n=>`Add ${n} more`,next:'Next word',finish:'See results',
      types:{pre:'prefix',root:'root',suf:'suffix'},ok:c=>`It works · +${c}`,no:'No such word in this lab',answer:'Here is the right mix',
      done:'Experiments complete',over:'Out of hearts',stCoins:'coins',stWords:'words built',stFirst:'first try',praise:w=>`You built ${w} from its parts. Now you can read words like it.`},
  uz:{title:'So\'z laboratoriyasi',lede:'So\'zlar ma\'no beradigan qismlardan tuziladi. Har bir ma\'noga mos so\'z hosil qilish uchun to\'g\'ri old qo\'shimcha, o\'zak va qo\'shimchani aralashtiring.',
      rules:['Qismlarni kolbalarga tartib bilan quyish uchun <b>bosing</b>. Kolbani bo\'shatish uchun uni bosing.','So\'zni sinash uchun <b>aralashtiring</b>. Noto\'g\'ri aralashma bitta yurakni oladi; har bir so\'zga ikki urinish.','Har bir so\'zdan keyin laboratoriya har bir qism ma\'nosini ko\'rsatadi.'],
      start:'Laboratoriyani ochish',build:'Shu ma\'nodagi so\'zni yasang',empty:'Bo\'shatish',mix:'Aralashtirish',fill:n=>`Yana ${n} ta qo\'shing`,next:'Keyingi so\'z',finish:'Natijalar',
      types:{pre:'old qo\'shimcha',root:'o\'zak',suf:'qo\'shimcha'},ok:c=>`Ishladi · +${c}`,no:'Bunday so\'z yo\'q',answer:'To\'g\'ri aralashma',
      done:'Tajribalar tugadi',over:'Yuraklar tugadi',stCoins:'tanga',stWords:'yasalgan so\'zlar',stFirst:'birinchi urinish',praise:w=>`${w} so\'zini qismlaridan yasadingiz. Endi shunga o\'xshash so\'zlarni ham tushunasiz.`}
};

let G=null, T=null;
function newRound(preview){
  const lab=K.block('parts',LAB), words=K.shuffle([...lab.words]).slice(0,ROUND);
  G={lab,words,i:-1,lives:LIVES,coins:0,built:0,first:0,res:{},preview:!!preview,over:false,W:null};
  K.hearts($('lives'),LIVES,LIVES); $('coinTxt').textContent=0; nextWord();
}
function nextWord(){
  G.i++;
  if(G.i>=G.words.length) return finish(true);
  const item=G.words[G.i], parts=G.lab.parts;
  // shelf: the right parts plus look-alike distractors of the same kinds
  const need=item.p, types=need.map(p=>parts[p][0]);
  const others=K.shuffle(Object.keys(parts).filter(p=>!need.includes(p)));
  const extra=[]; for(const t of ['pre','root','suf']){ const n=types.includes(t)?2:1; extra.push(...others.filter(p=>parts[p][0]===t).slice(0,n)) }
  const shelf=K.shuffle([...need,...extra.slice(0,Math.max(3,6-need.length))]);
  G.W={item,shelf,slots:Array(need.length).fill(null),tries:0,state:'build'};
  $('progChip').textContent=`${G.i+1}/${G.words.length}`;
  $('def').textContent=item.d; $('badge').hidden=true; $('prompt').classList.remove('ok');
  $('result').textContent=''; $('result').className='result'; $('break').innerHTML='';
  render();
}
function render(){
  const W=G.W, parts=G.lab.parts;
  $('slots').innerHTML=W.slots.map((p,i)=>{ const t=p?parts[p][0]:''; return (i?'<span class="plus">+</span>':'')+`<button class="flask ${p?'full t-'+t:''}" data-i="${i}"><span class="type">${p?esc(T.types[t]):''}</span><span class="glass"></span><span class="liq"></span><span class="tag">${p?esc(p):''}</span></button>` }).join('');
  $('shelf').innerHTML=W.shelf.map(p=>`<button class="part t-${parts[p][0]}${W.slots.includes(p)?' used':''}" data-p="${p}">${esc(p)}<small>${esc(T.types[parts[p][0]])}</small></button>`).join('');
  const b=$('mixBtn'), left=W.slots.filter(x=>!x).length;
  if(W.state==='build'){ b.disabled=left>0; b.textContent=left?T.fill(left):T.mix } else { b.disabled=false; b.textContent=G.i>=G.words.length-1?T.finish:T.next }
  $('clearBtn').disabled=W.state!=='build';
}
$('shelf').addEventListener('click',e=>{
  const b=e.target.closest('.part'); if(!b||!G||G.preview||G.W.state!=='build') return;
  const W=G.W, i=W.slots.findIndex(x=>!x); if(i<0) return;
  W.slots[i]=b.dataset.p; render(); const f=$('slots').querySelectorAll('.flask')[i]; f.classList.add('bubble');
  tone(300+i*120,.12,{type:'sine',v:.07,to:600+i*120}); noise(.15,{v:.06,f:2500,q:3});
});
$('slots').addEventListener('click',e=>{
  const f=e.target.closest('.flask'); if(!f||!G||G.W.state!=='build') return;
  const W=G.W, i=+f.dataset.i; if(!W.slots[i]) return;
  W.slots[i]=null; const rest=W.slots.filter(Boolean); W.slots=W.slots.map((_,j)=>rest[j]||null); render(); SFX.tap();
});
$('clearBtn').addEventListener('click',()=>{ const W=G.W; if(!W||W.state!=='build') return; W.slots=W.slots.map(()=>null); render() });
$('mixBtn').addEventListener('click',()=>{
  const W=G.W; if(!W) return;
  if(W.state!=='build') return nextWord();
  if(W.slots.some(x=>!x)) return;
  W.tries++;
  const made=W.slots.join(''), ok=W.slots.every((p,i)=>p===W.item.p[i]);
  if(W.tries===1&&G.res[W.item.w]===undefined) G.res[W.item.w]=ok;
  if(ok) return success();
  G.lives--; K.hearts($('lives'),G.lives,LIVES);
  const r=$('result'); r.textContent=made; r.className='result no'; SFX.wrong(); K.badge($('badge'),T.no,false,1500);
  if(G.lives<=0){ G.over=true; reveal(); return setTimeout(()=>finish(false),2000) }
  if(W.tries>=TRIES){ reveal(); return }
  setTimeout(()=>{ W.slots=W.slots.map(()=>null); r.textContent=''; r.className='result'; render() },900);
});
function success(){
  const W=G.W; W.state='solved';
  const c=PAY[W.tries-1]*TIER; G.coins+=c; G.built++; if(W.tries===1) G.first++; $('coinTxt').textContent=G.coins;
  const r=$('result'); r.textContent=W.item.w; r.className='result ok'; $('prompt').classList.add('ok');
  showBreakdown(); render(); [...$('slots').querySelectorAll('.flask')].forEach(f=>f.classList.add('bubble'));
  SFX.right(G.built); setTimeout(()=>SFX.coin(),160); K.badge($('badge'),T.ok(c),true,1300);
  if(W.item.p.length>=3&&W.tries===1) K.doni(T.praise(W.item.w));
}
function reveal(){
  const W=G.W; W.state='failed'; W.slots=[...W.item.p];
  const r=$('result'); r.textContent=W.item.w; r.className='result'; showBreakdown(); render(); K.badge($('badge'),T.answer,false,1800);
}
function showBreakdown(){ const parts=G.lab.parts; $('break').innerHTML=G.W.item.p.map(p=>`<span><b>${esc(p)}</b> = ${esc(parts[p][1])}</span>`).join('') }
function finish(done){
  G.over=true; done?SFX.win():SFX.end();
  const results=Object.entries(G.res).map(([w,ok])=>({wid:w,ok,evidence:ok?'medium':'none'}));
  K.end({title:done?T.done:T.over,stats:[{v:G.coins,l:T.stCoins},{v:`${G.built}/${G.words.length}`,l:T.stWords},{v:G.first,l:T.stFirst}],
    results,payload:{game:'word-lab',tier:TIER,coins:G.coins}});
}
K.setup({text,onText:t=>{ T=t; if(G&&G.W) render() },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

