story.js:
/* ═════════ Silly Story (drag into text) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone} = K;
const TIER = 2;              // hidden tier: Connect (chosen in context)
const PAY = [2,1];           // coins per blank by check (1st, 2nd), times TIER
const CHECKS = 2;

/* Content: stories with blanks written as [word]. `extra` words go in the bank but fit nowhere. Titles are in English, the story's language. */
const STORIES = {
  a2:[
    {t:'A Rainy Saturday',s:'On Saturday the [weather] was terrible. I forgot my [umbrella], so I got very wet. I went to the [library] to read, but it was not [quiet] because a baby was crying. After two hours I was [tired], so I went home and made soup in the [kitchen].',extra:['expensive','journey']},
    {t:'My Neighbour\'s Dog',s:'My [neighbour] has a big, friendly dog called Max. Max is never [angry]; he just wants to play. One day I wanted to [borrow] a ladder, so I knocked on the door. Max jumped on me and ate my [breakfast] sandwich! The road outside is [dangerous], so we always walk him in the park. Next time I must [remember] to hide my food!',extra:['cheap','busy']}],
  c1:[
    {t:'The Birthday Magician',s:'Max planned a [lavish] party, with a chocolate fountain and three bands. His friends were [skeptical] that a real magician would come. When the magician arrived, his act was [erratic]: one trick was brilliant, the next a disaster. After the rabbit escaped, chaos was [inevitable]. Max\'s dad stepped in to [admonish] the magician, but the magician gave such an [eloquent] apology that everyone clapped.',extra:['ephemeral','secluded']},
    {t:'Aunt Lola\'s Cabin',s:'Aunt Lola moved to a [secluded] cabin at the end of a forest road. Phones may be [ubiquitous] in the city, but out there nobody had one. Her love of silence was far from [ephemeral]: it lasted thirty years. She became [adept] at fixing everything herself, from roofs to radios. Her nephew tried to [coerce] her into buying a phone, but she simply laughed and said it would be [detrimental] to her peace.',extra:['lavish','colloquial']}]
};

const text = {
  en:{title:'Silly Story',lede:'A story is missing its best words. Fill every gap from the word bank, then read it back. Wrong words make very silly stories.',
      rules:['<b>Tap a gap</b>, then tap a word. Or tap a word first. Tap a filled gap to take its word back.','<b>Read the story</b> when every gap is full. Right words lock in; wrong ones come back to the bank.','Two readings per story. Two words in the bank fit nowhere.'],
      start:'Open the book',instr:(n,m)=>`Story ${n} of ${m} · fill every gap`,read:'Read my story',fill:n=>`${n} ${n===1?'gap':'gaps'} left`,next:'Next story',finish:'See results',
      silly:(sent)=>`That makes: <b>“${sent}”</b> Silly!`,right:c=>`What a story · +${c}`,someWrong:n=>`${n} ${n===1?'word doesn\'t':'words don\'t'} fit yet`,answer:'Here is the real story',
      done:'The end',stCoins:'coins',stWords:'words in place',stFirst:'first reading',praise:'Every word right on the first reading.'},
  uz:{title:'Kulgili hikoya',lede:'Hikoyadan eng yaxshi so\'zlar tushib qolgan. Har bir bo\'shliqni so\'zlar bankidan to\'ldiring, keyin o\'qing. Noto\'g\'ri so\'zlar juda kulgili hikoya chiqaradi.',
      rules:['<b>Bo\'shliqni bosing</b>, so\'ng so\'zni bosing. Yoki avval so\'zni bosing. To\'ldirilgan bo\'shliqni bossangiz, so\'z qaytadi.','Hamma bo\'shliq to\'lganda <b>hikoyani o\'qing</b>. To\'g\'ri so\'zlar qotadi, noto\'g\'rilari bankka qaytadi.','Har bir hikoyaga ikki marta o\'qish. Bankdagi ikki so\'z hech qayerga mos emas.'],
      start:'Kitobni ochish',instr:(n,m)=>`${m} tadan ${n}-hikoya · hamma bo\'shliqni to\'ldiring`,read:'Hikoyani o\'qish',fill:n=>`${n} ta bo\'shliq qoldi`,next:'Keyingi hikoya',finish:'Natijalar',
      silly:(sent)=>`Bu shunday bo'ldi: <b>“${sent}”</b> Kulgili!`,right:c=>`Zo'r hikoya · +${c}`,someWrong:n=>`${n} ta so'z hali mos emas`,answer:'Haqiqiy hikoya',
      done:'Tamom',stCoins:'tanga',stWords:'joyidagi so\'zlar',stFirst:'birinchi o\'qishda',praise:'Birinchi o\'qishdayoq hamma so\'z to\'g\'ri.'}
};
const LAUGH='<svg viewBox="0 0 60 60" aria-hidden="true"><g transform="translate(30 32)"><circle r="17" fill="#fff" stroke="#EADFCB" stroke-width="1.5"/><path d="M-9-3q3-3 6 0M3-3q3-3 6 0" stroke="#1C1C1E" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M-7 4q7 9 14 0z" fill="#1C1C1E"/><ellipse cx="-11" cy="4" rx="3" ry="2" fill="#FF9EC0"/><ellipse cx="11" cy="4" rx="3" ry="2" fill="#FF9EC0"/><path d="M0-17q2-6 0-9" stroke="#2FA35A" stroke-width="2.4" fill="none" stroke-linecap="round"/></g></svg>';

let G=null, T=null;
function parse(st){
  const segs=[]; let k=0;
  st.s.split(/(\[[^\]]+\])/).forEach(part=>{ const m=part.match(/^\[(.+)\]$/); if(m) segs.push({gap:k++,w:m[1]}); else if(part) segs.push({text:part}) });
  return segs;
}
function newRound(preview){
  const stories=K.shuffle([...K.block('stories',STORIES)]);
  G={stories,si:-1,coins:0,placed:0,total:0,first:0,res:{},preview:!!preview,S:null};
  $('coinTxt').textContent=0; nextStory();
}
function nextStory(){
  G.si++;
  if(G.si>=G.stories.length) return finish();
  const st=G.stories[G.si], segs=parse(st), gaps=segs.filter(s=>s.gap!==undefined);
  const bank=K.shuffle([...gaps.map(g=>g.w),...st.extra]);
  G.S={st,segs,gaps,bank,fill:Array(gaps.length).fill(null),locked:new Set(),sel:null,selWord:null,checks:0,state:'build',coins:0};
  G.total+=gaps.length;
  $('progChip').textContent=`${G.si+1}/${G.stories.length}`; $('instr').textContent=T.instr(G.si+1,G.stories.length);
  $('btitle').textContent=st.t; $('silly').hidden=true; $('badge').hidden=true;
  render();
}
function render(){
  const S=G.S;
  $('btext').innerHTML=S.segs.map(s=>{
    if(s.text) return esc(s.text);
    const v=S.fill[s.gap], cls=['blank']; if(v) cls.push('filled'); if(S.locked.has(s.gap)) cls.push('ok'); if(S.state==='failed'&&!S.locked.has(s.gap)) cls.push('answer'); if(S.sel===s.gap) cls.push('sel');
    return `<button class="${cls.join(' ')}" data-g="${s.gap}">${v?esc(v):'&nbsp;'}</button>`;
  }).join('');
  const usedCount={}; S.fill.forEach(v=>{ if(v) usedCount[v]=(usedCount[v]||0)+1 });
  $('bank').innerHTML=S.bank.map((w,k)=>{ const used=(usedCount[w]||0)>0 && (usedCount[w]--,true); return `<button class="wcard${used?' used':''}${S.selWord===k?' sel':''}" data-k="${k}">${esc(w)}</button>` }).join('');
  $('checks').innerHTML=[...Array(CHECKS)].map((_,i)=>`<i class="${i<S.checks?'used':''}"></i>`).join('');
  const b=$('readBtn'), left=S.fill.filter(v=>!v).length;
  if(S.state==='build'){ b.disabled=left>0; b.textContent=left?T.fill(left):T.read } else { b.disabled=false; b.textContent=G.si>=G.stories.length-1?T.finish:T.next }
}
function place(g,word){ const S=G.S; S.fill[g]=word; S.sel=null; S.selWord=null; SFX.tap(); tone(560,.06,{type:'triangle',v:.05}); render() }
$('btext').addEventListener('click',e=>{
  const b=e.target.closest('.blank'); if(!b||!G||G.preview||G.S.state!=='build') return;
  const S=G.S, g=+b.dataset.g; if(S.locked.has(g)) return;
  if(S.fill[g]){ S.fill[g]=null; S.sel=g; render(); return }           // take the word back and keep the gap selected
  if(S.selWord!==null) return place(g,S.bank[S.selWord]);
  S.sel = S.sel===g ? null : g; render();
});
$('bank').addEventListener('click',e=>{
  const c=e.target.closest('.wcard'); if(!c||!G||G.preview||G.S.state!=='build') return;
  const S=G.S, k=+c.dataset.k, w=S.bank[k];
  let g=S.sel; if(g===null&&S.selWord===null){ g=S.fill.findIndex((v,i)=>!v&&!S.locked.has(i)); if(g<0) g=null }
  if(g!==null) return place(g,w);
  S.selWord = S.selWord===k ? null : k; render();
});
$('readBtn').addEventListener('click',()=>{
  const S=G.S; if(!S) return;
  if(S.state!=='build') return nextStory();
  if(S.fill.some(v=>!v)) return;
  S.checks++;
  const wrong=[];
  S.gaps.forEach(gp=>{ const ok=S.fill[gp.gap]===gp.w; if(S.checks===1&&G.res[gp.w]===undefined) G.res[gp.w]=ok; if(ok){ if(!S.locked.has(gp.gap)){ S.locked.add(gp.gap); G.placed++; G.coins+=PAY[S.checks-1]*TIER; S.coins+=PAY[S.checks-1]*TIER; if(S.checks===1) G.first++ } } else wrong.push(gp) });
  $('coinTxt').textContent=G.coins;
  if(!wrong.length){
    S.state='solved'; render(); SFX.right(6); setTimeout(()=>SFX.coin(),160);
    K.badge($('badge'),T.right(S.coins),true,1500); $('silly').hidden=true;
    [...$('btext').querySelectorAll('.blank')].forEach((b,i)=>setTimeout(()=>tone(523*Math.pow(1.08,i),.08,{type:'triangle',v:.06}),i*80));
    return;
  }
  // show the silliest result: the sentence that holds the first wrong word
  const g=wrong[0]; const sent=sentenceWith(g.gap,S.fill[g.gap]);
  $('silly').innerHTML=LAUGH+`<span>${T.silly(esc(sent))}</span>`; $('silly').hidden=false;
  SFX.wrong(); setTimeout(()=>{ [0,1,2].forEach(i=>tone(660-i*60,.08,{type:'square',v:.03,at:i*.09})) },200);
  K.badge($('badge'),T.someWrong(wrong.length),false,1700);
  render(); wrong.forEach(gp=>{ const el=$('btext').querySelector(`[data-g="${gp.gap}"]`); el&&el.classList.add('wrong') });
  setTimeout(()=>{
    if(S.checks>=CHECKS){ S.state='failed'; wrong.forEach(gp=>S.fill[gp.gap]=gp.w); K.badge($('badge'),T.answer,false,1800) }
    else wrong.forEach(gp=>S.fill[gp.gap]=null);
    render();
  },1300);
});
function sentenceWith(gap,word){
  const S=G.S; let full=''; let pos=-1;
  S.segs.forEach(s=>{ if(s.text) full+=s.text; else { if(s.gap===gap) pos=full.length; full+= s.gap===gap?word:(S.fill[s.gap]||'___') } });
  const sents=full.match(/[^.!?]+[.!?]+/g)||[full]; let acc=0;
  for(const x of sents){ if(pos>=acc&&pos<acc+x.length) return x.trim(); acc+=x.length }
  return full;
}
function finish(){
  if(G.first===G.total) K.doni(T.praise);
  SFX.win();
  const results=Object.entries(G.res).map(([w,ok])=>({wid:w,ok,evidence:ok?'medium':'none'}));
  K.end({title:T.done,stats:[{v:G.coins,l:T.stCoins},{v:`${G.placed}/${G.total}`,l:T.stWords},{v:G.first,l:T.stFirst}],
    results,payload:{game:'silly-story',tier:TIER,coins:G.coins}});
}
K.setup({text,onText:t=>{ T=t; if(G&&G.S) render() },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

