ghost.js:
/* ═════════ Ghost Race ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone} = K;
const TIER = 3;              // hidden tier: Recall (typed)
const COIN = 2;              // per word typed right first time, times TIER
const RECORD_BONUS = 5;      // times TIER, only for a run with every word right
const WORDS = 6;
const DEFAULT_PACE = {a2:6, c1:8};   // seconds per word for Doni's ghost before you have a record

const text = {
  en:{title:'Ghost Race',lede:'Type six words from their meanings as fast as you can. Your ghost is your own best run. Beat it.',
      rules:['<b>Read the meaning</b> and type the word. A wrong word just costs you time.','<b>A record only counts</b> when all six words are right. "I don\'t know" shows the word but ends your record attempt.','Your first answer to each word is what counts for learning.'],
      start:'Ready, set…',you:'You',typeWord:'Type the word that means',go:'Go',type:'Type the word',ghostDoni:'Doni',ghostYou:'Best',
      best:'Your best',none:'No record yet. Race Doni first.',notQuite:'Not quite',close:w=>`Close · it's spelled ${w}`,was:w=>`The word was: ${w}`,
      noRecord:'This run can\'t set a record now',newRecord:'New record!',beatGhost:'You beat the ghost',lostGhost:'The ghost was faster',
      stTime:'time',stRight:'right first time',stCoins:'coins',secs:s=>`${s.toFixed(1)}s`,praise:'Six for six, and a new record.'},
  uz:{title:'Arvoh poygasi',lede:'Ma\'nosiga qarab oltita so\'zni iloji boricha tez yozing. Arvohingiz o\'zingizning eng yaxshi natijangiz. Uni yuting.',
      rules:['<b>Ma\'noni o\'qing</b> va so\'zni yozing. Noto\'g\'ri so\'z faqat vaqtingizni oladi.','<b>Rekord</b> faqat oltita so\'zning hammasi to\'g\'ri bo\'lsa hisoblanadi. "Bilmayman" so\'zni ko\'rsatadi, lekin rekord urinishini tugatadi.','O\'rganish uchun har bir so\'zga birinchi javobingiz hisoblanadi.'],
      start:'Tayyor…',you:'Siz',typeWord:'Shu ma\'nodagi so\'zni yozing',go:'Kirit',type:'So\'zni yozing',ghostDoni:'Doni',ghostYou:'Rekord',
      best:'Eng yaxshi natijangiz',none:'Hali rekord yo\'q. Avval Doni bilan poyga qiling.',notQuite:'Hali emas',close:w=>`Deyarli · to'g'ri yozilishi: ${w}`,was:w=>`So'z: ${w}`,
      noRecord:'Bu poyga endi rekord bo\'la olmaydi',newRecord:'Yangi rekord!',beatGhost:'Arvohni yutdingiz',lostGhost:'Arvoh tezroq edi',
      stTime:'vaqt',stRight:'birinchi urinishda',stCoins:'tanga',secs:s=>`${s.toFixed(1)} s`,praise:'Oltidan olti, yangi rekord bilan.'}
};

// best runs are a per-viewer convenience kept in this browser
function loadBest(){ try{ return JSON.parse(localStorage.getItem('ghost-best-'+K.level+K.hwId)||'null') }catch(e){ return null } }
function saveBest(b){ try{ localStorage.setItem('ghost-best-'+K.level+K.hwId,JSON.stringify(b)) }catch(e){} }

let G=null, T=null, raf=0;
function ghostSplits(){ const b=loadBest(); if(b&&b.splits&&b.splits.length===WORDS) return {splits:b.splits,mine:true}; const p=DEFAULT_PACE[K.level]||7; return {splits:[...Array(WORDS)].map((_,i)=>p*(i+1)),mine:false} }
function newRound(preview){
  cancelAnimationFrame(raf);
  const eng=K.engine(K.words), words=[]; for(let i=0;i<WORDS;i++) words.push(eng.next(2+(i>2?1:0),words.map(w=>w.id)));
  const gh=ghostSplits();
  G={eng,words,i:0,t:0,running:false,splits:[],firstTry:true,right:0,valid:true,coins:0,ghost:gh,preview:!!preview,over:false};
  $('ghostName').textContent=gh.mine?T.ghostYou:T.ghostDoni; $('coinTxt').textContent=0;
  $('splits').innerHTML=''; $('timeChip').textContent=T.secs(0); $('progChip').textContent=`0/${WORDS}`;
  $('inp').value=''; $('inp').placeholder=T.type; $('goBtn').textContent=T.go; $('note').textContent='';
  show(0); place();
  const b=loadBest(); $('bestBox').innerHTML = b ? `<span>${esc(T.best)}</span><b>${T.secs(b.time)}</b>` : `<span>${esc(T.none)}</span>`;
  if(!preview) countdown();
}
function show(i){ const w=G.words[i]; $('def').textContent=w.d; $('prompt').classList.remove('ok'); $('badge').hidden=true; G.firstTry=true }
function countdown(){
  const c=$('count'); let n=3; $('inp').disabled=true;
  const step=()=>{ if(n>0){ c.textContent=n; tone(440,.12,{type:'triangle',v:.08}); n--; setTimeout(step,650) } else { c.textContent=''; tone(880,.2,{type:'triangle',v:.1}); go() } };
  step();
}
function go(){ G.running=true; $('inp').disabled=false; $('inp').focus(); let last=performance.now(); const loop=now=>{ if(!G||G.over) return; if(G.running&&!document.hidden){ G.t+=(now-last)/1000 } last=now; $('timeChip').textContent=T.secs(G.t); place(); raf=requestAnimationFrame(loop) }; raf=requestAnimationFrame(loop) }
function place(){
  const pct=x=>`calc(${Math.min(1,x)*100}% - ${Math.min(1,x)*28}px + 4px)`;
  $('me').style.left=pct(G.i/WORDS);
  const s=G.ghost.splits; let k=s.findIndex(v=>v>G.t); if(k<0) k=WORDS; const prev=k?s[k-1]:0, next=s[Math.min(k,WORDS-1)];
  const frac = k>=WORDS ? 1 : (k + (G.t-prev)/Math.max(.1,next-prev))/WORDS;
  $('ghost').style.left=pct(frac);
}
$('typer').addEventListener('submit',e=>{
  e.preventDefault(); if(!G||!G.running||G.over) return;
  const w=G.words[G.i], v=$('inp').value; if(!K.norm(v)) return;
  const r=K.judge(v,w);
  if(!r){
    if(G.firstTry){ G.eng.submit(w.id,false); G.firstTry=false; G.valid=false }
    const t=$('typer'); t.classList.remove('shake'); void t.offsetWidth; t.classList.add('shake'); SFX.wrong(); K.badge($('badge'),T.notQuite,false,1100);
    $('inp').select(); return;
  }
  if(G.firstTry){ G.eng.submit(w.id,true,r==='exact'?'strong':'medium'); G.right++; const c=COIN*TIER; G.coins+=c; $('coinTxt').textContent=G.coins }
  done(w, r==='close' ? T.close(w.w) : null, true);
});
$('idkBtn').addEventListener('click',()=>{
  if(!G||!G.running||G.over) return; const w=G.words[G.i];
  if(G.firstTry) G.eng.submit(w.id,false); G.valid=false;
  K.badge($('badge'),T.was(w.w),false,1500); $('note').textContent=T.noRecord; done(w,null,false);
});
$('idkBtn').addEventListener('pointerdown',e=>{ if(document.activeElement===$('inp')) e.preventDefault() });
function done(w,msg,ok){
  G.splits.push(G.t);
  const ahead = G.ghost.splits[G.i]!==undefined && G.t<G.ghost.splits[G.i];
  const sp=document.createElement('span'); sp.className=(ok&&G.firstTry?'ok':'miss')+(ahead?' ahead':''); sp.textContent=`${w.w} ${T.secs(G.t)}`; $('splits').appendChild(sp);
  if(ok){ $('prompt').classList.add('ok'); SFX.right(G.i); if(msg) K.badge($('badge'),msg,true,1200) }
  if(!G.valid && !$('note').textContent) $('note').textContent=T.noRecord;
  G.i++; $('inp').value=''; $('progChip').textContent=`${G.i}/${WORDS}`; place();
  if(G.i>=WORDS) return finish();
  setTimeout(()=>{ if(!G.over) show(G.i) },ok?260:900);
}
function finish(){
  G.over=true; G.running=false; cancelAnimationFrame(raf); $('inp').blur();
  const best=loadBest(), allRight=G.right===WORDS&&G.valid;
  const record = allRight && (!best || G.t<best.time);
  const beat = G.t < G.ghost.splits[WORDS-1];
  if(record){ saveBest({time:G.t,splits:G.splits}); G.coins+=RECORD_BONUS*TIER; K.doni(T.praise); SFX.win() } else if(beat&&allRight) SFX.win(); else SFX.end();
  $('coinTxt').textContent=G.coins;
  K.end({title:record?T.newRecord:beat&&allRight?T.beatGhost:T.lostGhost,
    stats:[{v:T.secs(G.t),l:T.stTime},{v:`${G.right}/${WORDS}`,l:T.stRight},{v:G.coins,l:T.stCoins}],
    results:G.eng.results(),payload:{game:'ghost-race',tier:TIER,coins:G.coins,time:+G.t.toFixed(2),valid:allRight}});
}
K.setup({text,onText:t=>{ T=t },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

