/* ═════════ Balloon Rescue (letter guessing with a definition) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 3;              // hidden tier: Recall with support; evidence is only medium (common letters give a lot away)
const ROUND = 8, BALLOONS = 6;
const COLS = ['#D92F7A','#2E46E8','#0B8F84','#6A3DF0','#F5B700','#FFFFFF'];
const POS = [[0,18],[30,0],[62,6],[94,20],[16,38],[76,40]];

const text = {
  en:{title:'Balloon Rescue',lede:'Doni\'s balloon is drifting. Guess the word letter by letter from its meaning. Every wrong letter pops a balloon.',
      rules:['<b>Tap letters</b> (or type them) to fill in the word.','<b>A wrong letter</b> pops one of six balloons. Lose them all and the basket lands.','Fewer popped balloons earn more coins. The word rises you higher.'],
      start:'Take off',guess:'Guess the word that means',left:n=>`${n} ${n===1?'balloon':'balloons'} left`,
      saved:c=>`Saved · +${c}`,landed:w=>`Landed · the word was ${w}`,done:'Safe flight',stCoins:'coins',stWords:'words found',stAlt:'height',
      praise:'Not a single balloon popped.'},
  uz:{title:'Havo shari',lede:'Donining havo shari uchib ketyapti. Ma\'nosiga qarab so\'zni harfma-harf toping. Har bir noto\'g\'ri harf bitta sharni yoradi.',
      rules:['So\'zni to\'ldirish uchun <b>harflarni bosing</b> (yoki yozing).','<b>Noto\'g\'ri harf</b> oltita shardan birini yoradi. Hammasi yorilsa, savat yerga tushadi.','Kamroq yorilgan shar ko\'proq tanga beradi. So\'z sizni yuqoriga ko\'taradi.'],
      start:'Uchish',guess:'Shu ma\'nodagi so\'zni toping',left:n=>`${n} ta shar qoldi`,
      saved:c=>`Qutqarildi · +${c}`,landed:w=>`Yerga tushdi · so'z: ${w}`,done:'Xavfsiz parvoz',stCoins:'tanga',stWords:'topilgan so\'zlar',stAlt:'balandlik',
      praise:'Birorta ham shar yorilmadi.'}
};
const ROWS=['qwertyuiop','asdfghjkl','zxcvbnm'];

let G=null, T=null;
function newRound(preview){
  const eng=K.engine(K.words.filter(w=>/^[a-z]+$/i.test(w.w)));
  G={eng,n:0,alt:0,coins:0,found:0,clean:0,preview:!!preview,W:null};
  $('coinTxt').textContent=0; $('altChip').textContent='0 m'; setAlt(); nextWord();
}
function setAlt(fall){ const c=$('craft'); c.classList.toggle('fall',!!fall); c.style.setProperty('--alt',(18+Math.min(G.alt,7)*6.5)+'%') }
function nextWord(){
  if(G.n>=ROUND) return finish();
  G.n++; $('progChip').textContent=`${G.n}/${ROUND}`;
  const w=G.eng.next(1+Math.floor(G.n/3));
  G.W={w,letters:[...w.w.toLowerCase()],guessed:new Set(),left:BALLOONS,state:'play'};
  $('def').textContent=w.d; $('prompt').classList.remove('ok'); $('badge').hidden=true;
  $('bunch').innerHTML=POS.map((p,i)=>`<i class="bal" style="left:${p[0]}px;top:${p[1]}px;background:${COLS[i]};border-top-color:${COLS[i]}"></i>`).join('');
  $('keys').innerHTML=ROWS.map(r=>`<div class="krow">${[...r].map(ch=>`<button class="key" data-k="${ch}">${ch}</button>`).join('')}</div>`).join('');
  renderSlots(); $('note').textContent=T.left(BALLOONS);
}
function renderSlots(){ const W=G.W; $('slots').innerHTML=W.letters.map(ch=>`<span class="slot ${W.guessed.has(ch)?'got':''}">${W.guessed.has(ch)?ch:''}</span>`).join('') }
function guess(ch){
  const W=G.W; if(!W||W.state!=='play'||G.preview||W.guessed.has(ch)) return;
  W.guessed.add(ch);
  const key=$('keys').querySelector(`[data-k="${ch}"]`);
  if(W.letters.includes(ch)){
    key&&key.classList.add('hit'); key&&(key.disabled=true); renderSlots(); tone(660+W.guessed.size*20,.07,{type:'triangle',v:.07});
    if(W.letters.every(c=>W.guessed.has(c))) return win();
  } else {
    key&&key.classList.add('miss'); key&&(key.disabled=true);
    W.left--; const b=$('bunch').children[BALLOONS-1-W.left]; b&&b.classList.add('pop');
    noise(.12,{v:.5,f:2500,q:1}); tone(200,.15,{v:.08,to:90});
    $('note').textContent=T.left(W.left);
    if(W.left<=0) return lose();
  }
}
$('keys').addEventListener('click',e=>{ const k=e.target.closest('.key'); if(k) guess(k.dataset.k) });
addEventListener('keydown',e=>{ if(!$('startOv').hidden||!$('endOv').hidden) return; const ch=e.key.toLowerCase(); if(/^[a-z]$/.test(ch)) guess(ch) });
function win(){
  const W=G.W; W.state='won'; const popped=BALLOONS-W.left;
  G.eng.submit(W.w.id,true,'medium'); G.found++; if(!popped) G.clean++;
  const c=Math.max(1,3-Math.floor(popped/2))*TIER; G.coins+=c; G.alt+=1; $('coinTxt').textContent=G.coins; $('altChip').textContent=`${G.alt*100} m`;
  $('slots').querySelectorAll('.slot').forEach(s=>s.classList.add('win')); $('prompt').classList.add('ok');
  setAlt(); SFX.right(G.found); setTimeout(()=>SFX.coin(),160); K.badge($('badge'),T.saved(c),true,1300);
  if(!popped&&W.w.diff>=2) K.doni(T.praise);
  setTimeout(nextWord,1500);
}
function lose(){
  const W=G.W; W.state='lost'; G.eng.submit(W.w.id,false);
  $('slots').innerHTML=W.letters.map(ch=>`<span class="slot ${W.guessed.has(ch)?'got':'shown'}">${ch}</span>`).join('');
  G.alt=Math.max(0,G.alt-1); setAlt(true); $('altChip').textContent=`${G.alt*100} m`;
  SFX.wrong(); K.badge($('badge'),T.landed(W.w.w),false,2000);
  $('keys').querySelectorAll('.key').forEach(k=>k.disabled=true);
  setTimeout(nextWord,2200);
}
$('idkBtn').addEventListener('click',()=>{ if(!G||G.preview||!G.W||G.W.state!=='play') return; G.W.left=0; $('bunch').querySelectorAll('.bal').forEach(b=>b.classList.add('pop')); lose() });
function finish(){
  SFX.win();
  K.end({title:T.done,stats:[{v:G.coins,l:T.stCoins},{v:`${G.found}/${ROUND}`,l:T.stWords},{v:`${G.alt*100} m`,l:T.stAlt}],
    results:G.eng.results(),payload:{game:'balloon-rescue',tier:TIER,coins:G.coins}});
}
K.setup({text,onText:t=>{ T=t },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

