scramble.js:
/* ═════════ Letter Tiles (scramble / anagram) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone} = K;
const TIER = 3;              // hidden tier: bridge to typing; evidence is medium (the letters are given)
const PAY = [3,2,1];         // coins by attempt, times TIER; a hint drops one level
const ROUND = 10, TRIES = 3;
const PTS = {a:1,e:1,i:1,o:1,u:1,l:1,n:1,s:1,t:1,r:1,d:2,g:2,b:3,c:3,m:3,p:3,f:4,h:4,v:4,w:4,y:4,k:5,j:8,x:8,q:10,z:10};

const text = {
  en:{title:'Letter Tiles',lede:'The letters of a word have been shuffled. Read the meaning and put the tiles back in order.',
      rules:['<b>Tap tiles</b> to place them; tap a placed tile to send it back.','The word is checked as soon as every tile is placed. <b>3 tries</b> per word.','<b>Hint</b> fixes the first letter, for fewer coins. After each word you see it in a sentence.'],
      start:'Open the board',unscramble:'Put the letters in order · the word means',hint:'Hint',shuffle:'Shuffle',next:'Next word',finish:'See results',
      tries:n=>`${n} ${n===1?'try':'tries'} left`,ok:c=>`Correct · +${c}`,notQuite:'Not quite',was:w=>`The word was: ${w}`,streak:n=>`×${n}`,
      done:'Board cleared',stCoins:'coins',stWords:'words rebuilt',stFirst:'first try',praise:n=>`${n} words in a row on the first try.`},
  uz:{title:'Harf toshlari',lede:'So\'z harflari aralashib ketgan. Ma\'nosini o\'qing va toshlarni o\'z joyiga qo\'ying.',
      rules:['Joylash uchun <b>toshlarni bosing</b>; joylangan toshni bossangiz, qaytadi.','Hamma tosh joylanishi bilan so\'z tekshiriladi. Har bir so\'zga <b>3 urinish</b>.','<b>Yordam</b> birinchi harfni qo\'yib beradi, kamroq tanga uchun. Har bir so\'zdan keyin uni gapda ko\'rasiz.'],
      start:'Boshlash',unscramble:'Harflarni tartiblang · so\'z ma\'nosi',hint:'Yordam',shuffle:'Aralashtirish',next:'Keyingi so\'z',finish:'Natijalar',
      tries:n=>`${n} ta urinish qoldi`,ok:c=>`To'g'ri · +${c}`,notQuite:'Hali emas',was:w=>`So'z: ${w}`,streak:n=>`×${n}`,
      done:'Taxta tozalandi',stCoins:'tanga',stWords:'tiklangan so\'zlar',stFirst:'birinchi urinishda',praise:n=>`Ketma-ket ${n} ta so\'z birinchi urinishda.`}
};

let G=null, T=null;
function newRound(preview){
  const eng=K.engine(K.words.filter(w=>/^[a-z]+$/i.test(w.w)&&w.w.length>=4));
  G={eng,n:0,coins:0,built:0,first:0,streak:0,preview:!!preview,W:null};
  $('coinTxt').textContent=0; $('streakChip').textContent=''; nextWord();
}
function scramble(word){
  const L=[...word]; let s; let guard=0;
  do{ s=K.shuffle([...L]); guard++ } while(s.join('')===word && guard<20);
  return s;
}
function nextWord(){
  if(G.n>=ROUND) return finish();
  G.n++; $('progChip').textContent=`${G.n}/${ROUND}`;
  const w=G.eng.next(1+Math.floor(G.n/4)), word=w.w.toLowerCase();
  G.W={w,word,rack:scramble(word).map((c,i)=>({c,id:i})),ans:Array(word.length).fill(null),fixed:new Set(),tries:0,hinted:false,state:'play'};
  $('def').textContent=w.d; $('prompt').classList.remove('ok'); $('hintline').hidden=true; $('badge').hidden=true; $('example').hidden=true;
  $('nextBtn').hidden=true; $('hintBtn').disabled=false; $('note').textContent=T.tries(TRIES);
  render();
}
function render(){
  const W=G.W;
  $('answer').className='answer'+(W.state==='won'?' ok':'');
  $('answer').innerHTML=W.ans.map((t,i)=>t?`<button class="tile${W.fixed.has(i)?' fixed':''}" data-a="${i}" data-pts="${PTS[t.c]||1}">${esc(t.c)}</button>`:`<span class="tile slot"></span>`).join('');
  $('rack').innerHTML=W.rack.map(t=>`<button class="tile" data-r="${t.id}" data-pts="${PTS[t.c]||1}">${esc(t.c)}</button>`).join('');
}
$('rack').addEventListener('click',e=>{
  const b=e.target.closest('.tile'); if(!b||!G||G.preview||G.W.state!=='play') return;
  const W=G.W, k=W.rack.findIndex(t=>t.id===+b.dataset.r); if(k<0) return;
  const i=W.ans.findIndex(x=>!x); if(i<0) return;
  W.ans[i]=W.rack.splice(k,1)[0]; render(); const el=$('answer').children[i]; el&&el.classList.add('in');
  tone(500+i*40,.05,{type:'triangle',v:.05});
  if(W.ans.every(Boolean)) setTimeout(check,180);
});
$('answer').addEventListener('click',e=>{
  const b=e.target.closest('.tile'); if(!b||b.classList.contains('slot')||!G||G.W.state!=='play') return;
  const W=G.W, i=+b.dataset.a; if(W.fixed.has(i)) return;
  W.rack.push(W.ans[i]); W.ans[i]=null; SFX.tap(); render();
});
$('shuffleBtn').addEventListener('click',()=>{ if(!G||G.W.state!=='play') return; K.shuffle(G.W.rack); render(); tone(400,.05,{type:'triangle',v:.04}) });
$('hintBtn').addEventListener('click',()=>{
  const W=G.W; if(!W||W.state!=='play'||W.hinted||G.preview) return; W.hinted=true; $('hintBtn').disabled=true;
  // put the right first letter in place and fix it
  if(W.ans[0]){ W.rack.push(W.ans[0]); W.ans[0]=null }
  let k=W.rack.findIndex(t=>t.c===W.word[0]);
  if(k<0){ const j=W.ans.findIndex((t,i)=>t&&i>0&&t.c===W.word[0]); W.rack.push(W.ans[j]); W.ans[j]=null; k=W.rack.length-1 }
  W.ans[0]=W.rack.splice(k,1)[0]; W.fixed.add(0);
  tone(880,.08,{type:'triangle',v:.06}); render();
});
function check(){
  const W=G.W; W.tries++;
  const made=W.ans.map(t=>t.c).join('');
  if(made===W.word){
    if(W.tries===1&&!W.hinted) G.eng.submit(W.w.id,true,'medium'); else if(W.tries===1) G.eng.submit(W.w.id,true,'weak');
    W.state='won'; const lvl=Math.min(2,W.tries-1+(W.hinted?1:0)); const c=PAY[lvl]*TIER; G.coins+=c; G.built++;
    if(W.tries===1&&!W.hinted){ G.first++; G.streak++ } else G.streak=0;
    $('coinTxt').textContent=G.coins; $('streakChip').textContent=G.streak>=2?T.streak(G.streak):'';
    $('prompt').classList.add('ok'); render(); SFX.right(G.streak); setTimeout(()=>SFX.coin(),160); K.badge($('badge'),T.ok(c),true,1200);
    if(G.streak===4) K.doni(T.praise(G.streak));
    return after();
  }
  if(W.tries===1) G.eng.submit(W.w.id,false);
  G.streak=0; $('streakChip').textContent='';
  const a=$('answer'); a.classList.remove('wrong'); void a.offsetWidth; a.classList.add('wrong'); SFX.wrong();
  if(W.tries>=TRIES){ W.state='lost'; W.ans=[...W.word].map((c,i)=>({c,id:100+i})); W.rack=[]; render(); K.badge($('badge'),T.was(W.w.w),false,1800); return after() }
  K.badge($('badge'),T.notQuite,false,1000); $('note').textContent=T.tries(TRIES-W.tries);
  setTimeout(()=>{ W.ans.forEach((t,i)=>{ if(t&&!W.fixed.has(i)){ W.rack.push(t); W.ans[i]=null } }); K.shuffle(W.rack); render() },500);
}
$('idkBtn').addEventListener('click',()=>{
  const W=G&&G.W; if(!W||W.state!=='play'||G.preview) return;
  if(W.tries===0) G.eng.submit(W.w.id,false);
  W.state='lost'; G.streak=0; $('streakChip').textContent=''; W.ans=[...W.word].map((c,i)=>({c,id:100+i})); W.rack=[]; render(); K.badge($('badge'),T.was(W.w.w),false,1800); after();
});
function after(){
  const W=G.W; $('hintBtn').disabled=true; $('note').textContent='';
  const ex=$('example'); ex.innerHTML=esc(W.w.s).replace('___',`<b>${esc(W.w.f)}</b>`); ex.hidden=false;
  const b=$('nextBtn'); b.hidden=false; b.textContent=G.n>=ROUND?T.finish:T.next; b.focus();
}
$('nextBtn').addEventListener('click',()=>{ if(G) nextWord() });
addEventListener('keydown',e=>{
  if(!G||!G.W||G.W.state!=='play'||!$('startOv').hidden) return; const ch=e.key.toLowerCase();
  if(/^[a-z]$/.test(ch)){ const t=G.W.rack.find(x=>x.c===ch); if(t){ const b=$('rack').querySelector(`[data-r="${t.id}"]`); b&&b.click() } }
  else if(e.key==='Backspace'){ const W=G.W; for(let i=W.ans.length-1;i>=0;i--){ if(W.ans[i]&&!W.fixed.has(i)){ W.rack.push(W.ans[i]); W.ans[i]=null; render(); break } } }
});
function finish(){
  SFX.win();
  K.end({title:T.done,stats:[{v:G.coins,l:T.stCoins},{v:`${G.built}/${ROUND}`,l:T.stWords},{v:G.first,l:T.stFirst}],
    results:G.eng.results(),payload:{game:'letter-tiles',tier:TIER,coins:G.coins}});
}
K.setup({text,onText:t=>{ T=t },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

