crossword.js:
/* ═════════ Crossword (definition clues, typed answers) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone} = K;
const TIER = 3;              // hidden tier: Recall (typed)
const PAY = [3,1];           // coins per word: first try with no letter shown, otherwise, times TIER
const TARGET = 8;            // words in the grid

const text = {
  en:{title:'Crossword',lede:'A crossword built from your words. Every clue is a meaning; type the word and it fills the grid.',
      rules:['<b>Tap a square</b> or use the arrows to choose a clue, then type the word.','Letters from words you have already solved help with the ones that cross them.','<b>Letter</b> shows one letter for fewer coins. Your first answer to each word is what counts.'],
      start:'Start the crossword',across:'Across',down:'Down',clueNo:(n,d)=>`${n} ${d} · ${'{len}'}`,letters:n=>`${n} letters`,
      type:'Type the answer',go:'Fill',letter:'Letter',notQuite:'Not quite',close:w=>`Close · it's spelled ${w}`,was:w=>`The word was: ${w}`,
      ok:c=>`Correct · +${c}`,solved:n=>`${n} left`,done:'Crossword complete',stCoins:'coins',stWords:'words solved',stClean:'first try, no help',praise:'The whole grid, first try.'},
  uz:{title:'Krossvord',lede:'So\'zlaringizdan tuzilgan krossvord. Har bir savol bu ma\'no; so\'zni yozing, u katakchalarni to\'ldiradi.',
      rules:['Savolni tanlash uchun <b>katakchani bosing</b> yoki strelkalardan foydalaning, so\'ng so\'zni yozing.','Yechilgan so\'zlarning harflari ularni kesib o\'tadigan so\'zlarga yordam beradi.','<b>Harf</b> bitta harfni ko\'rsatadi, kamroq tanga uchun. Har bir so\'zga birinchi javobingiz hisoblanadi.'],
      start:'Krossvordni boshlash',across:'Gorizontal',down:'Vertikal',clueNo:(n,d)=>`${n} ${d}`,letters:n=>`${n} ta harf`,
      type:'Javobni yozing',go:'To\'ldirish',letter:'Harf',notQuite:'Hali emas',close:w=>`Deyarli · to'g'ri yozilishi: ${w}`,was:w=>`So'z: ${w}`,
      ok:c=>`To'g'ri · +${c}`,solved:n=>`${n} ta qoldi`,done:'Krossvord tugadi',stCoins:'tanga',stWords:'yechilgan so\'zlar',stClean:'birinchi urinish, yordamsiz',praise:'Butun krossvord birinchi urinishda.'}
};

/* ───────── Grid builder: places words so they cross, never side by side ───────── */
function build(words){
  const cells=new Map(), key=(r,c)=>r+','+c, get=(r,c)=>cells.get(key(r,c));
  const placed=[]; let bb={r0:0,c0:0,r1:0,c1:0};
  function fits(w,r,c,dir){
    const dr=dir==='d'?1:0, dc=dir==='a'?1:0; let cross=0;
    if(get(r-dr,c-dc)||get(r+dr*w.length,c+dc*w.length)) return -1;
    for(let i=0;i<w.length;i++){
      const rr=r+dr*i, cc=c+dc*i, ex=get(rr,cc);
      if(ex){ if(ex.ch!==w[i]||ex[dir]) return -1; cross++; continue }
      // no neighbours alongside a new letter
      if(get(rr+dc,cc+dr)||get(rr-dc,cc-dr)) return -1;
    }
    return cross;
  }
  function put(item,r,c,dir){
    const w=item.word, dr=dir==='d'?1:0, dc=dir==='a'?1:0;
    for(let i=0;i<w.length;i++){ const k=key(r+dr*i,c+dc*i); const ex=cells.get(k)||{ch:w[i]}; ex[dir]=item; cells.set(k,ex) }
    placed.push({...item,r,c,dir});
    bb={r0:Math.min(bb.r0,r),c0:Math.min(bb.c0,c),r1:Math.max(bb.r1,r+dr*(w.length-1)),c1:Math.max(bb.c1,c+dc*(w.length-1))};
  }
  // compact grids fit a phone: score crossings first, then the smallest square-ish box
  function cost(w,r,c,dir){ const dr=dir==='d'?1:0, dc=dir==='a'?1:0; const r0=Math.min(bb.r0,r), c0=Math.min(bb.c0,c), r1=Math.max(bb.r1,r+dr*(w.length-1)), c1=Math.max(bb.c1,c+dc*(w.length-1)); const h=r1-r0+1, wd=c1-c0+1; return Math.max(h,wd)*3+h*wd/10 }
  const list=[...words].sort((a,b)=>b.word.length-a.word.length);
  put(list[0],0,0,'a');
  for(const item of list.slice(1)){
    if(placed.length>=TARGET) break;
    let best=null;
    for(const [k,cell] of cells){
      const [r0,c0]=k.split(',').map(Number);
      for(let i=0;i<item.word.length;i++){
        if(item.word[i]!==cell.ch) continue;
        for(const dir of ['a','d']){
          if(cell[dir]) continue;
          const r=dir==='d'?r0-i:r0, c=dir==='a'?c0-i:c0;
          const s=fits(item.word,r,c,dir);
          if(s>0){ const sc=s*8-cost(item.word,r,c,dir)+K.rng(); if(!best||sc>best.sc) best={r,c,dir,s,sc} }
        }
      }
    }
    if(best) put(item,best.r,best.c,best.dir);
  }
  // normalise and number
  let minR=1e9,minC=1e9,maxR=-1e9,maxC=-1e9;
  for(const k of cells.keys()){ const [r,c]=k.split(',').map(Number); minR=Math.min(minR,r); minC=Math.min(minC,c); maxR=Math.max(maxR,r); maxC=Math.max(maxC,c) }
  placed.forEach(p=>{ p.r-=minR; p.c-=minC });
  const starts=[...new Set(placed.map(p=>p.r+','+p.c))].map(s=>s.split(',').map(Number)).sort((a,b)=>a[0]-b[0]||a[1]-b[1]);
  placed.forEach(p=>{ p.num=starts.findIndex(([r,c])=>r===p.r&&c===p.c)+1 });
  placed.sort((a,b)=>(a.dir===b.dir?0:a.dir==='a'?-1:1)||a.num-b.num);
  return {rows:maxR-minR+1,cols:maxC-minC+1,entries:placed};
}

let G=null, T=null;
function newRound(preview){
  const pool=K.shuffle(K.words.filter(w=>/^[a-z]+$/i.test(w.w)&&w.w.length>=3&&w.w.length<=11)).map(w=>({w,word:w.w.toLowerCase()}));
  let best=null; const size=b=>Math.max(b.rows,b.cols);
  // at least 7 words; then the smallest grid wins, then more words
  const better=(x,y)=>{ const ox=x.entries.length>=TARGET-1, oy=y.entries.length>=TARGET-1; if(ox!==oy) return ox; if(size(x)!==size(y)) return size(x)<size(y); return x.entries.length>y.entries.length };
  for(let t=0;t<60;t++){ const b=build(K.shuffle([...pool]).slice(0,14)); if(!best||better(b,best)) best=b; if(best.entries.length>=TARGET&&size(best)<=10) break }
  const eng=K.engine(best.entries.map(e=>e.w));
  G={...best,eng,cur:0,coins:0,solved:0,clean:0,preview:!!preview,over:false}; $('coinTxt').textContent=0;
  G.entries.forEach(e=>{ e.state='open'; e.tries=0; e.hints=new Set() });
  layout(); render(); select(0);
}
function cellsOf(e){ return [...Array(e.word.length)].map((_,i)=>[e.r+(e.dir==='d'?i:0), e.c+(e.dir==='a'?i:0)]) }
function letterAt(r,c){ for(const e of G.entries){ if(e.state==='open') continue; const i=cellsOf(e).findIndex(([a,b])=>a===r&&b===c); if(i>=0) return {ch:e.word[i],st:e.state} } return null }
function hintAt(r,c){ for(const e of G.entries){ const i=cellsOf(e).findIndex(([a,b])=>a===r&&b===c); if(i>=0&&e.hints.has(i)) return e.word[i] } return null }
function layout(){
  const wrap=$('gridwrap').getBoundingClientRect();
  const cell=Math.max(18,Math.min(42,Math.floor((wrap.width-20-(G.cols-1)*2)/G.cols),Math.floor((wrap.height-20-(G.rows-1)*2)/G.rows)));
  const g=$('xgrid'); g.style.setProperty('--cols',G.cols); g.style.setProperty('--rows',G.rows); g.style.setProperty('--cell',cell+'px');
}
new ResizeObserver(()=>{ if(G) layout() }).observe($('gridwrap'));
function render(){
  const used=new Map(); G.entries.forEach((e,ei)=>cellsOf(e).forEach(([r,c])=>{ const k=r+','+c; if(!used.has(k)) used.set(k,[]); used.get(k).push(ei) }));
  const nums=new Map(); G.entries.forEach(e=>nums.set(e.r+','+e.c,e.num));
  const curCells=new Set(cellsOf(G.entries[G.cur]||G.entries[0]).map(([r,c])=>r+','+c));
  let html='';
  for(let r=0;r<G.rows;r++) for(let c=0;c<G.cols;c++){
    const k=r+','+c;
    if(!used.has(k)){ html+='<span class="cell void"></span>'; continue }
    const L=letterAt(r,c), h=hintAt(r,c);
    const cls=['cell']; if(curCells.has(k)) cls.push('on'); if(L) cls.push(L.st==='solved'?'ok':'shown'); else if(h) cls.push('hintc');
    html+=`<button class="${cls.join(' ')}" data-k="${k}">${nums.has(k)?`<span class="n">${nums.get(k)}</span>`:''}${L?L.ch:(h||'')}</button>`;
  }
  $('xgrid').innerHTML=html;
  $('progChip').textContent=`${G.solved}/${G.entries.length}`;
}
function select(i){
  G.cur=(i+G.entries.length)%G.entries.length; const e=G.entries[G.cur];
  $('clueNo').textContent=`${e.num} ${e.dir==='a'?T.across:T.down} · ${T.letters(e.word.length)}`;
  $('clue').textContent=e.w.d; $('prompt').classList.toggle('ok',e.state==='solved'); $('badge').hidden=true;
  const open=e.state==='open'; $('inp').disabled=!open; $('goBtn').disabled=!open; $('hintBtn').disabled=!open; $('idkBtn').disabled=!open;
  $('inp').value=''; $('inp').placeholder=T.type; $('goBtn').textContent=T.go; $('note').textContent=T.solved(G.entries.length-G.solved);
  render(); if(open&&!G.preview) $('inp').focus();
}
$('prevBtn').addEventListener('click',()=>select(G.cur-1));
$('nextBtn').addEventListener('click',()=>{ const n=G.entries.findIndex((e,i)=>i>G.cur&&e.state==='open'); select(n>=0?n:G.cur+1) });
['prevBtn','nextBtn','hintBtn','idkBtn'].forEach(id=>$(id).addEventListener('pointerdown',e=>{ if(document.activeElement===$('inp')) e.preventDefault() }));
$('xgrid').addEventListener('click',e=>{
  const b=e.target.closest('.cell'); if(!b||!G) return; const [r,c]=b.dataset.k.split(',').map(Number);
  const hits=G.entries.map((x,i)=>[x,i]).filter(([x])=>cellsOf(x).some(([a,b2])=>a===r&&b2===c));
  // tapping a crossing square again switches direction
  const pick=hits.length>1&&hits[0][1]===G.cur?hits[1]:hits.find(([x])=>x.state==='open')||hits[0];
  select(pick[1]);
});
$('typer').addEventListener('submit',e=>{
  e.preventDefault(); if(!G||G.preview||G.over) return;
  const en=G.entries[G.cur]; if(en.state!=='open') return;
  const v=$('inp').value; if(!K.norm(v)) return;
  const r=K.judge(v,en.w);
  en.tries++;
  if(!r){
    if(en.tries===1) G.eng.submit(en.w.id,false);
    const t=$('typer'); t.classList.remove('shake'); void t.offsetWidth; t.classList.add('shake'); SFX.wrong(); K.badge($('badge'),T.notQuite,false,1100); $('inp').select(); return;
  }
  const clean=en.tries===1&&en.hints.size===0;
  if(en.tries===1) G.eng.submit(en.w.id,true,clean&&r==='exact'?'strong':'medium');
  en.state='solved'; G.solved++; if(clean) G.clean++;
  const c=(clean?PAY[0]:PAY[1])*TIER; G.coins+=c; $('coinTxt').textContent=G.coins;
  render(); cellsOf(en).forEach(([a,b],i)=>{ const el=$('xgrid').querySelector(`[data-k="${a},${b}"]`); if(el) setTimeout(()=>{ el.classList.add('pop'); tone(523*Math.pow(1.06,i),.06,{type:'triangle',v:.05}) },i*50) });
  $('prompt').classList.add('ok'); SFX.coin(); K.badge($('badge'),r==='close'?T.close(en.w.w):T.ok(c),true,1300);
  afterWord();
});
$('hintBtn').addEventListener('click',()=>{
  const en=G&&G.entries[G.cur]; if(!en||en.state!=='open'||G.preview) return;
  const crossing=new Set(cellsOf(en).map(([r,c],i)=>letterAt(r,c)?i:-1).filter(i=>i>=0));
  const free=[...Array(en.word.length).keys()].filter(i=>!en.hints.has(i)&&!crossing.has(i)); if(!free.length) return;
  en.hints.add(free[0]); tone(880,.08,{type:'triangle',v:.06}); render(); $('inp').focus();
});
$('idkBtn').addEventListener('click',()=>{
  const en=G&&G.entries[G.cur]; if(!en||en.state!=='open'||G.preview) return;
  if(en.tries===0) G.eng.submit(en.w.id,false);
  en.state='shown'; SFX.wrong(); K.badge($('badge'),T.was(en.w.w),false,1600); render(); afterWord();
});
function afterWord(){
  const left=G.entries.filter(e=>e.state==='open');
  $('note').textContent=T.solved(left.length);
  if(!left.length) return setTimeout(finish,900);
  const nextI=G.entries.findIndex((e,i)=>i>G.cur&&e.state==='open'); const i=nextI>=0?nextI:G.entries.indexOf(left[0]);
  setTimeout(()=>select(i),900);
}
function finish(){
  G.over=true; $('inp').blur();
  if(G.clean===G.entries.length) K.doni(T.praise);
  SFX.win();
  K.end({title:T.done,stats:[{v:G.coins,l:T.stCoins},{v:`${G.solved}/${G.entries.length}`,l:T.stWords},{v:G.clean,l:T.stClean}],
    results:G.eng.results(),payload:{game:'crossword',tier:TIER,coins:G.coins,size:`${G.cols}x${G.rows}`}});
}
K.setup({text,onText:t=>{ T=t; if(G) select(G.cur) },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

