boss.js:
/* ═════════ Boss Word ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 4;              // hidden tier: the strongest check, typed with no options
const PAY = [4,2,1];         // coins by clue phase (meaning only, + sentence, + first letter), times TIER
const BOSS_BONUS = 3;        // times TIER, per boss defeated
const LIVES = 3, HP = 2;     // three bosses, two hard words each

const BOSSES = [
  {key:'golem',en:'The Gloom Golem',uz:'Qorong\'u Golem',svg:`<svg viewBox="0 0 200 200"><ellipse cx="100" cy="186" rx="60" ry="8" fill="rgba(0,0,0,.35)"/><rect x="48" y="60" width="104" height="112" rx="26" fill="#6B5A4A"/><rect x="56" y="68" width="88" height="40" rx="14" fill="#7E6B58"/><path d="M60 150l18-20M118 158l22-26M90 172l10-18" stroke="#4A3D32" stroke-width="5" stroke-linecap="round"/><circle cx="80" cy="92" r="10" fill="#FFB020"/><circle cx="120" cy="92" r="10" fill="#FFB020"/><circle cx="80" cy="92" r="4" fill="#2B1300"/><circle cx="120" cy="92" r="4" fill="#2B1300"/><path d="M78 124q22 14 44 0" stroke="#2B1300" stroke-width="6" fill="none" stroke-linecap="round"/><rect x="22" y="86" width="30" height="64" rx="14" fill="#5C4C3E"/><rect x="148" y="86" width="30" height="64" rx="14" fill="#5C4C3E"/><path d="M70 60l10-22 12 22M108 60l12-24 10 24" fill="#7E6B58"/></svg>`},
  {key:'wyrm',en:'The Riddle Wyrm',uz:'Topishmoq Ajdari',svg:`<svg viewBox="0 0 200 200"><ellipse cx="100" cy="186" rx="64" ry="8" fill="rgba(0,0,0,.35)"/><path d="M40 170c0-40 30-50 30-80s-20-40 0-60c20 18 40 10 60 0 20 20 0 30 0 60s30 40 30 80z" fill="#2E7D5B"/><path d="M60 170c0-30 22-40 22-70M140 170c0-30-22-40-22-70" stroke="#256A4C" stroke-width="6" fill="none"/><path d="M70 30l-14-22 26 10M130 30l14-22-26 10" fill="#E8C96A"/><ellipse cx="82" cy="62" rx="11" ry="13" fill="#FFE27A"/><ellipse cx="118" cy="62" rx="11" ry="13" fill="#FFE27A"/><ellipse cx="82" cy="64" rx="4" ry="9" fill="#1E0E00"/><ellipse cx="118" cy="64" rx="4" ry="9" fill="#1E0E00"/><path d="M84 92q16 10 32 0" stroke="#1E0E00" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M92 96l4 10 4-10M104 96l4 10 4-10" fill="#fff"/><text x="100" y="150" text-anchor="middle" font-size="34" font-weight="900" fill="#E8C96A" font-family="system-ui">?</text></svg>`},
  {key:'lich',en:'The Lexicon Lich',uz:'Lug\'at Arvohi',svg:`<svg viewBox="0 0 200 200"><ellipse cx="100" cy="186" rx="56" ry="8" fill="rgba(0,0,0,.35)"/><path d="M50 180l14-96c4-30 22-48 36-48s32 18 36 48l14 96z" fill="#3A2A6A"/><path d="M64 84c4-28 20-44 36-44s32 16 36 44c-10-8-22-12-36-12s-26 4-36 12z" fill="#4E3A8A"/><ellipse cx="100" cy="92" rx="28" ry="30" fill="#E9E2FF"/><circle cx="88" cy="88" r="7" fill="#7FE0FF"/><circle cx="112" cy="88" r="7" fill="#7FE0FF"/><path d="M88 110h24" stroke="#3A2A6A" stroke-width="4" stroke-linecap="round"/><path d="M92 110v6M100 110v6M108 110v6" stroke="#3A2A6A" stroke-width="3"/><rect x="66" y="130" width="68" height="40" rx="6" fill="#F5E6C8"/><path d="M100 130v40M74 140h20M74 150h18M106 140h20M106 150h18" stroke="#B8A27A" stroke-width="2.5"/><path d="M30 60l10-10 10 10-10 10z" fill="#FFE27A"/><path d="M156 44l8-8 8 8-8 8z" fill="#FFE27A"/></svg>`}
];

const text = {
  en:{title:'Boss Word',lede:'Three bosses guard your hardest words. No options to pick from: type each word from its meaning to strike.',
      rules:['<b>Type the word</b> from its meaning alone for a critical hit.','A miss reveals more: first a sentence with the word missing, then its first letter.','After three misses the boss strikes back and you lose a heart. Lose all three and the gauntlet ends.'],
      start:'Enter the gauntlet',p1:'Meaning only · critical hit',p2:'Clue: the word in a sentence',p3:'Clue: the first letter',type:'Type the word',strike:'Strike',
      crit:c=>`Critical hit · +${c}`,hit:c=>`Hit · +${c}`,miss:'Blocked',was:w=>`The boss struck · the word was ${w}`,close:w=>`Hit · it's spelled ${w}`,
      defeated:n=>`${n} defeated`,next:'Next boss',win:'Gauntlet cleared',lose:'The bosses won this time',
      stCoins:'coins',stBosses:'bosses defeated',stCrit:'critical hits',praise:w=>`${w}, from the meaning alone. That's a boss word.`},
  uz:{title:'Boss so\'z',lede:'Uchta boss eng qiyin so\'zlaringizni qo\'riqlaydi. Tanlash uchun variant yo\'q: zarba berish uchun har bir so\'zni ma\'nosiga qarab yozing.',
      rules:['Kuchli zarba uchun <b>so\'zni faqat ma\'nosiga qarab yozing</b>.','Xato qilsangiz, ko\'proq maslahat chiqadi: avval so\'z tushib qolgan gap, keyin birinchi harf.','Uchta xatodan keyin boss javob zarbasini beradi va bitta yurak yo\'qoladi. Uchalasi tugasa, sinov tugaydi.'],
      start:'Sinovga kirish',p1:'Faqat ma\'no · kuchli zarba',p2:'Maslahat: so\'z gapda',p3:'Maslahat: birinchi harf',type:'So\'zni yozing',strike:'Zarba',
      crit:c=>`Kuchli zarba · +${c}`,hit:c=>`Zarba · +${c}`,miss:'To\'sib qoldi',was:w=>`Boss urdi · so'z: ${w}`,close:w=>`Zarba · to'g'ri yozilishi: ${w}`,
      defeated:n=>`${n} yengildi`,next:'Keyingi boss',win:'Sinovdan o\'tdingiz',lose:'Bu safar bosslar yutdi',
      stCoins:'tanga',stBosses:'yengilgan bosslar',stCrit:'kuchli zarbalar',praise:w=>`${w}, faqat ma'nosiga qarab. Mana bu boss so'z.`}
};

let G=null, T=null;
function newRound(preview){
  // the hardest due words go to the bosses
  const pool=[...K.words].sort((a,b)=>b.diff-a.diff||K.rng()-.5);
  const eng=K.engine(pool.slice(0,Math.max(8,LIVES*HP+2)));
  G={eng,bi:-1,lives:LIVES,coins:0,beaten:0,crit:0,preview:!!preview,over:false,B:null};
  K.hearts($('lives'),LIVES,LIVES); $('coinTxt').textContent=0; nextBoss();
}
function nextBoss(){
  G.bi++;
  if(G.bi>=BOSSES.length) return finish(true);
  const b=BOSSES[G.bi];
  G.B={b,hp:HP,w:null,phase:0,used:new Set()};
  $('bossName').textContent=K.LEVELS[K.level].text==='uz'?b.uz:b.en;
  const el=$('boss'); el.className='boss'; el.innerHTML=b.svg;
  $('progChip').textContent=`${G.bi+1}/${BOSSES.length}`; renderHp();
  noise(.5,{v:.2,f:150,type:'lowpass'}); tone(110,.5,{type:'sawtooth',v:.04,to:70});
  nextWord();
}
function renderHp(){ $('hp').innerHTML=[...Array(HP)].map((_,i)=>`<i class="${i>=G.B.hp?'gone':''}"></i>`).join('') }
function nextWord(){
  const w=G.eng.next(3,[...G.B.used]); G.B.used.add(w.id);
  G.B.w=w; G.B.phase=0; G.B.first=true;
  $('def').textContent=w.d; $('ctx').hidden=true; $('hintline').hidden=true; $('badge').hidden=true; $('prompt').classList.remove('ok');
  $('inp').value=''; $('inp').placeholder=T.type; $('goBtn').textContent=T.strike; $('inp').disabled=false; $('goBtn').disabled=false; $('idkBtn').disabled=false;
  phaseUi(); if(!G.preview) setTimeout(()=>$('inp').focus(),50);
}
function phaseUi(){
  const B=G.B, w=B.w;
  $('phaseLbl').textContent=[T.p1,T.p2,T.p3][B.phase];
  if(B.phase>=1){ const c=$('ctx'); c.textContent=w.s.replace('___','_____'); c.hidden=false }
  if(B.phase>=2){ const h=$('hintline'); const f=(w.f||w.w); h.textContent=f[0].toUpperCase()+' '+'_ '.repeat(f.length-1).trim(); h.hidden=false }
  $('note').textContent='';
}
$('typer').addEventListener('submit',e=>{
  e.preventDefault(); if(!G||G.preview||G.over) return;
  const B=G.B, v=$('inp').value; if(!K.norm(v)) return;
  const r=K.judge(v,B.w);
  if(r) return strike(r);
  if(B.first){ G.eng.submit(B.w.id,false); B.first=false }
  const t=$('typer'); t.classList.remove('shake'); void t.offsetWidth; t.classList.add('shake');
  noise(.1,{v:.3,f:800,q:2}); K.badge($('badge'),T.miss,false,1000);
  B.phase++;
  if(B.phase>2) return bossStrikes();
  phaseUi(); $('inp').select();
});
$('idkBtn').addEventListener('click',()=>{ if(!G||G.preview||G.over) return; if(G.B.first){ G.eng.submit(G.B.w.id,false); G.B.first=false } bossStrikes() });
$('idkBtn').addEventListener('pointerdown',e=>{ if(document.activeElement===$('inp')) e.preventDefault() });
function strike(r){
  const B=G.B, crit=B.phase===0&&r==='exact';
  if(B.first) G.eng.submit(B.w.id,true,B.phase===0?(r==='exact'?'strong':'medium'):'medium');
  const c=PAY[B.phase]*TIER; G.coins+=c; if(crit) G.crit++; $('coinTxt').textContent=G.coins;
  B.hp--; renderHp();
  const el=$('boss'); el.classList.remove('hit'); void el.offsetWidth; el.classList.add('hit');
  const fx=$('hitfx'); fx.className='hitfx'; void fx.offsetWidth; fx.className='hitfx go';
  noise(.2,{v:.5,f:crit?600:1000,q:.7}); tone(crit?220:300,.25,{type:'sawtooth',v:.07,to:80}); setTimeout(()=>SFX.coin(),200);
  $('prompt').classList.add('ok'); K.badge($('badge'),r==='close'?T.close(B.w.w):crit?T.crit(c):T.hit(c),true,1300);
  if(crit&&B.w.diff>=3) K.doni(T.praise(K.cap(B.w.w)));
  lockInput();
  if(B.hp<=0) return setTimeout(defeat,800);
  setTimeout(nextWord,1100);
}
function bossStrikes(){
  const B=G.B; G.lives--; K.hearts($('lives'),G.lives,LIVES);
  const el=$('boss'); el.classList.remove('attack'); void el.offsetWidth; el.classList.add('attack');
  const fx=$('hitfx'); fx.className='hitfx'; void fx.offsetWidth; fx.className='hitfx hurt';
  noise(.4,{v:.5,f:200,type:'lowpass'}); tone(90,.4,{v:.16,to:40});
  K.badge($('badge'),T.was(B.w.w),false,2000); lockInput();
  if(G.lives<=0){ G.over=true; return setTimeout(()=>finish(false),2000) }
  setTimeout(nextWord,2100);
}
function lockInput(){ $('inp').disabled=true; $('goBtn').disabled=true; $('idkBtn').disabled=true }
function defeat(){
  const el=$('boss'); el.classList.add('down'); G.beaten++; G.coins+=BOSS_BONUS*TIER; $('coinTxt').textContent=G.coins;
  [392,523,659,784,1047].forEach((f,i)=>tone(f,.16,{type:'triangle',v:.08,at:i*.08}));
  K.banner(T.defeated($('bossName').textContent),'');
  setTimeout(nextBoss,1700);
}
function finish(won){
  G.over=true; $('inp').blur(); won?SFX.win():SFX.end();
  K.end({title:won?T.win:T.lose,stats:[{v:G.coins,l:T.stCoins},{v:`${G.beaten}/${BOSSES.length}`,l:T.stBosses},{v:G.crit,l:T.stCrit}],
    results:G.eng.results(),payload:{game:'boss-word',tier:TIER,coins:G.coins}});
}
K.setup({text,onText:t=>{ T=t; if(G&&G.B){ $('bossName').textContent=K.LEVELS[K.level].text==='uz'?G.B.b.uz:G.B.b.en; phaseUi() } },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

duel.css:
/* Word Duel: two players, one question; Connect stage pink */
:root{--stage:#D92F7A}
.duel{position:relative;flex:none;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:6px;border-radius:22px;padding:12px 10px 16px;background:radial-gradient(120% 140% at 50% 0%,#8E1450,#3D0722 75%);overflow:hidden}
.pl{display:grid;justify-items:center;gap:3px;text-align:center;min-width:0}
.pl b{font:800 14px var(--display);max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.av{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;font:900 20px var(--display);background:#fff;color:#D92F7A;box-shadow:0 0 0 3px rgba(255,255,255,.25);transition:transform .2s,box-shadow .2s}
.av.op{background:#FFD1E5;color:#7A0F43}
.av.go{animation:avgo .45s ease}
@keyframes avgo{40%{transform:scale(1.18)}}
.av.lit{box-shadow:0 0 0 4px var(--green),0 0 24px rgba(19,138,61,.7)}
.pts{font:900 30px/1 var(--display);font-variant-numeric:tabular-nums}
.pts.bump{animation:bump .4s ease}
@keyframes bump{40%{transform:scale(1.35)}}
.st{font:700 12px var(--display);opacity:.85;min-height:15px}
.st.ok{color:#9BF0B8;opacity:1}.st.no{color:#FFC2D9;opacity:1}
.vs{display:grid;justify-items:center;gap:4px}
.vs span{font:900 18px var(--display);letter-spacing:.06em;color:#FFD1E5}
.goal{font:700 11px var(--display);opacity:.75;text-align:center;max-width:90px}
.timer{position:absolute;left:12px;right:12px;bottom:7px;height:4px;border-radius:9px;background:rgba(255,255,255,.15);overflow:hidden}
.timer i{display:block;height:100%;width:100%;background:#fff;transform-origin:left;transform:scaleX(0)}
.timer i.run{animation:tick var(--ms) linear forwards}
@keyframes tick{from{transform:scaleX(1)}to{transform:scaleX(0)}}
.opts.wait .opt{opacity:0;pointer-events:none}
.opts .opt{transition:opacity .25s,transform .1s,background .15s}
.opts.locked .opt:not(.sel):not(.right):not(.reveal){opacity:.45}
.typer{flex:none;display:flex;gap:8px}
.typer input{flex:1;min-width:0;height:54px;border:0;border-radius:17px;background:#fff;color:var(--ink);font:800 21px var(--display);padding:0 16px}
.typer .go{height:54px;border:0;border-radius:17px;background:#3D0722;color:#fff;font:800 17px var(--display);padding:0 18px}
.typer.shake input{animation:tshake .32s}
@keyframes tshake{25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}
.row{flex:none;display:flex;gap:8px;align-items:center}
.row .note{flex:1;text-align:center;font:700 13px var(--display);opacity:.8}
.small{border:0;background:var(--glass);border-radius:99px;height:36px;padding:0 14px;font:800 14px var(--display)}
.small:disabled{opacity:.4}
@media (max-height:640px){.av{width:40px;height:40px;font-size:17px}.pts{font-size:25px}.typer input,.typer .go{height:48px}}
@media (prefers-reduced-motion:reduce){.av.go,.pts.bump,.typer.shake input{animation:none}.timer i.run{animation:none;transform:scaleX(.5)}}

duel.js:
/* ═════════ Word Duel (1 v 1) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 2;               // hidden tier: context choice (medium evidence); definition rounds are weak
const GOAL = 8, ROUNDS = 10;  // first to 8 points, or most points after 10 rounds
const READ_MS = 900;          // the question shows alone first: read, then choose
const LIMIT = 12000, TYPE_LIMIT = 25000;
// points: right +1, first right +1 more, wrong −1, "I don't know" 0. A blind guess on 4 options loses points on average.
const COIN_RIGHT = 2, COIN_FIRST = 1, WIN_BONUS = 5, SUDDEN_BONUS = 4;   // times TIER, only for right answers

const text = {
  en:{title:'Word Duel',lede:'One opponent, the same question at the same moment. Read, pick once, and outscore them.',
      rules:['<b>Right +1</b>, and <b>+1 more</b> if you were right first.','<b>Wrong −1.</b> "I don\'t know" is 0, so a blind guess costs you.','First to 8 points wins, or the most after 10 rounds. A tie ends with a typed sudden word.'],
      start:'Find an opponent',fits:'Which word fits?',means:'Which word means',typeAsk:'Sudden word · type the word that means',type:'Type the word',go:'Go',
      you:'You',thinking:'thinking…',answered:'answered',right:'right',wrong:'wrong',pass:'passed',none:'no answer',goal:`First to ${GOAL}`,
      read:'Read first…',first:'First!',sudden:'Sudden word',suddenSub:'First correct typed word wins',
      win:n=>`You beat ${n}`,lose:n=>`${n} won this duel`,draw:'Honours even',was:w=>`It was: ${w}`,
      stCoins:'coins',stScore:'final score',stRight:'right answers',found:n=>`Opponent: ${n}`,praise:'Typed under pressure. That word is yours now.',
      sim:'Practice opponent · on the site this is a real classmate'},
  uz:{title:'So\'z dueli',lede:'Bitta raqib, bir vaqtda bir xil savol. O\'qing, bir marta tanlang va undan ko\'p ochko yig\'ing.',
      rules:['<b>To\'g\'ri +1</b>, birinchi bo\'lib to\'g\'ri topsangiz <b>yana +1</b>.','<b>Xato −1.</b> "Bilmayman" 0, shuning uchun taxmin qilish zarar.','8 ochkoga birinchi yetgan yoki 10 raunddan keyin ko\'p ochko to\'plagan yutadi. Durang bo\'lsa, so\'z yoziladi.'],
      start:'Raqib topish',fits:'Qaysi so\'z mos keladi?',means:'Qaysi so\'z ma\'nosi',typeAsk:'Hal qiluvchi so\'z · ma\'nosiga qarab yozing',type:'So\'zni yozing',go:'Yuborish',
      you:'Siz',thinking:'o\'ylayapti…',answered:'javob berdi',right:'to\'g\'ri',wrong:'xato',pass:'o\'tkazdi',none:'javob yo\'q',goal:`${GOAL} ochkogacha`,
      read:'Avval o\'qing…',first:'Birinchi!',sudden:'Hal qiluvchi so\'z',suddenSub:'Birinchi to\'g\'ri yozgan yutadi',
      win:n=>`Siz ${n}ni yutdingiz`,lose:n=>`Bu duelda ${n} yutdi`,draw:'Durang',was:w=>`Javob: ${w}`,
      stCoins:'tanga',stScore:'yakuniy hisob',stRight:'to\'g\'ri javoblar',found:n=>`Raqib: ${n}`,praise:'Bosim ostida yozdingiz. Bu so\'z endi sizniki.',
      sim:'Mashq raqibi · saytda bu haqiqiy sinfdosh bo\'ladi'}
};

let G=null, T=null, timers=[];
const later=(fn,ms)=>{ const id=setTimeout(fn,ms); timers.push(id); return id };
const clearAll=()=>{ timers.forEach(clearTimeout); timers=[] };

function newRound(preview){
  clearAll();
  const R=K.room({size:2,you:T.you});
  G={R,op:R.players[1],eng:K.engine(K.words),me:0,them:0,round:0,coins:0,right:0,preview:!!preview,over:false,Q:null,sudden:0};
  $('meName').textContent=T.you; $('opName').textContent=G.op.name; $('opAv').textContent=G.op.name[0];
  $('goal').textContent=T.goal; score(); $('coinTxt').textContent=0;
  if(preview){ showQ(true); return }
  K.banner(T.found(G.op.name),T.sim); later(nextRound,1700);
}
function score(){ $('mePts').textContent=G.me; $('opPts').textContent=G.them; $('roundChip').textContent=`${Math.min(G.round,ROUNDS)||1}/${ROUNDS}` }
function status(who,txt,cls){ const el=$(who+'St'); el.textContent=txt; el.className='st'+(cls?' '+cls:'') }

function nextRound(){
  if(G.over) return;
  if(G.me>=GOAL||G.them>=GOAL||G.round>=ROUNDS){ return G.me===G.them ? sudden() : finish() }
  G.round++; score(); showQ(false);
}
function showQ(preview){
  const w=G.eng.next(1+Math.min(2,Math.floor(G.round/4)));
  const ctx=!!w.s&&K.rng()<.6;
  G.Q={w,ctx,opts:K.options(w,K.words),mine:null,theirs:null,done:false,t0:0};
  $('ask').textContent=ctx?T.fits:T.means;
  $('def').innerHTML=ctx?esc(w.s).replace('___','<u>&nbsp;?&nbsp;</u>'):esc(w.d);
  $('prompt').classList.remove('ok'); $('badge').hidden=true; $('typer').hidden=true; $('opts').hidden=false;
  $('opts').className='opts four wait';
  $('opts').innerHTML=G.Q.opts.map((o,i)=>`<button class="opt" data-i="${i}">${esc(o.w)}</button>`).join('');
  status('me',''); status('op',T.thinking); $('note').textContent=T.read; $('idkBtn').disabled=false;
  ['meAv','opAv'].forEach(id=>$(id).classList.remove('lit'));
  const tm=$('timer'); tm.classList.remove('run');
  if(preview) return;
  later(()=>{
    $('opts').classList.remove('wait'); $('note').textContent=''; G.Q.t0=performance.now();
    tm.style.setProperty('--ms',LIMIT+'ms'); void tm.offsetWidth; tm.classList.add('run');
    const b=G.R.bot(G.op,w,TIER);
    later(()=>{ if(G.Q.done) return; G.Q.theirs={ok:b.ok,t:b.t}; status('op',T.answered); $('opAv').classList.add('go'); later(()=>$('opAv').classList.remove('go'),500); tryResolve() },Math.min(b.t,LIMIT-200));
    later(()=>resolve(),LIMIT);
  },READ_MS);
}
$('opts').addEventListener('click',e=>{
  const b=e.target.closest('.opt'); const Q=G&&G.Q; if(!b||!Q||G.preview||Q.done||Q.mine||$('opts').classList.contains('wait')) return;
  const o=Q.opts[+b.dataset.i]; Q.mine={ok:o.id===Q.w.id,t:performance.now()-Q.t0,i:+b.dataset.i};
  b.classList.add('sel'); $('opts').classList.add('locked'); SFX.tap(); status('me',T.answered); $('idkBtn').disabled=true; tryResolve();
});
$('idkBtn').addEventListener('click',()=>{
  if(!G||G.preview||G.over) return;
  if(G.Q&&G.Q.sudden){ return suddenGiveUp() }
  const Q=G.Q; if(!Q||Q.done||Q.mine||$('opts').classList.contains('wait')) return;
  Q.mine={ok:false,pass:true,t:performance.now()-Q.t0}; $('opts').classList.add('locked'); status('me',T.pass); $('idkBtn').disabled=true; tryResolve();
});
function tryResolve(){ if(G.Q.mine&&G.Q.theirs) later(resolve,350) }
function resolve(){
  const Q=G.Q; if(!Q||Q.done) return; Q.done=true; clearAll();
  $('timer').classList.remove('run');
  const m=Q.mine, o=Q.theirs;
  // engine: the first answer per word counts; a pass is an honest "wrong"
  G.eng.submit(Q.w.id,!!(m&&m.ok),Q.ctx?'medium':'weak');
  const firstMe=m&&m.ok&&(!o||!o.ok||m.t<=o.t), firstOp=o&&o.ok&&!firstMe;
  let dMe=0,dOp=0;
  if(m&&m.ok){ dMe=1+(firstMe?1:0) } else if(m&&!m.pass){ dMe=-1 }
  if(o&&o.ok){ dOp=1+(firstOp?1:0) } else if(o){ dOp=-1 }
  G.me=Math.max(0,G.me+dMe); G.them=Math.max(0,G.them+dOp);
  status('me',!m?T.none:m.pass?T.pass:m.ok?`${T.right} +${dMe}`:`${T.wrong} −1`,m&&m.ok?'ok':m&&!m.pass?'no':'');
  status('op',!o?T.none:o.ok?`${T.right} +${dOp}`:`${T.wrong} −1`,o&&o.ok?'ok':o?'no':'');
  const btns=[...$('opts').children], ri=Q.opts.findIndex(x=>x.id===Q.w.id);
  $('opts').classList.remove('wait'); $('opts').classList.add('locked');
  if(m&&m.ok){ btns[m.i].classList.remove('sel'); btns[m.i].classList.add('right'); $('prompt').classList.add('ok');
    const c=(COIN_RIGHT+(firstMe?COIN_FIRST:0))*TIER; G.coins+=c; G.right++; $('coinTxt').textContent=G.coins;
    SFX.right(G.right); later(()=>SFX.coin(),150); K.badge($('badge'),firstMe?`${T.first} +${c}`:`+${c}`,true,1400); $('meAv').classList.add('lit') }
  else { btns[ri].classList.add('reveal'); if(m&&!m.pass){ btns[m.i].classList.add('dim'); SFX.wrong() } K.badge($('badge'),T.was(Q.w.w),false,1700) }
  if(firstOp) $('opAv').classList.add('lit');
  if(dMe) bump('mePts'); if(dOp) bump('opPts'); score();
  later(nextRound,2000);
}
function bump(id){ const el=$(id); el.classList.remove('bump'); void el.offsetWidth; el.classList.add('bump') }

/* Tie: a typed sudden word decides (strong evidence) */
function sudden(){
  G.sudden++;
  if(G.sudden>3) return finish();
  const w=G.eng.next(3);
  G.Q={w,sudden:true,done:false,theirs:null,first:true};
  K.banner(T.sudden,T.suddenSub); noise(.4,{v:.2,f:500});
  $('ask').textContent=T.typeAsk; $('def').textContent=w.d+`  (${(w.f||w.w).length})`; $('prompt').classList.remove('ok');
  $('opts').hidden=true; const ty=$('typer'); ty.hidden=false; $('inp').value=''; $('inp').placeholder=T.type; $('goBtn').textContent=T.go; $('inp').disabled=false;
  status('me',''); status('op',T.thinking); $('idkBtn').disabled=false; $('note').textContent='';
  later(()=>{ const tm=$('timer'); tm.style.setProperty('--ms',TYPE_LIMIT+'ms'); tm.classList.remove('run'); void tm.offsetWidth; tm.classList.add('run'); $('inp').focus();
    const b=G.R.bot(G.op,w,3);
    later(()=>{ if(G.Q.done) return; if(b.ok) suddenEnd(false); else { G.Q.theirs={ok:false}; status('op',T.pass) } },Math.min(b.t*1.6,TYPE_LIMIT-300));
    later(()=>{ if(!G.Q.done) suddenEnd(null) },TYPE_LIMIT);
  },1400);
}
$('typer').addEventListener('submit',e=>{
  e.preventDefault(); const Q=G&&G.Q; if(!Q||!Q.sudden||Q.done) return;
  const r=K.judge($('inp').value,Q.w);
  if(r){ if(Q.first) G.eng.submit(Q.w.id,true,r==='exact'?'strong':'medium'); return suddenEnd(true) }
  if(!K.norm($('inp').value)) return;
  if(Q.first){ G.eng.submit(Q.w.id,false); Q.first=false }
  const t=$('typer'); t.classList.remove('shake'); void t.offsetWidth; t.classList.add('shake'); SFX.wrong(); $('inp').select();
});
function suddenGiveUp(){ const Q=G.Q; if(Q.done) return; if(Q.first){ G.eng.submit(Q.w.id,false); Q.first=false } $('inp').disabled=true; status('me',T.pass); if(Q.theirs) suddenEnd(null) }
function suddenEnd(meWon){
  const Q=G.Q; Q.done=true; clearAll(); $('timer').classList.remove('run'); $('inp').disabled=true;
  if(meWon===true){ G.me++; const c=SUDDEN_BONUS*TIER; G.coins+=c; G.right++; $('coinTxt').textContent=G.coins; $('prompt').classList.add('ok'); SFX.right(3); K.badge($('badge'),`+${c}`,true,1400); K.doni(T.praise); bump('mePts') }
  else if(meWon===false){ G.them++; status('op',T.right,'ok'); K.badge($('badge'),T.was(Q.w.w),false,1800); bump('opPts'); SFX.wrong() }
  else { K.badge($('badge'),T.was(Q.w.w),false,1800) }
  score(); later(()=> G.me===G.them ? sudden() : finish(),2000);
}
function finish(){
  G.over=true; clearAll(); $('inp').blur();
  const won=G.me>G.them, draw=G.me===G.them;
  if(won){ G.coins+=WIN_BONUS*TIER; SFX.win() } else SFX.end();
  K.end({title:draw?T.draw:won?T.win(G.op.name):T.lose(G.op.name),stats:[{v:G.coins,l:T.stCoins},{v:`${G.me}–${G.them}`,l:T.stScore},{v:G.right,l:T.stRight}],
    results:G.eng.results(),payload:{game:'word-duel',tier:TIER,coins:G.coins,mode:G.R.mode,won,score:[G.me,G.them]}});
}
K.setup({text,onText:t=>{ T=t; if(G){ $('meName').textContent=T.you; $('goal').textContent=T.goal } },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

