/* ═════════ Tug of War (team vs team) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 1;              // hidden tier: recognition taps (weak evidence)
const TEAM = 3, GOAL = 8, QUESTIONS = 12;
const READ_MS = 800, LIMIT = 10000;
const PULL = {right:1, wrong:-2, pass:0, none:0};  // a wrong answer pulls the rope the other way, twice as far
const COIN_RIGHT = 2, WIN_BONUS = 4, MIN_RIGHT_FOR_BONUS = 3;  // times TIER; the team bonus needs your own right answers

const text = {
  en:{title:'Tug of War',lede:'Your team against theirs, one rope between you. Every answer pulls.',
      rules:['Everyone answers the same question. <b>Right pulls your way 1 step.</b>','<b>Wrong pulls the rope 2 steps the other way.</b> "I don\'t know" pulls nothing, so never guess for your team.',`Pull the flag ${GOAL} steps to your side, or be ahead after ${QUESTIONS} questions.`],
      start:'Pick up the rope',teamA:'Your team',teamB:'Rivals',you:'You',means:'Which word means',meaning:'What does this word mean?',read:'Read first…',
      net:n=>n>0?`Your team pulled ${n}`:n<0?`Rivals pulled ${-n}`:'No change',was:w=>`It was: ${w}`,
      win:'Your team won the tug',draw:'Dead even: nobody moved',lose:'The rivals won this time',stCoins:'coins',stRight:'your right answers',stPull:'your pull',
      noBonus:`The team bonus needs ${MIN_RIGHT_FOR_BONUS} right answers of your own`,praise:n=>`${n} right in a row. The rope felt that.`,
      sim:'Practice teams · on the site these are your classmates'},
  uz:{title:'Arqon tortish',lede:'Sizning jamoangiz raqibga qarshi, o\'rtada bitta arqon. Har bir javob tortadi.',
      rules:['Hamma bir xil savolga javob beradi. <b>To\'g\'ri javob arqonni 1 qadam sizga tortadi.</b>','<b>Xato javob arqonni 2 qadam raqib tomonga tortadi.</b> "Bilmayman" hech narsa qilmaydi, shuning uchun jamoa uchun taxmin qilmang.',`Bayroqni ${GOAL} qadam o\'z tomoningizga torting yoki ${QUESTIONS} savoldan keyin oldinda bo\'ling.`],
      start:'Arqonni ushlash',teamA:'Jamoangiz',teamB:'Raqiblar',you:'Siz',means:'Qaysi so\'z ma\'nosi',meaning:'Bu so\'z nimani anglatadi?',read:'Avval o\'qing…',
      net:n=>n>0?`Jamoangiz ${n} qadam tortdi`:n<0?`Raqiblar ${-n} qadam tortdi`:'O\'zgarish yo\'q',was:w=>`Javob: ${w}`,
      win:'Jamoangiz yutdi',draw:'Teng: hech kim siljimadi',lose:'Bu safar raqiblar yutdi',stCoins:'tanga',stRight:'to\'g\'ri javoblaringiz',stPull:'sizning tortishingiz',
      noBonus:`Jamoa bonusi uchun o\'zingiz ${MIN_RIGHT_FOR_BONUS} ta to\'g\'ri javob berishingiz kerak`,praise:n=>`Ketma-ket ${n} ta to\'g\'ri. Arqon buni sezdi.`,
      sim:'Mashq jamoalari · saytda bular sinfdoshlaringiz'}
};

let G=null, T=null, timers=[];
const later=(fn,ms)=>{ const id=setTimeout(fn,ms); timers.push(id); return id };
const clearAll=()=>{ timers.forEach(clearTimeout); timers=[] };

function newRound(preview){
  clearAll();
  const R=K.room({size:TEAM*2,you:T.you});
  const A=R.players.slice(0,TEAM), B=R.players.slice(TEAM);
  G={R,A,B,eng:K.engine(K.words),pos:0,q:0,coins:0,right:0,streak:0,myPull:0,preview:!!preview,over:false,Q:null};
  $('teamA').textContent=T.teamA; $('teamB').textContent=T.teamB;
  $('sideA').innerHTML=A.slice().reverse().map(p=>`<span class="pp${p.me?' me':''}" data-p="${p.id}">${esc(p.name[0])}<i></i></span>`).join('');
  $('sideB').innerHTML=B.map(p=>`<span class="pp" data-p="${p.id}">${esc(p.name[0])}<i></i></span>`).join('');
  rope(); $('coinTxt').textContent=0;
  if(preview){ ask(true); return }
  K.banner(T.title,T.sim); later(next,1600);
}
function rope(){ $('rope').style.transform=`translateX(${G.pos/GOAL*18}%)`; $('qChip').textContent=`${Math.max(1,G.q)}/${QUESTIONS}` }
function next(){
  if(G.over) return;
  if(Math.abs(G.pos)>=GOAL||G.q>=QUESTIONS) return finish();
  G.q++; rope(); ask(false);
}
function ask(preview){
  const w=G.eng.next(1+Math.floor(G.q/5)), byMeaning=G.q%2===1;
  G.Q={w,byMeaning,opts:K.options(w,K.words),mine:null,bots:{},done:false};
  $('ask').textContent=byMeaning?T.means:T.meaning; $('def').textContent=byMeaning?w.d:w.w;
  $('prompt').classList.remove('ok'); $('badge').hidden=true; $('note').textContent=T.read; $('idkBtn').disabled=false;
  $('opts').className='opts wait'+(byMeaning?'':' def');
  $('opts').innerHTML=G.Q.opts.map((o,i)=>`<button class="opt" data-i="${i}">${esc(byMeaning?o.w:o.d)}</button>`).join('');
  document.querySelectorAll('.pp i').forEach(i=>{ i.className=''; i.textContent='' });
  if(preview) return;
  later(()=>{
    $('opts').classList.remove('wait'); $('note').textContent='';
    const tm=$('timer'); tm.style.setProperty('--ms',LIMIT+'ms'); tm.classList.remove('run'); void tm.offsetWidth; tm.classList.add('run');
    G.R.players.filter(p=>!p.me).forEach(p=>{ const b=G.R.bot(p,w,TIER); later(()=>{ if(G.Q.done) return; G.Q.bots[p.id]=b.ok?'right':'wrong'; mark(p.id,'·',''); check() },Math.min(b.t,LIMIT-300)) });
    later(resolve,LIMIT);
  },READ_MS);
}
function mark(id,txt,cls){ const i=document.querySelector(`.pp[data-p="${id}"] i`); if(!i) return; i.textContent=txt; i.className='show'+(cls?' '+cls:'') }
$('opts').addEventListener('click',e=>{
  const b=e.target.closest('.opt'); const Q=G&&G.Q; if(!b||!Q||G.preview||Q.done||Q.mine||$('opts').classList.contains('wait')) return;
  const o=Q.opts[+b.dataset.i]; Q.mine={r:o.id===Q.w.id?'right':'wrong',i:+b.dataset.i};
  b.classList.add('sel'); $('opts').classList.add('locked'); SFX.tap(); $('idkBtn').disabled=true; mark('me','·',''); check();
});
$('idkBtn').addEventListener('click',()=>{ const Q=G&&G.Q; if(!Q||G.preview||Q.done||Q.mine||$('opts').classList.contains('wait')) return; Q.mine={r:'pass'}; $('opts').classList.add('locked'); $('idkBtn').disabled=true; mark('me','–',''); check() });
function check(){ const Q=G.Q; if(Q.mine&&Object.keys(Q.bots).length===TEAM*2-1) later(resolve,400) }
function resolve(){
  const Q=G.Q; if(!Q||Q.done) return; Q.done=true; clearAll(); $('timer').classList.remove('run');
  const mine=Q.mine?Q.mine.r:'none';
  G.eng.submit(Q.w.id,mine==='right','weak');
  const res={me:mine,...Q.bots};
  let a=0,b=0;
  G.A.forEach(p=>{ const r=res[p.id]||'none'; a+=PULL[r]; mark(p.id,r==='right'?'✓':r==='wrong'?'✗':'–',r==='right'?'ok':r==='wrong'?'no':'') });
  G.B.forEach(p=>{ const r=res[p.id]||'none'; b+=PULL[r]; mark(p.id,r==='right'?'✓':r==='wrong'?'✗':'–',r==='right'?'ok':r==='wrong'?'no':'') });
  const net=a-b; G.myPull+=PULL[mine];
  G.pos=Math.max(-GOAL,Math.min(GOAL,G.pos-net));   // negative = towards your side (left)
  const btns=[...$('opts').children], ri=Q.opts.findIndex(x=>x.id===Q.w.id);
  if(mine==='right'){ btns[Q.mine.i].classList.remove('sel'); btns[Q.mine.i].classList.add('right'); $('prompt').classList.add('ok'); G.right++; G.streak++;
    const c=COIN_RIGHT*TIER; G.coins+=c; $('coinTxt').textContent=G.coins; SFX.right(G.streak); later(()=>SFX.coin(),150); if(G.streak===4) K.doni(T.praise(G.streak)) }
  else { G.streak=0; btns[ri].classList.add('reveal'); if(mine==='wrong'){ btns[Q.mine.i].classList.add('dim'); SFX.wrong() } }
  K.badge($('badge'),mine==='right'?T.net(net):T.was(Q.w.w)+' · '+T.net(net),net>0,1700);
  const rp=$('rope'); rp.classList.toggle('heave',net>0); rp.classList.toggle('heaveB',net<0);
  noise(.25,{v:.18,f:net>0?700:300}); rope();
  later(()=>{ rp.classList.remove('heave','heaveB'); next() },2100);
}
function finish(){
  G.over=true; clearAll();
  const won=G.pos<0, draw=G.pos===0, bonus=won&&G.right>=MIN_RIGHT_FOR_BONUS;
  if(bonus) G.coins+=WIN_BONUS*TIER;
  won?SFX.win():SFX.end();
  K.end({title:draw?T.draw:won?T.win:T.lose,stats:[{v:G.coins,l:T.stCoins},{v:G.right,l:T.stRight},{v:(G.myPull>0?'+':'')+G.myPull,l:T.stPull}],
    extra:won&&!bonus?`<p class="mini">${esc(T.noBonus)}</p>`:'',
    results:G.eng.results(),payload:{game:'tug-of-war',tier:TIER,coins:G.coins,mode:G.R.mode,won}});
}
K.setup({text,onText:t=>{ T=t; if(G){ $('teamA').textContent=T.teamA; $('teamB').textContent=T.teamB } },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

