royale.js:
/* ═════════ Word Royale (last one standing) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const PLAYERS = 12, HEARTS = 4, MAX_Q = 16;
// the circle closes: phase 1 taps (weak), phase 2 context (medium), phase 3 typed (strong). Tier = phase.
const PHASE_AT = [1,5,9];
const LIMIT = {1:11000,2:13000,3:25000}, READ_MS = 800;
const LOSS = {wrong:2, pass:1, none:1};   // a wrong answer costs two hearts, "I don't know" one: never guess
const COIN_RIGHT = 2, PLACE = [10,6,4];  // times the phase tier; placement bonus times 2
const SPECTATOR_RATE = .5;               // after you are out you keep training for half coins

const text = {
  en:{title:'Word Royale',lede:`${PLAYERS} players, ${HEARTS} hearts each. The circle closes as the questions get harder. Be the last one standing.`,
      rules:['<b>Wrong costs 2 hearts. "I don\'t know" costs 1.</b> A guess is the worst choice.','The circle closes: first tap answers, then words in sentences, then you type the word.','Out early? Keep answering while you watch: your words still count and you still earn coins.'],
      start:'Drop in',you:'You',p1:'Tap round',p2:'Context round',p3:'Typing round',q:(n)=>`Question ${n}`,means:'Which word means',fits:'Which word fits?',typeAsk:'Type the word that means',type:'Type the word',go:'Go',
      read:'Read first…',alive:n=>`${n} left`,circle:'The circle closes',out:'You are out',outSub:'Keep answering: your words still count',
      lost:n=>`−${n} ${n>1?'hearts':'heart'}`,was:w=>`It was: ${w}`,ok:c=>`Right · +${c}`,spect:'Training while you watch',
      win:'Last one standing!',place:n=>`You finished #${n}`,shared:'Survivors share the crown',
      stCoins:'coins',stPlace:'place',stRight:'right answers',praise:'Typed in the final circle. Ice cold.',sim:'Practice lobby · on the site these are your classmates'},
  uz:{title:'So\'z Royale',lede:`${PLAYERS} o\'yinchi, har birida ${HEARTS} ta yurak. Savollar qiyinlashgani sari doira torayadi. Oxirgi qolgan bo\'ling.`,
      rules:['<b>Xato 2 ta yurak oladi. "Bilmayman" 1 ta.</b> Taxmin eng yomon tanlov.','Doira torayadi: avval bosib javob berasiz, keyin gapdagi so\'zlar, keyin so\'zni yozasiz.','Erta chiqdingizmi? Kuzatib turib javob berishda davom eting: so\'zlaringiz hisoblanadi va tanga olasiz.'],
      start:'Kirish',you:'Siz',p1:'Bosish raundi',p2:'Gap raundi',p3:'Yozish raundi',q:(n)=>`${n}-savol`,means:'Qaysi so\'z ma\'nosi',fits:'Qaysi so\'z mos keladi?',typeAsk:'Ma\'nosiga qarab so\'zni yozing',type:'So\'zni yozing',go:'Yuborish',
      read:'Avval o\'qing…',alive:n=>`${n} qoldi`,circle:'Doira torayapti',out:'Siz chiqdingiz',outSub:'Javob berishda davom eting: so\'zlaringiz hisoblanadi',
      lost:n=>`−${n} yurak`,was:w=>`Javob: ${w}`,ok:c=>`To'g'ri · +${c}`,spect:'Kuzatib turib mashq qilyapsiz',
      win:'Oxirgi qolgan siz!',place:n=>`Siz ${n}-o'rinni egalladingiz`,shared:'Qolganlar tojni bo\'lishadi',
      stCoins:'tanga',stPlace:'o\'rin',stRight:'to\'g\'ri javoblar',praise:'Oxirgi doirada yozdingiz. Juda sovuqqon.',sim:'Mashq xonasi · saytda bular sinfdoshlaringiz'}
};

let G=null, T=null, timers=[];
const later=(fn,ms)=>{ const id=setTimeout(fn,ms); timers.push(id); return id };
const clearAll=()=>{ timers.forEach(clearTimeout); timers=[] };
const phaseOf=q=>q>=PHASE_AT[2]?3:q>=PHASE_AT[1]?2:1;

function newRound(preview){
  clearAll();
  const R=K.room({size:PLAYERS,you:T.you});
  R.players.forEach(p=>{ p.hp=HEARTS; p.out=0 });
  G={R,me:R.players[0],eng:K.engine(K.words),q:0,coins:0,right:0,outOrder:[],preview:!!preview,over:false,Q:null,phase:1};
  dots(); K.hearts($('lives'),HEARTS,HEARTS); $('coinTxt').textContent=0; setPhase(1);
  if(preview){ ask(true); return }
  K.banner(T.title,T.sim); later(next,1600);
}
function dots(){
  const n=G.R.players.length;
  $('dots').innerHTML=G.R.players.map((p,i)=>{ const a=i/n*Math.PI*2-Math.PI/2; return `<span class="dot${p.me?' me':''}" data-p="${p.id}" style="left:${50+40*Math.cos(a)}%;top:${50+40*Math.sin(a)}%">${esc(p.name[0])}</span>` }).join('');
}
const alive=()=>G.R.players.filter(p=>!p.out);
function setPhase(ph){
  G.phase=ph; document.body.classList.toggle('p2',ph===2); document.body.classList.toggle('p3',ph===3);
  $('phase').textContent=T['p'+ph]; $('zone').style.setProperty('--z',[0,92,70,50][ph]+'%');
}
function next(){
  if(G.over) return;
  const left=alive();
  if(left.length<=1||G.q>=MAX_Q) return finish();
  G.q++; const ph=phaseOf(G.q);
  if(ph!==G.phase){ setPhase(ph); K.banner(T.circle,T['p'+ph]); noise(.6,{v:.2,f:300,type:'lowpass'}); later(()=>ask(false),1600); }
  else ask(false);
}
function ask(preview){
  const ph=G.phase, w=G.eng.next(ph);
  const ctx=ph===2&&!!w.s;
  G.Q={w,ph,ctx,opts:ph<3?K.options(w,K.words):null,done:false,mine:null,first:true};
  $('qNum').textContent=T.q(Math.max(1,G.q)); $('aliveChip').textContent=T.alive(alive().length);
  $('ask').textContent=ph===3?T.typeAsk:ctx?T.fits:T.means;
  $('def').innerHTML=ctx?esc(w.s).replace('___','<u>&nbsp;?&nbsp;</u>'):esc(w.d)+(ph===3?` <small>(${(w.f||w.w).length})</small>`:'');
  $('prompt').classList.remove('ok'); $('badge').hidden=true; $('idkBtn').disabled=false;
  $('note').textContent=G.me.out?T.spect:T.read;
  if(ph<3){
    $('typer').hidden=true; $('opts').hidden=false; $('opts').className='opts wait';
    $('opts').innerHTML=G.Q.opts.map((o,i)=>`<button class="opt" data-i="${i}">${esc(o.w)}</button>`).join('');
  } else { $('opts').hidden=true; $('typer').hidden=false; $('inp').value=''; $('inp').disabled=false; $('inp').placeholder=T.type; $('goBtn').textContent=T.go }
  if(preview) return;
  later(()=>{
    $('opts').classList.remove('wait'); if(!G.me.out) $('note').textContent='';
    if(ph===3) $('inp').focus();
    const tm=$('timer'); tm.style.setProperty('--ms',LIMIT[ph]+'ms'); tm.classList.remove('run'); void tm.offsetWidth; tm.classList.add('run');
    later(resolve,LIMIT[ph]);
  },READ_MS);
}
$('opts').addEventListener('click',e=>{
  const b=e.target.closest('.opt'); const Q=G&&G.Q; if(!b||!Q||G.preview||Q.done||Q.mine||$('opts').classList.contains('wait')) return;
  const o=Q.opts[+b.dataset.i]; Q.mine={r:o.id===Q.w.id?'right':'wrong',i:+b.dataset.i};
  b.classList.add('sel'); $('opts').classList.add('locked'); SFX.tap(); $('idkBtn').disabled=true; later(resolve,500);
});
$('typer').addEventListener('submit',e=>{
  e.preventDefault(); const Q=G&&G.Q; if(!Q||Q.done||Q.mine||Q.ph!==3||G.preview) return;
  if(!K.norm($('inp').value)) return;
  const r=K.judge($('inp').value,Q.w);
  Q.mine={r:r?'right':'wrong',close:r==='close'}; $('inp').disabled=true; $('idkBtn').disabled=true;
  if(!r){ const t=$('typer'); t.classList.remove('shake'); void t.offsetWidth; t.classList.add('shake') }
  later(resolve,400);
});
$('idkBtn').addEventListener('click',()=>{ const Q=G&&G.Q; if(!Q||G.preview||Q.done||Q.mine) return; Q.mine={r:'pass'}; $('opts').classList.add('locked'); $('inp').disabled=true; $('idkBtn').disabled=true; later(resolve,300) });

function resolve(){
  const Q=G.Q; if(!Q||Q.done) return; Q.done=true; clearAll(); $('timer').classList.remove('run');
  const mine=Q.mine?Q.mine.r:'none';
  G.eng.submit(Q.w.id,mine==='right',Q.ph===3?(Q.mine&&Q.mine.close?'medium':'strong'):Q.ph===2&&Q.ctx?'medium':'weak');
  // everyone still in the circle answers; bots that miss either pass or answer wrong
  G.R.players.filter(p=>!p.me&&!p.out).forEach(p=>{ const b=G.R.bot(p,Q.w,Q.ph); if(!b.ok) hurt(p,K.rng()<.5?'wrong':'pass') });
  if(!G.me.out&&mine!=='right') hurt(G.me,mine);
  const btns=Q.opts?[...$('opts').children]:[], ri=Q.opts?Q.opts.findIndex(x=>x.id===Q.w.id):-1;
  if(mine==='right'){
    const c=Math.round(COIN_RIGHT*Q.ph*(G.me.out?SPECTATOR_RATE:1)); G.coins+=c; G.right++; $('coinTxt').textContent=G.coins;
    if(Q.opts){ btns[Q.mine.i].classList.remove('sel'); btns[Q.mine.i].classList.add('right') }
    $('prompt').classList.add('ok'); SFX.right(G.right); later(()=>SFX.coin(),150); K.badge($('badge'),T.ok(c),true,1300);
    if(Q.ph===3&&!G.me.out&&alive().length<=4) K.doni(T.praise);
  } else {
    if(Q.opts){ btns[ri].classList.add('reveal'); if(Q.mine&&Q.mine.i!=null) btns[Q.mine.i].classList.add('dim') }
    K.badge($('badge'),(G.me.out?'':T.lost(LOSS[mine])+' · ')+T.was(Q.w.w),false,1800); if(mine==='wrong') SFX.wrong();
  }
  K.hearts($('lives'),G.me.hp,HEARTS); $('aliveChip').textContent=T.alive(alive().length);
  if(G.me.out===G.q){ later(()=>{ K.banner(T.out,T.outSub); SFX.lose() },700) }
  later(next,G.me.out===G.q?2900:2000);
}
function hurt(p,kind){
  p.hp=Math.max(0,p.hp-LOSS[kind]);
  const d=document.querySelector(`.dot[data-p="${p.id}"]`); if(d){ d.classList.remove('hit'); void d.offsetWidth; d.classList.add('hit') }
  if(p.hp<=0&&!p.out){ p.out=G.q; G.outOrder.push(p); if(d) later(()=>d.classList.add('out'),400) }
}
function finish(){
  G.over=true; clearAll(); $('inp').blur();
  const left=alive();
  // place: survivors share 1st; then reverse order of elimination
  let place = !G.me.out ? 1 : left.length + (G.outOrder.length - G.outOrder.indexOf(G.me));
  if(place<=3){ G.coins+=PLACE[place-1]*2 }
  place===1?SFX.win():SFX.end();
  const title=!G.me.out?(left.length===1?T.win:T.shared):T.place(place);
  K.end({title,stats:[{v:G.coins,l:T.stCoins},{v:'#'+place,l:T.stPlace},{v:G.right,l:T.stRight}],
    results:G.eng.results(),payload:{game:'word-royale',tier:'1-3',coins:G.coins,mode:G.R.mode,place}});
  document.body.classList.remove('p2','p3');
}
K.setup({text,onText:t=>{ T=t; if(G) $('phase').textContent=T['p'+G.phase] },preview:()=>{ T=K.T; document.body.classList.remove('p2','p3'); newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();

heist.css:
/* The Vault Heist: co-op typed recall; Recall orange stage with a night-time vault */
.vault{position:relative;flex:none;border-radius:22px;padding:12px;background:radial-gradient(120% 120% at 50% 0%,#1F2A48,#0A0F1F 75%);color:#fff;display:grid;gap:10px;overflow:hidden}
.vault.alert{animation:alert 1s ease}
@keyframes alert{30%{box-shadow:inset 0 0 0 3px #FFB020,inset 0 0 40px rgba(255,176,32,.5)}}
.locks{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.lock{position:relative;border-radius:16px;background:#151D35;padding:8px 6px;display:grid;justify-items:center;gap:6px;box-shadow:inset 0 0 0 2px #2A3760;transition:background .4s,box-shadow .4s}
.lock.cur{box-shadow:inset 0 0 0 2px #F5B700}
.lock.open{background:#2A2208;box-shadow:inset 0 0 0 2px #F5B700,0 0 18px rgba(245,183,0,.35)}
.dial{width:44px;height:44px;border-radius:50%;background:conic-gradient(#F5B700 var(--a,0deg),#2A3760 0);display:grid;place-items:center;transition:--a .4s}
.dial b{width:32px;height:32px;border-radius:50%;background:#0A0F1F;display:grid;place-items:center;font:900 13px var(--display);color:#F5B700}
.lock.open .dial b::before{content:"✓"}
.pins{display:grid;grid-template-columns:repeat(4,1fr);gap:3px;width:100%}
.pins i{height:6px;border-radius:3px;background:#2A3760}
.pins i.on{background:#F5B700}
.pins i.me{background:#3B4C85}
.pins i.me.on{background:#FFE27A}
.crew{display:flex;justify-content:space-between;gap:6px}
.mate{flex:1;min-width:0;display:flex;align-items:center;gap:6px;background:#151D35;border-radius:12px;padding:5px 7px}
.mate .av{width:24px;height:24px;border-radius:50%;flex:none;display:grid;place-items:center;font:900 11px var(--display);background:#fff;color:#0A0F1F}
.mate.me .av{background:#F5B700}
.mate span{font:700 11px var(--display);opacity:.85;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mate.busy .av{animation:busy 1.2s ease-in-out infinite}
@keyframes busy{50%{transform:rotate(25deg)}}
.alarm{display:flex;align-items:center;gap:8px;font:800 11px var(--display);text-transform:uppercase;letter-spacing:.08em;opacity:.9}
.abar{flex:1;height:8px;border-radius:9px;background:#151D35;overflow:hidden}
.abar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#F5B700,#FF8A1E,#FF5FA2);transition:width .5s}
@media (max-width:380px){.mate span{display:none}.mate{justify-content:center}}
@media (max-height:640px){.dial{width:36px;height:36px}.dial b{width:26px;height:26px}}
@media (prefers-reduced-motion:reduce){.vault.alert,.mate.busy .av{animation:none}}

heist.js:
/* ═════════ The Vault Heist (co-op, typed recall) ═════════ */
(() => {
'use strict';
const {$,esc,SFX,tone,noise} = K;
const TIER = 3;               // hidden tier: typed from meaning (strong evidence)
const CREW = 4, LOCKS = 3, PINS = 3;   // each lock needs 3 words from every crew member
const TIME = 180, LOCK_TIME = 25;      // seconds; each opened lock buys more time
// the alarm: a wrong typed word +20, "I don't know" +10, a crewmate's miss +12. 100 = caught.
const ALARM = {wrong:20, pass:10, bot:12};
const PAY = {solo:3, helped:1}, LOOT = 4, FULL = 6;   // times TIER

const text = {
  en:{title:'The Vault Heist',lede:'Four of you, three locks, one alarm. Every crew member types their own words to turn the tumblers.',
      rules:['Type the word from its meaning to turn your tumbler. A lock opens when the <b>whole crew</b> has turned theirs.','<b>Wrong +20 alarm, "I don\'t know" +10.</b> At 100 the guards arrive.','Stuck? <b>Ask the crew</b> for the first letters: the tumbler still turns, for less loot.'],
      start:'Start the heist',alarmL:'Alarm',askCrew:'Ask the crew',type:'Type the word',go:'Turn',
      ask:n=>`Lock ${n} · type the word that means`,you:'You',cracking:'cracking…',done:'done',
      opened:n=>`Lock ${n} open`,openedSub:t=>`+${t}s on the clock`,ok:c=>`Click · +${c}`,miss:'The tumbler stuck · alarm +20',
      passed:w=>`The crew turned it: ${w} · alarm +10`,mateMiss:n=>`${n} slipped · alarm +12`,hint:'The crew whispers the first letters',
      win:'Vault emptied!',caught:'The alarm went off',time:'Out of time',part:n=>`You escaped with ${n} of ${LOCKS} locks`,
      stCoins:'coins',stLocks:'locks opened',stSolo:'words alone',praise:'Three words, no help, no alarm. Smooth.',sim:'Practice crew · on the site this is your team'},
  uz:{title:'Seyf o\'g\'irligi',lede:'To\'rt kishi, uchta qulf, bitta signal. Har bir a\'zo mexanizmni burish uchun o\'z so\'zlarini yozadi.',
      rules:['Mexanizmni burish uchun so\'zni ma\'nosiga qarab yozing. <b>Butun jamoa</b> o\'z qismini bursa, qulf ochiladi.','<b>Xato +20 signal, "Bilmayman" +10.</b> 100 bo\'lsa, qo\'riqchilar keladi.','Qiynaldingizmi? Birinchi harflar uchun <b>jamoadan so\'rang</b>: mexanizm buriladi, lekin o\'lja kamroq.'],
      start:'Boshlash',alarmL:'Signal',askCrew:'Jamoadan so\'rash',type:'So\'zni yozing',go:'Burish',
      ask:n=>`${n}-qulf · ma'nosiga qarab so'zni yozing`,you:'Siz',cracking:'ochyapti…',done:'tayyor',
      opened:n=>`${n}-qulf ochildi`,openedSub:t=>`Vaqtga +${t} soniya`,ok:c=>`Chiq · +${c}`,miss:'Mexanizm tiqilib qoldi · signal +20',
      passed:w=>`Jamoa burib berdi: ${w} · signal +10`,mateMiss:n=>`${n} adashdi · signal +12`,hint:'Jamoa birinchi harflarni pichirladi',
      win:'Seyf bo\'shatildi!',caught:'Signal yangradi',time:'Vaqt tugadi',part:n=>`${LOCKS} ta qulfdan ${n} tasi bilan qochdingiz`,
      stCoins:'tanga',stLocks:'ochilgan qulflar',stSolo:'yordamsiz so\'zlar',praise:'Uchta so\'z, yordamsiz, signalsiz. Silliq.',sim:'Mashq jamoasi · saytda bu sizning jamoangiz'}
};

let G=null, T=null, timers=[], clock=0;
const later=(fn,ms)=>{ const id=setTimeout(fn,ms); timers.push(id); return id };
const clearAll=()=>{ timers.forEach(clearTimeout); timers=[]; clearInterval(clock) };

function newRound(preview){
  clearAll();
  const R=K.room({size:CREW,you:T.you});
  G={R,crew:R.players,eng:K.engine(K.words),lock:0,pins:R.players.map(()=>0),alarm:0,time:TIME,coins:0,solo:0,soloRun:0,opened:0,preview:!!preview,over:false,W:null};
  $('locks').innerHTML=[...Array(LOCKS)].map((_,i)=>`<div class="lock" data-l="${i}"><div class="dial"><b>${i+1}</b></div><div class="pins">${[...Array(CREW*PINS)].map((_,j)=>`<i class="${j%CREW===0?'me':''}"></i>`).join('')}</div></div>`).join('');
  $('crew').innerHTML=G.crew.map(p=>`<div class="mate${p.me?' me':''}" data-p="${p.id}"><span class="av">${esc(p.name[0])}</span><span>${esc(p.name)}</span></div>`).join('');
  $('coinTxt').textContent=0; alarm(0); drawLock(); tick();
  $('inp').placeholder=T.type; $('goBtn').textContent=T.go;
  nextWord(true);
  if(preview) return;
  K.banner(T.title,T.sim);
  later(()=>{ clock=setInterval(()=>{ if(G.over) return; G.time--; tick(); if(G.time<=0) finish('time') },1000); G.crew.filter(p=>!p.me).forEach(work); $('inp').focus() },1500);
}
function tick(){ const m=Math.floor(Math.max(0,G.time)/60), s=Math.max(0,G.time)%60; $('clockChip').textContent=`${m}:${String(s).padStart(2,'0')}`; $('lockChip').textContent=`${Math.min(G.lock+1,LOCKS)}/${LOCKS}` }
function alarm(add){
  G.alarm=Math.min(100,G.alarm+add); $('alarm').style.width=G.alarm+'%';
  if(add){ const v=$('vault'); v.classList.remove('alert'); void v.offsetWidth; v.classList.add('alert'); noise(.3,{v:.15,f:1800,q:4}); tone(880,.12,{type:'square',v:.03}); tone(660,.12,{type:'square',v:.03,at:.14}) }
  if(G.alarm>=100&&!G.over) later(()=>finish('caught'),600);
}
function drawLock(){
  document.querySelectorAll('.lock').forEach((el,i)=>{
    el.classList.toggle('cur',i===G.lock&&!G.over); el.classList.toggle('open',i<G.lock);
    const pins=[...el.querySelectorAll('.pins i')];
    pins.forEach((p,j)=>{ const who=j%CREW, n=Math.floor(j/CREW); p.classList.toggle('on',i<G.lock||(i===G.lock&&G.pins[who]>n)) });
    const done=i<G.lock?CREW*PINS:i===G.lock?G.pins.reduce((a,b)=>a+b,0):0;
    el.querySelector('.dial').style.setProperty('--a',(done/(CREW*PINS)*360)+'deg');
  });
  G.crew.forEach((p,k)=>{ const el=document.querySelector(`.mate[data-p="${p.id}"]`); if(!el) return; el.classList.toggle('busy',!p.me&&G.pins[k]<PINS&&!G.over) });
}
/* a crewmate works on their own tumblers; a miss raises the alarm and they try again */
function work(p){
  const k=G.crew.indexOf(p);
  if(G.over||G.pins[k]>=PINS) return;
  const b=G.R.bot(p,{diff:2},TIER);
  later(()=>{
    if(G.over) return;
    if(b.ok){ G.pins[k]++; tone(1200,.04,{type:'triangle',v:.04}); drawLock(); checkLock() }
    else { alarm(ALARM.bot); K.badge($('badge'),T.mateMiss(p.name),false,1300) }
    work(p);
  },b.t*1.8+1500);
}
function nextWord(first){
  if(G.pins[0]>=PINS){ $('inp').disabled=true; $('crewBtn').disabled=true; $('idkBtn').disabled=true; $('def').textContent='…'; $('note').textContent=T.cracking; return }
  const w=G.eng.next(Math.min(3,2+G.lock));
  G.W={w,tries:0,hint:false,first:true};
  $('ask').textContent=T.ask(G.lock+1); $('def').innerHTML=esc(w.d)+` <small>(${(w.f||w.w).length})</small>`;
  $('hintline').hidden=true; $('prompt').classList.remove('ok'); $('note').textContent='';
  $('inp').value=''; $('inp').disabled=false; $('crewBtn').disabled=true; $('idkBtn').disabled=false;
  if(!first) $('inp').focus();
}
$('typer').addEventListener('submit',e=>{
  e.preventDefault(); const W=G&&G.W; if(!W||G.over||G.preview||$('inp').disabled) return;
  const v=$('inp').value; if(!K.norm(v)) return;
  const r=K.judge(v,W.w);
  if(r){
    if(W.first) G.eng.submit(W.w.id,true,W.hint||r==='close'?'medium':'strong');
    const solo=!W.hint&&W.tries===0, c=(solo?PAY.solo:PAY.helped)*TIER; G.coins+=c; $('coinTxt').textContent=G.coins;
    if(solo){ G.solo++; G.soloRun++ } else G.soloRun=0;
    if(G.soloRun===3) K.doni(T.praise);
    $('prompt').classList.add('ok'); K.badge($('badge'),T.ok(c),true,1100); SFX.right(G.soloRun); later(()=>SFX.coin(),140);
    G.pins[0]++; drawLock(); $('inp').disabled=true;
    later(()=>{ checkLock(); if(!G.over) nextWord(false) },700);
    return;
  }
  if(W.first){ G.eng.submit(W.w.id,false); W.first=false }
  W.tries++; alarm(ALARM.wrong); K.badge($('badge'),T.miss,false,1300);
  const t=$('typer'); t.classList.remove('shake'); void t.offsetWidth; t.classList.add('shake'); SFX.wrong(); $('inp').select();
  $('crewBtn').disabled=W.hint;
});
$('crewBtn').addEventListener('click',()=>{
  const W=G&&G.W; if(!W||W.hint||G.over) return; W.hint=true; $('crewBtn').disabled=true;
  const f=W.w.f||W.w.w, n=Math.min(2,Math.max(1,f.length-3));
  const h=$('hintline'); h.textContent=f.slice(0,n).toUpperCase().split('').join(' ')+' '+'_ '.repeat(f.length-n).trim(); h.hidden=false;
  $('note').textContent=T.hint; tone(520,.1,{type:'triangle',v:.05}); $('inp').focus();
});
$('crewBtn').addEventListener('pointerdown',e=>{ if(document.activeElement===$('inp')) e.preventDefault() });
$('idkBtn').addEventListener('pointerdown',e=>{ if(document.activeElement===$('inp')) e.preventDefault() });
$('idkBtn').addEventListener('click',()=>{
  const W=G&&G.W; if(!W||G.over||G.preview||$('inp').disabled) return;
  if(W.first){ G.eng.submit(W.w.id,false); W.first=false }
  alarm(ALARM.pass); G.soloRun=0; K.badge($('badge'),T.passed(W.w.w),false,2000);
  $('inp').disabled=true; later(()=>{ if(!G.over) nextWord(false) },1800);   // the word returns later in the heist
});
function checkLock(){
  if(G.over||G.pins.some(n=>n<PINS)) return;
  G.lock++; G.opened++; G.time+=LOCK_TIME; G.coins+=LOOT*TIER; $('coinTxt').textContent=G.coins;
  [523,659,784,1047].forEach((f,i)=>tone(f,.15,{type:'triangle',v:.08,at:i*.07})); K.banner(T.opened(G.opened),T.openedSub(LOCK_TIME));
  if(G.lock>=LOCKS) return later(()=>finish('win'),900);
  G.pins=G.crew.map(()=>0); drawLock(); tick();
  later(()=>{ G.crew.filter(p=>!p.me).forEach(work); nextWord(false) },900);
}
function finish(why){
  if(G.over) return; G.over=true; clearAll(); $('inp').blur(); drawLock();
  if(why==='win'){ G.coins+=FULL*TIER; SFX.win() } else SFX.end();
  const title=why==='win'?T.win:(why==='caught'?T.caught:T.time)+' · '+T.part(G.opened);
  K.end({title,stats:[{v:G.coins,l:T.stCoins},{v:`${G.opened}/${LOCKS}`,l:T.stLocks},{v:G.solo,l:T.stSolo}],
    results:G.eng.results(),payload:{game:'vault-heist',tier:TIER,coins:G.coins,mode:G.R.mode,outcome:why}});
}
K.setup({text,onText:t=>{ T=t; $('inp').placeholder=T.type; $('goBtn').textContent=T.go },preview:()=>{ T=K.T; newRound(true) },start:()=>{ T=K.T; newRound(false) }});
})();
